INSERT INTO admins (email, password_hash) VALUES ('admin@ornaplant.com.mx', '$2y$12$PGNCUDee12zARkHoVl40DuUFIRtFJrSVOmL4HcGdU/8MeciV/gEWW')
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAB01L003', 'Arbol De La Abundancia', 'Portulacaria afra', 'suculenta', 'Es una suculenta originaria del sur de África con hojas carnosas que crece como un pequeño arbusto. Sus hojas son verdes y redondas, y la planta tiene forma de pequeño árbol. Es conocida por su simbolismo de buena suerte y prosperidad según el Feng Shui.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AAB01L003', 8, '["suculenta", "buena suerte", "feng shui", "interior", "fácil cuidado", "prosperidad", "popular"]', '["bolsa 1 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777095326/plantas/aab01l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAC03L003', 'Aralea Arboricola', 'Schefflera arboricola', 'interior', 'Planta de interior originaria de Taiwán, también conocida como árbol paraguas enano o cheflera. Sus hojas variegadas crecen en rosetas que asemejan pequeños paraguas, lo que le da su nombre común. Es una planta resistente y de rápido crecimiento muy popular en interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AAC03L003', 1, '["árbol paraguas", "variegada", "tropical", "fácil cuidado", "crecimiento rápido", "hojas brillantes", "popular"]', '["bolsa 3 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777095375/plantas/aac03l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAM04L006', 'Avelia Amarilla', 'Abelia x grandiflora ''Amarillo''', 'exterior', 'La Abelia ''Amarillo'' es un arbusto semi-perenne o perenne con follaje brillante que puede ser verde, amarillo o variegado, a menudo adquiriendo tonos bronce en invierno. Produce abundantes flores fragantes, en forma de campana, de color blanco a rosa pálido, desde el verano hasta el otoño. Es una planta de tamaño mediano, ideal para bordes o setos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AAM04L006', 0, '["arbusto", "ornamental", "follaje amarillo", "floración prolongada", "atrae polinizadores", "resistente a ciervos", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777131704/plantas/aam04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAM45L009', 'Acacia Bicapsularis', 'Senna bicapsularis (L.) Roxb.', 'exterior', 'Es un arbusto semiperenne que puede crecer hasta 3.5 metros de altura, con una copa extendida. Sus hojas son pinnadas con seis a ocho folíolos y produce abundantes flores amarillas brillantes en racimos, especialmente de otoño a invierno. El fruto es una vaina cilíndrica de color marrón.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AAM45L009', 1, '["arbusto", "flores amarillas", "semiperenne", "ornamental", "atrae polinizadores", "invasiva"]', '["bolsa 45 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777131937/plantas/aam45l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAR11P145', 'Aloe Arborecente Cosmos', 'Aloe arborescens', 'suculenta', 'El Aloe arborescens es una suculenta perenne grande y ramificada que puede crecer hasta 4 metros de altura. Sus hojas carnosas, de color verde a verde azulado y con pequeños dientes, se agrupan en rosetas al final de las ramas. En invierno, produce espectaculares flores tubulares de color rojo-anaranjado vibrante.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AAR11P145', 1, '["suculenta", "arbusto", "floración invernal", "bajo mantenimiento", "resistente a la sequía", "medicinal"]', '["maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777131955/plantas/aar11p145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAT06L003', 'Aralea Arboricola Trinet', 'Schefflera arboricola ''Trinette''', 'ornamental', 'La Schefflera arboricola ''Trinette'' es una planta paraguas enana variegada, caracterizada por sus hojas verdes brillantes con distintivas manchas de color amarillo cremoso. Es un arbusto compacto y adaptable, muy apreciado para embellecer tanto interiores como paisajes tropicales. Esta planta puede alcanzar una altura de aproximadamente 0.8 a 1.8 metros.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AAT06L003', 0, '["planta de interior", "planta de exterior", "variegada", "fácil cuidado", "arbusto", "tropical", "popular"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777131976/plantas/aat06l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAV03L003', 'Aralea Arboricola Verde', 'Schefflera arboricola', 'interior', 'La Schefflera arboricola, también conocida como Cheflera o Árbol paraguas enano, es un arbusto perennifolio popular como planta de interior. Se caracteriza por sus hojas palmeadas y brillantes, que se agrupan de forma similar a un paraguas. Es apreciada por su exuberante follaje tropical y su fácil cuidado.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AAV03L003', 1, '["planta de interior", "árbol paraguas", "cheflera", "follaje verde", "fácil cuidado", "tropical", "popular"]', '["bolsa 3 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777131997/plantas/aav03l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AAZ20L009', 'Agave Azul', 'Agave tequilana Weber var. azul', 'suculenta', 'El Agave Azul es una planta suculenta perenne, reconocida por sus hojas gruesas y carnosas de color azul-verdoso dispuestas en forma de roseta, con puntas afiladas y márgenes espinosos. Es la materia prima principal para la producción de tequila y puede alcanzar hasta 2.5 metros de altura.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AAZ20L009', 0, '["suculenta", "tequila", "ornamental", "bajo mantenimiento", "exterior", "medicinal"]', '["bolsa 20 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132019/plantas/aaz20l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ABB04L077', 'Arandano Blue Berry', 'Vaccinium corymbosum', 'exterior', 'El arándano azul es un arbusto caducifolio que produce frutos dulces y redondos de color azul intenso. Es apreciado tanto por sus bayas comestibles como por su valor ornamental, con flores delicadas y follaje otoñal rojizo.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'ABB04L077', 0, '["arbusto", "frutal", "bayas", "acidófila", "comestible", "ornamental", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132035/plantas/abb04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ACA01L124', 'Acanto', 'Acanthus mollis', 'ornamental', 'El Acanto (Acanthus mollis) es una planta herbácea perenne, muy apreciada en jardinería por sus grandes hojas lobuladas y sus elegantes espigas florales. Originaria de la región mediterránea, puede alcanzar hasta un metro de altura y destaca por su fácil mantenimiento. Es ideal para aportar textura y volumen en jardines de sombra parcial.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ACA01L124', 0, '["Planta ornamental", "Hojas grandes", "Jardín mediterráneo", "Bajo mantenimiento", "Perenne", "Sombra parcial", "popular"]', '["bolsa 1 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132054/plantas/aca01l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ACA10L145', 'Aloe Camperi', 'Aloe camperi Schweinf.', 'suculenta', 'Aloe camperi es una planta suculenta perenne que forma colonias de rosetas de hojas verdes estrechas y recurvadas con bordes dentados. Produce inflorescencias ramificadas con flores tubulares de color albaricoque, salmón o amarillo que florecen a finales de primavera. Es una planta de bajo mantenimiento, tolerante a la sequía y al calor.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ACA10L145', 0, '["suculenta", "exterior", "fácil cuidado", "tolerante a la sequía", "flores de primavera", "atrae colibríes", "medicinal"]', '["bolsa 10 litros", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132074/plantas/aca10l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ACH10P145', 'Aloe Chabaudii', 'Aloe chabaudii', 'suculenta', 'Es una planta suculenta perenne sin tallo, que forma rosetas de hojas de color verde grisáceo con márgenes dentados. Produce inflorescencias ramificadas con flores tubulares de color rosa coral o rojo anaranjado que aparecen en invierno. Se utiliza en jardines de rocalla y tiene propiedades medicinales.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ACH10P145', 0, '["suculenta", "exterior", "medicinal", "fácil cuidado", "floración invernal", "rocalla"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132096/plantas/ach10p145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ACO04L145', 'Aloe Cobre', 'Aloe (híbrido)', 'ornamental', 'Esta suculenta es un híbrido de Aloe que se caracteriza por sus flores de color naranja bronceado que adornan la planta en otoño e invierno. Posee hojas carnosas de color verde claro, típicas del género Aloe. Es una planta ornamental valorada por su vistosa floración.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ACO04L145', 0, '["suculenta", "ornamental", "floración invernal", "bajo mantenimiento", "resistente a la sequía", "tóxica para mascotas"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133560/plantas/aco04l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ADE03L001', 'Adelfa Enana Fiusha', 'Nerium oleander ''Nana''', 'ornamental', 'La Adelfa Enana Fiusha es un arbusto perenne de porte compacto y floración abundante. Sus hojas son alargadas y de color verde oscuro, y produce vistosas flores en tonos fucsia durante gran parte del año. Es una planta muy resistente y de bajo mantenimiento, ideal para exteriores.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ADE03L001', 0, '["arbusto", "perenne", "floración abundante", "resistente", "exterior", "mediterránea", "flores fucsia"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132148/plantas/ade03l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ADE03L009', 'Adelfa', 'Nerium oleander', 'ornamental', 'La adelfa es un arbusto perenne de hoja perenne que puede alcanzar hasta 6 metros de altura. Se caracteriza por sus vistosas flores de diversos colores, como rosas, blancas, rojas o amarillas, que florecen desde la primavera hasta el otoño. Es una planta muy resistente y adaptable a diferentes condiciones climáticas y de suelo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ADE03L009', 0, '["arbusto", "perenne", "flores vistosas", "resistente", "mediterránea", "venenosa", "popular"]', '["bolsa 3 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132168/plantas/ade03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ADE08L001', 'Adenium', 'Adenium obesum', 'suculenta', 'La Adenium obesum, conocida como Rosa del Desierto, es una suculenta arbustiva con un tallo basal grueso y abultado (cáudice) que almacena agua. Produce flores vistosas en forma de trompeta en tonos que van del rosa al rojo y blanco. Es una planta ornamental muy apreciada por su resistencia y belleza exótica, ideal para climas cálidos.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ADE08L001', 0, '["Rosa del Desierto", "arbusto", "floración", "desértica", "bonsái", "ornamental", "popular"]', '["bolsa 8 litros", "maceta negra 6 pulgadas", "maceta negra 8 pulgadas", "maceta negra 12 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132188/plantas/ade08l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ADI04P121', 'Arbol Del Dinero', 'Pachira aquatica', 'interior', 'La Pachira aquatica es un árbol tropical perenne, nativo de América Central y del Sur, conocido por sus hojas palmadas de color verde brillante y su tronco que a menudo se trenza. Es popular como planta de interior y se asocia con la buena suerte y la prosperidad en el Feng Shui.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ADI04P121', 2, '["Feng Shui", "prosperidad", "planta de interior", "follaje", "tronco trenzado", "fácil cuidado", "popular"]', '["maceta negra 4 pulgadas", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132205/plantas/adi04p121.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ADI11P145', 'Aloe Dieri', 'Aloe dyeri Schönland', 'suculenta', 'Esta aloe solitaria y sin tallo forma grandes rosetas de 1.2 a 1.5 metros de ancho con hojas de color verde amarillento oscuro y marcas lineales claras. En otoño, produce tallos ramificados de hasta 1.8 metros con flores tubulares de color salmón a rojo ladrillo. Es una de las aloes manchadas más grandes y robustas, originaria de Sudáfrica.', 'media sombra', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ADI11P145', 0, '["suculenta", "Sudáfrica", "ornamental", "resistente a la sequía", "planta de contenedor", "rocalla"]', '["maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132229/plantas/adi11p145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AEL08L006', 'Aralea Elegantisima', 'Plerandra elegantissima', 'ornamental', 'La Plerandra elegantissima, también conocida como falsa aralia, es un arbusto o árbol pequeño de hoja perenne originario de Nueva Caledonia. Se caracteriza por sus tallos delgados y un follaje delicado y parecido a un encaje, con hojas estrechas y dentadas que nacen de color cobre y maduran a un verde oscuro casi negro. Es muy apreciada como planta ornamental de interior por su aspecto elegante y estilizado.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AEL08L006', 0, '["planta de interior", "falsa aralia", "follaje decorativo", "tropical", "humedad alta", "elegante", "popular"]', '["bolsa 8 litros", "bolsa 20 litros", "bolsa 60 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132250/plantas/ael08l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AEN02L010', 'Agapando', 'Agapanthus africanus', 'ornamental', 'El Agapando es una planta herbácea perenne originaria de Sudáfrica, conocida por sus hojas alargadas y acintadas de color verde oscuro. Produce vistosas inflorescencias en umbelas esféricas, con flores que varían en tonos de violeta, azul o blanco, elevándose sobre tallos altos. Es una planta rizomatosa muy apreciada por su valor ornamental.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AEN02L010', 0, '["Flor del amor", "Lirio africano", "Planta perenne", "Jardín", "Flores azules", "Bajo mantenimiento", "popular"]', '["bolsa 2 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132274/plantas/aen02l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AGA01L125', 'Agazania', 'Gazania rigens', 'exterior', 'La Gazania es una planta herbácea perenne, a menudo cultivada como anual, conocida por sus grandes y vistosas flores parecidas a margaritas. Estas flores, en tonos de amarillo, naranja, rojo, rosa y blanco, se abren con el sol y se cierran por la noche o en días nublados. Es una planta de bajo crecimiento, ideal para cubrir suelos o decorar macetas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AGA01L125', 0, '["ornamental", "floración prolongada", "resistente sequía", "bajo mantenimiento", "planta tapizante", "atrae polinizadores", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132308/plantas/aga01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AGA50L157', 'Agave Americano', 'Agave americana L.', 'suculenta', 'El Agave americano es una planta perenne suculenta, acaule, con grandes hojas carnosas de color verde-azulado o grisáceo que forman una roseta basal. Sus hojas están bordeadas con espinas afiladas y terminan en una punta robusta. Esta planta florece una sola vez en su vida, produciendo un imponente tallo floral antes de morir.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AGA50L157', 0, '["ornamental", "exterior", "resistente a la sequía", "maguey", "pita", "monocárpica", "popular"]', '["bolsa 50 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132325/plantas/aga50l157.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AGI10P145', 'Agave Gipsofilam', 'Agave gypsophila', 'suculenta', 'La Agave gypsophila es una suculenta de tamaño pequeño a mediano que forma una roseta abierta de hojas carnosas, suaves y onduladas de color gris azulado, con pequeños dientes a lo largo de los márgenes. Puede alcanzar hasta 2 metros de diámetro y produce infrecuentemente flores amarillas en un tallo alto. Es apreciada por su valor ornamental y su resistencia a la sequía.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AGI10P145', 0, '["suculenta", "ornamental", "México", "hojas onduladas", "resistente a la sequía", "bajo mantenimiento"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132349/plantas/agi10p145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AGL06P168', 'Aglonema', 'Aglaonema', 'ornamental', 'La Aglaonema es un género de plantas herbáceas perennes, nativas de las selvas tropicales del sudeste asiático. Se caracteriza por su llamativo follaje con hojas lanceoladas u ovadas, que presentan una amplia gama de colores y patrones, incluyendo tonos de verde, plata, rojo y rosa. Es una planta de crecimiento lento que puede alcanzar entre 20 y 150 cm de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AGL06P168', 0, '["planta de interior", "follaje decorativo", "tropical", "baja luz", "fácil cuidado", "siempreviva china"]', '["maceta negra 6 pulgadas", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132364/plantas/agl06p168.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AHA06L115', 'Aguacate Hass', 'Persea americana ''Hass''', 'árbol', 'El aguacate Hass es un árbol perenne conocido por producir frutos de excelente calidad. Sus aguacates son de tamaño mediano, con una piel rugosa de color verde oscuro que se vuelve púrpura-negra al madurar, y una pulpa cremosa de sabor rico y a nuez. Es una variedad muy apreciada globalmente por su versatilidad culinaria y su alto contenido de aceite.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AHA06L115', 0, '["árbol frutal", "fruta comestible", "cultivo comercial", "perenne", "clima cálido", "piel rugosa", "popular"]', '["bolsa 6 litros", "bolsa 35 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132384/plantas/aha06l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AHI04L077', 'Amohena', 'Dieffenbachia amoena', 'ornamental', 'Es una planta tropical de la familia Araceae, conocida por sus grandes hojas verdes con llamativas manchas claras o variegaciones. Es una planta herbácea perenne con un tallo erguido y carnoso.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AHI04L077', 0, '["planta tropical", "hojas variegadas", "decorativa", "araceae", "venenosa", "interior", "popular"]', '["bolsa 4 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132399/plantas/ahi04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AHU04L129', 'Ahuehuete', 'Taxodium mucronatum', 'árbol', 'El Ahuehuete es un árbol majestuoso y longevo, capaz de alcanzar hasta 40 metros de altura y troncos de gran diámetro. Su nombre náhuatl significa "viejo del agua" o "anciano del río", haciendo referencia a su preferencia por crecer cerca de cuerpos de agua. Es el árbol nacional de México, valorado por su resistencia y adaptabilidad a diversas condiciones.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AHU04L129', 0, '["árbol nacional de México", "longevo", "ripario", "gran tamaño", "conífera", "resistente"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132420/plantas/ahu04l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AJE01L125', 'Ajenjo', 'Artemisia absinthium', 'medicinal', 'El ajenjo es una planta herbácea perenne con un rizoma leñoso, que alcanza entre 80 y 120 cm de altura y presenta una coloración verde plateada. Sus hojas aromáticas son de color gris plateado y sus pequeñas flores amarillas no tienen gran interés ornamental. Destaca por el brillo suave de su follaje, que aporta luz incluso en zonas secas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AJE01L125', 0, '["medicinal", "aromática", "perenne", "exterior", "resistente a la sequía", "follaje plateado", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132445/plantas/aje01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ALC10L009', 'Alcatraz', 'Zantedeschia aethiopica', 'ornamental', 'El Alcatraz, cuyo nombre científico es Zantedeschia aethiopica, es una planta herbácea perenne conocida por sus grandes hojas verdes en forma de flecha y sus distintivas flores en forma de trompeta, generalmente blancas con un espádice amarillo central. Puede alcanzar hasta un metro de altura y es muy apreciada por su valor ornamental y como flor de corte. Toda la planta es tóxica si se ingiere, tanto para humanos como para mascotas.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'ALC10L009', 0, '["flor de corte", "perenne", "hojas verdes", "flores blancas", "tóxica", "rizoma", "popular"]', '["bolsa 10 litros", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132464/plantas/alc10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ALM04L115', 'Almendro', 'Prunus dulcis', 'árbol', 'El almendro (Prunus dulcis) es un árbol caducifolio de la familia de las rosáceas, originario de Asia Central. Puede alcanzar entre 3 y 10 metros de altura y es apreciado por su vistosa floración blanca o rosada a finales del invierno, que anuncia la primavera. Produce un fruto comestible, la almendra, de gran valor comercial.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ALM04L115', 0, '["árbol frutal", "floración invernal", "fruto seco", "cultivo", "exterior", "resistente a la sequía"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132485/plantas/alm04l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ALO10L009', 'Alocasia Cuculata', 'Alocasia cucullata', 'ornamental', 'La Alocasia cucullata es una planta herbácea perenne conocida por sus distintivas hojas brillantes en forma de corazón, de color verde intenso, que emergen de tallos delgados y erguidos. Puede alcanzar hasta un metro de altura y es apreciada por su aspecto tropical y decorativo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ALO10L009', 0, '["tropical", "hojas verdes", "planta de interior", "decorativa", "fácil cuidado", "tóxica", "popular"]', '["bolsa 10 litros", "maceta negra 15 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132129/plantas/alo10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ALO20L116', 'Acacia Lluvia De Oro', 'Cassia fistula L.', 'árbol', 'Es un árbol ornamental de tamaño mediano a grande, conocido por sus impresionantes cascadas de flores amarillas doradas que aparecen a finales de primavera. Sus hojas son caducas y produce frutos en forma de legumbres cilíndricas. La pulpa de sus frutos se ha utilizado en la medicina tradicional.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ALO20L116', 0, '["ornamental", "medicinal", "flores amarillas", "caducifolio", "tropical", "laxante"]', '["bolsa 20 litros", "bolsa 65 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132501/plantas/alo20l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AMA04L009', 'Amaryllis', 'Hippeastrum spp.', 'ornamental', 'Planta bulbosa conocida por sus grandes y vistosas flores en forma de trompeta, que emergen en tallos altos y sin hojas. Es popular como planta de interior, especialmente durante el invierno, y sus flores pueden ser de diversos colores vibrantes.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AMA04L009', 1, '["bulbosa", "flores grandes", "interior", "invierno", "vistosa", "fácil cuidado"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132522/plantas/ama04l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AMA06L129', 'Amate', 'Ficus obtusifolia', 'árbol', 'El Amate es un árbol tropical perenne, robusto y de gran tamaño, perteneciente al género Ficus, común en México y Mesoamérica. Se caracteriza por sus hojas anchas y brillantes, su tronco grueso con raíces aéreas y la producción de pequeños higos. Históricamente, su corteza se ha utilizado para elaborar el tradicional papel amate.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AMA06L129', 0, '["árbol nativo", "Mesoamérica", "papel amate", "sombra", "ficus", "tropical"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132582/plantas/ama06l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AMA06P134', 'Amazonica', 'Alocasia x amazonica', 'ornamental', 'La Alocasia x amazonica, también conocida como ''Planta Máscara Africana'', es un híbrido llamativo con hojas grandes, en forma de punta de flecha, de color verde oscuro y con venas plateadas o blancas muy marcadas. Es una planta perenne rizomatosa, apreciada por su follaje dramático y cultivada principalmente como planta de interior.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AMA06P134', 4, '["Planta Máscara Africana", "Oreja de Elefante", "Tropical", "Planta de interior", "Follaje dramático", "Híbrido", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132539/plantas/ama06p134.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AMA08L124', 'Acacia Mariposa', 'Senegalia crassifolia', 'árbol', 'Es un árbol pequeño de hoja perenne con hojas distintivas en forma de mariposa, que alcanza entre 3 y 4.5 metros de altura y ancho. Produce flores redondas de color blanco a beige en primavera. Es nativo del noreste de México.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'AMA08L124', 0, '["árbol", "exterior", "hojas de mariposa", "resistente a la sequía", "bajo mantenimiento", "floración primaveral"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777132558/plantas/ama08l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AMI06L003', 'Aralea Mini Gold', 'Polyscias fruticosa ''Ming Gold''', 'ornamental', 'Es un arbusto de hoja perenne con hojas verdes ricas, a menudo variegadas con tonos amarillos o crema, y un follaje similar a helechos. Se cultiva frecuentemente como bonsái en miniatura y es apreciada por su atractivo decorativo.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AMI06L003', 0, '["arbusto", "variegada", "interior", "bonsái", "follaje", "purificadora de aire", "popular"]', '["bolsa 6 litros", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133600/plantas/ami06l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ANT07P200', 'Anthurio', 'Anthurium', 'interior', 'El Anthurium es una planta tropical originaria de América Central y del Sur, conocida por sus llamativas espatas en forma de corazón, a menudo confundidas con flores, y sus hojas verdes brillantes. Es una planta ornamental muy popular para interiores.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'ANT07P200', 0, '["tropical", "flor de flamenco", "ornamental", "hojas brillantes", "purificadora de aire", "araceae"]', '["maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133619/plantas/ant07p200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ANT08P006', 'Anthurio Oaxaqueño', 'Anthurium ''Oaxaca''', 'ornamental', 'El Anthurium ''Oaxaca'' es una planta perenne de hoja ancha y perenne, conocida por su follaje verde brillante y sus flores rosadas que emergen durante todo el año. Presenta hojas grandes en forma de corazón y una textura lustrosa. Es una planta ornamental popular por su belleza y relativa facilidad de cuidado.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ANT08P006', 0, '["planta tropical", "flor de flamenco", "hojas acorazonadas", "planta de interior", "floración duradera", "fácil cuidado", "popular"]', '["maceta negra 8 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133640/plantas/ant08p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('APA08L006', 'Ave De Paraiso', 'Strelitzia reginae', 'ornamental', 'La Strelitzia reginae es una planta herbácea perenne originaria de Sudáfrica, conocida por sus llamativas flores que se asemejan a la cabeza de un ave tropical con tonos naranjas y azules. Posee hojas grandes, alargadas y de color verde grisáceo, que crecen en forma de abanico.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'APA08L006', 0, '["planta tropical", "flor exótica", "jardín", "maceta", "hojas grandes", "Sudáfrica", "popular"]', '["bolsa 8 litros", "bolsa 4 litros", "bolsa 45 litros", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133658/plantas/apa08l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('APA60L120', 'Ave De Paraiso Gigante', 'Strelitzia nicolai', 'árbol', 'La Strelitzia nicolai es una planta grande con hojas similares a las de un plátano y flores blancas y azules que recuerdan a un ave exótica. Puede alcanzar hasta 10 metros de altura en condiciones óptimas. Es una planta ornamental popular tanto en interiores amplios como en exteriores en climas cálidos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'APA60L120', 0, '["tropical", "exótica", "flores blancas", "hojas grandes", "interior", "exterior"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133682/plantas/apa60l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('API04P126', 'Aloe Pink', 'Aloe ''Pink Blush''', 'suculenta', 'El Aloe ''Pink Blush'' es una suculenta híbrida de pequeño tamaño, que forma rosetas de hojas texturizadas en tonos verde oscuro y claro con crestas rosadas elevadas. Puede alcanzar hasta 30 cm de altura y 20-30 cm de ancho. Produce flores tubulares de color naranja desde finales del invierno hasta la primavera.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'API04P126', 0, '["suculenta", "híbrido", "ornamental", "bajo mantenimiento", "floración invernal", "resistente a la sequía"]', '["maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133699/plantas/api04p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('APU15L145', 'Agave Pulpo', 'Agave vilmoriniana', 'suculenta', 'Es una planta suculenta perenne originaria de México, conocida por sus hojas largas, delgadas y arqueadas que se retuercen, asemejándose a los tentáculos de un pulpo. Forma una roseta solitaria de follaje verde grisáceo, valorada en paisajismo por su forma única y escultural. A diferencia de otros agaves, sus hojas suelen tener márgenes lisos sin espinas terminales afiladas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'APU15L145', 0, '["suculenta", "agave", "ornamental", "exterior", "bajo mantenimiento", "resistente a la sequía"]', '["bolsa 15 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133731/plantas/apu15l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ARE07P125', 'Aretillo', 'Fuchsia spp.', 'ornamental', 'El Aretillo, también conocido como fucsia, es un arbusto apreciado por sus vistosas flores colgantes, que presentan una amplia gama de colores como blanco, rosa, rojo y morado. Sus hojas son ovales y de un vibrante color verde. Es una planta ornamental popular en jardines y macetas.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'ARE07P125', 0, '["arbusto", "flores colgantes", "ornamental", "media sombra", "jardín", "fucsia", "popular"]', '["maceta negra 7 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133752/plantas/are07p125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ARU30L170', 'Acer Rubrum', 'Acer rubrum', 'árbol', 'El Acer rubrum, también conocido como arce rojo, es un árbol caducifolio nativo del este de Norteamérica. Se distingue por su espectacular follaje otoñal que varía entre tonos rojos, naranjas y amarillos. Puede alcanzar alturas de 12 a 30 metros y sus hojas presentan de 3 a 5 lóbulos.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ARU30L170', 0, '["árbol caducifolio", "hojas rojas", "otoño", "América del Norte", "paisajismo", "madera"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133771/plantas/aru30l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ASH20L169', 'Aralea Schefflera', 'Schefflera arboricola', 'interior', 'La Schefflera arboricola, también conocida como cheflera enana o árbol paraguas, es un arbusto perennifolio tropical. Se caracteriza por sus hojas palmadas de color verde brillante, que se agrupan de forma similar a un paraguas. Es una planta ornamental muy popular, especialmente como planta de interior.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ASH20L169', 0, '["planta de interior", "árbol paraguas", "follaje", "tropical", "arbusto", "fácil cuidado"]', '["bolsa 20 litros", "bolsa 60 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133793/plantas/ash20l169.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ASI11P001', 'Aralea Siboldi', 'Fatsia japonica', 'ornamental', 'La Fatsia japonica, también conocida como Aralia del Japón, es un arbusto o pequeño árbol de hoja perenne originario de Japón y Corea. Se caracteriza por sus grandes hojas palmadas, brillantes y de color verde oscuro, que le otorgan un aspecto tropical. Es una planta ornamental popular tanto para interiores como para jardines.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ASI11P001', 0, '["arbusto", "perennifolio", "hojas grandes", "sombra", "interior", "exterior"]', '["maceta negra 11 pulgadas", "bolsa 4 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133816/plantas/asi11p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ASI80L161', 'Acer Silver', 'Acer saccharinum', 'árbol', 'El arce plateado es un árbol caducifolio de crecimiento rápido, nativo del este y centro de Norteamérica, que puede alcanzar entre 15 y 30 metros de altura. Se distingue por sus hojas profundamente lobuladas con el envés plateado y su corteza grisácea que se vuelve escamosa con la edad. Es valorado por su rápido crecimiento y su capacidad para proporcionar sombra.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ASI80L161', 0, '["árbol caducifolio", "árbol de sombra", "crecimiento rápido", "nativo de Norteamérica", "hojas plateadas", "resistente a heladas"]', '["bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133836/plantas/asi80l161.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ASP06P130', 'Aspidistra', 'Aspidistra elatior', 'ornamental', 'La Aspidistra elatior, conocida popularmente como ''planta de hierro'', es una planta perenne rizomatosa, de hojas grandes, lanceoladas, de color verde oscuro brillante y textura coriácea. Es famosa por su extrema resistencia y adaptabilidad a condiciones adversas, lo que la convierte en una opción ideal para interiores con poca luz o zonas sombreadas en exteriores. Originaria de Asia oriental, es de crecimiento lento y puede alcanzar hasta 80 cm de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ASP06P130', 0, '["planta de hierro", "resistente", "bajo mantenimiento", "hoja perenne", "interior", "exterior", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133856/plantas/asp06p130.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AST03L124', 'Aster', 'Aster spp.', 'ornamental', 'Las Aster son plantas herbáceas, generalmente perennes, conocidas por sus vistosas flores en forma de estrella. Sus pétalos, que varían en tonos de púrpura, azul, rosa o blanco, florecen desde finales del verano hasta el otoño. Son apreciadas por su fácil cuidado y su capacidad para atraer polinizadores.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AST03L124', 0, '["floración otoñal", "jardín", "perenne", "atrae polinizadores", "fácil cuidado", "flor estrella"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133874/plantas/ast03l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AST06L145', 'Aloe Striata', 'Aloe striata Haw.', 'suculenta', 'Es una suculenta sin tallo con hojas anchas, carnosas y de color verde azulado, a menudo con márgenes rosados y líneas longitudinales distintivas. Produce inflorescencias altas y ramificadas con flores tubulares de color rojo coral que aparecen a finales del invierno o principios de la primavera. Es una planta ornamental popular por su apariencia llamativa y su resistencia a la sequía.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AST06L145', 0, '["ornamental", "exterior", "interior", "resistente a la sequía", "floración invernal", "Sudáfrica"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133918/plantas/ast06l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AST08L119', 'Astronomica', 'Lagerstroemia indica', 'ornamental', 'Es un árbol o arbusto caducifolio conocido por su atractiva corteza de tono marrón rosado. Sus hojas, de color verde oscuro grisáceo, adquieren tonos amarillos y naranjas en otoño. Produce abundantes flores de color rosa, malva o blanco durante el verano.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'AST08L119', 0, '["Árbol de Júpiter", "Crespón", "floración veraniega", "caducifolio", "ornamental", "jardín", "popular"]', '["bolsa 8 litros", "bolsa 30 litros", "bolsa 4 litros", "bolsa 60 litros", "bolsa 11 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133896/plantas/ast08l119.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ATO08P162', 'Agave Tobala', 'Agave Potatorum', 'suculenta', 'El Agave Tobalá, científicamente conocido como Agave Potatorum, es una pequeña variedad de agave silvestre originaria de las tierras altas de Oaxaca, México. Se caracteriza por su roseta compacta de hojas azul-verdosas con espinas rojas y es altamente valorado en la producción de mezcal por su perfil de sabor único. Esta suculenta es tolerante a la sequía y puede ser cultivada como planta ornamental.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ATO08P162', 0, '["Agave", "Mezcal", "Oaxaca", "Suculenta", "Planta silvestre", "Ornamental", "Resistente a la sequía"]', '["maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133940/plantas/ato08p162.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AVE04L006', 'Avelia Verde', 'Abelia x grandiflora', 'ornamental', 'La Abelia x grandiflora es un arbusto ornamental de follaje semi-perenne, con hojas pequeñas, ovaladas y de un verde brillante. Produce abundantes flores campaniformes, fragantes y de tonos blancos a rosados, que florecen desde la primavera hasta el otoño. Puede alcanzar una altura de 1.5 a 3 metros.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'AVE04L006', 0, '["arbusto", "floración prolongada", "follaje verde", "resistente", "jardín", "seto", "popular"]', '["bolsa 4 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133960/plantas/ave04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AVR10P107', 'Agave Victoria Regina', 'Agave victoriae-reginae', 'suculenta', 'La Agave victoriae-reginae es una suculenta ornamental de tamaño compacto, formando rosetas globosas de hojas gruesas, lanceoladas y de color verde oscuro con distintivas líneas blancas en los márgenes. Puede alcanzar hasta 50 centímetros de diámetro y 30 centímetros de altura, con espinas cortas en las puntas de sus hojas. Es muy apreciada por coleccionistas y viveristas debido a su alto valor ornamental.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'AVR10P107', 0, '["suculenta", "ornamental", "México", "roseta", "bajo mantenimiento", "sol directo", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777133988/plantas/avr10p107.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AZA10L115', 'Azalea Arbusto', 'Rhododendron spp.', 'ornamental', 'Las azaleas son arbustos floridos del género Rhododendron, apreciadas por sus vistosas y abundantes flores de diversos colores que aparecen en primavera. Pueden ser de hoja caduca o perenne, con hojas generalmente ovaladas de color verde oscuro. Se cultivan tanto en interiores como en exteriores.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AZA10L115', 0, '["arbusto", "flores", "colorida", "jardín", "suelo ácido", "primavera"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134030/plantas/aza10l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AZA30L115', 'Azalea De Copa', 'Rhododendron indicum', 'ornamental', 'La azalea de copa es un arbusto ornamental que se cultiva con una forma de arbolito y una copa redondeada. Sus hojas son de color verde oscuro y ovaladas, y produce una abundante floración primaveral con flores de colores brillantes como rojo, rosa y blanco.', 'luz indirecta', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AZA30L115', 0, '["arbusto", "floración primaveral", "suelo ácido", "exterior", "interior", "flores vistosas"]', '["bolsa 30 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134010/plantas/aza30l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('AZA40L158', 'Azalea Topiario', 'Rhododendron spp.', 'ornamental', 'Las azaleas son arbustos de tamaño mediano, apreciadas por sus abundantes y vistosas flores en tonos blancos, rojos, malvas y rosados que aparecen en primavera. La forma ''topiario'' se refiere a su poda y modelado artístico.', 'media sombra', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'AZA40L158', 0, '["arbusto", "floración primaveral", "flores vistosas", "planta ornamental", "exterior", "interior", "acidófila", "topiario"]', '["bolsa 40 litros", "bolsa 70 litros", "bolsa 50 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134048/plantas/aza40l158.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BAR01L200', 'Buxus Arrayan', 'Buxus sempervirens', 'ornamental', 'Es un arbusto o árbol pequeño de hoja perenne, que alcanza de 1 a 9 metros de altura. Posee hojas pequeñas, ovaladas y de color verde oscuro brillante. Es muy valorado en jardinería para setos y topiarios.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BAR01L200', 0, '["arbusto", "seto", "topiario", "perenne", "jardín", "resistente", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134075/plantas/bar01l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BAR06L170', 'Buxus Arrayan Bola', 'Buxus sempervirens', 'ornamental', 'El Buxus sempervirens, conocido comúnmente como Boj, es un arbusto de hoja perenne que se caracteriza por su denso follaje. La forma ''Arrayán Bola'' se refiere a ejemplares podados esféricamente, muy apreciados en jardinería ornamental. Es una planta resistente y de fácil cultivo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BAR06L170', 0, '["arbusto", "perenne", "jardinería", "topiaria", "resistente", "exterior", "popular"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134090/plantas/bar06l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BCU07L114', 'Bugambilia Cuautla', 'Bougainvillea spp.', 'ornamental', 'Es un arbusto o planta trepadora perenne, conocida por sus vistosas brácteas de colores intensos como fucsia, morado, blanco o rojo, que a menudo se confunden con sus pequeñas flores. Posee tallos leñosos con espinas y puede alcanzar varios metros de altura.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BCU07L114', 0, '["trepadora", "arbusto", "brácteas coloridas", "exterior", "clima cálido", "medicinal", "espinas", "popular"]', '["bolsa 7 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134117/plantas/bcu07l114.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BEA15L117', 'Beaucarnea', 'Beaucarnea recurvata', 'ornamental', 'La Beaucarnea recurvata, conocida comúnmente como Pata de Elefante, es una planta suculenta originaria de México, caracterizada por su tronco grueso y bulboso que almacena agua y sus hojas largas y delgadas que caen en cascada. Es una planta de crecimiento lento, muy valorada por su porte escultural y resistencia, ideal para la decoración de interiores.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BEA15L117', 0, '["Pata de elefante", "suculenta", "planta de interior", "resistente", "bajo mantenimiento", "México"]', '["bolsa 15 litros", "bolsa 30 litros", "maceta negra 14 pulgadas", "bolsa 10 litros", "maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134135/plantas/bea15l117.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BEL06P006', 'Belen', 'Impatiens walleriana', 'ornamental', 'La Impatiens walleriana, comúnmente conocida como Belén o Alegría del hogar, es una planta popular por sus vibrantes y coloridas flores. Crece entre 15 y 60 cm de altura, con tallos carnosos y hojas ovadas de color verde brillante. Florece profusamente desde primavera hasta otoño, añadiendo color continuo a jardines y macetas.', 'media sombra', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BEL06P006', 0, '["floración prolongada", "planta de sombra", "fácil cuidado", "macetas", "jardín", "colores vibrantes", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134152/plantas/bel06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BER01L125', 'Bergenia', 'Bergenia', 'ornamental', 'La Bergenia es un género de plantas perennes rizomatosas, originarias de Asia central. Se distingue por sus grandes hojas coriáceas, que a menudo cambian a tonos rojizos en invierno, y sus vistosas flores en forma de campanilla que brotan desde finales del invierno hasta la primavera. Es una planta ornamental muy apreciada por su follaje persistente y su floración temprana.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BER01L125', 0, '["perenne", "follaje ornamental", "floración invernal", "resistente al frío", "cubresuelos", "jardín de sombra", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134171/plantas/ber01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BES02L125', 'Bandera Española', 'Lantana camara', 'ornamental', 'La Lantana camara, conocida como Bandera Española, es un arbusto perenne de rápido crecimiento que alcanza hasta 2 metros de altura. Sus hojas son rugosas y dentadas, y sus flores, agrupadas en densos ramilletes, cambian de color del amarillo al naranja y rojo a medida que maduran. Es muy valorada por su prolongada y vistosa floración multicolor.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'BES02L125', 1, '["arbusto", "flores", "exterior", "resistente", "polinizadores", "sequía", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134187/plantas/bes02l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BIG08L105', 'Bignonia Morada', 'Podranea ricasoliana', 'ornamental', 'Es una vigorosa enredadera de rápido crecimiento, conocida por sus abundantes flores en forma de trompeta de color lila o rosa. Originaria del sur de África, es ideal para cubrir pérgolas, cercas y muros.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BIG08L105', 0, '["enredadera", "flores rosas", "exterior", "crecimiento rápido", "trepadora", "Sudáfrica", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134211/plantas/big08l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BMA06L009', 'Black Magic', 'Colocasia esculenta ''Black Magic''', 'ornamental', 'La Colocasia esculenta ''Black Magic'' es una planta perenne tuberosa, apreciada por su espectacular follaje. Sus grandes hojas en forma de corazón, de color púrpura-negro ahumado, pueden alcanzar hasta 60 cm de largo y cuelgan hacia abajo. Es ideal para añadir un toque tropical a jardines y contenedores.', 'media sombra', 'alto', 'fácil', 'disponible', 'ambas', 'tóxica', 'BMA06L009', 0, '["follaje oscuro", "planta tropical", "oreja de elefante", "planta acuática", "exterior", "macetas"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134230/plantas/bma06l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BMI20L132', 'Bugambilia Minimorada', 'Bougainvillea spectabilis', 'ornamental', 'La Bugambilia Minimorada es una planta trepadora ornamental, originaria de Brasil, que se caracteriza por sus pequeñas hojas y sus vistosas brácteas de color guinda o morado intenso que rodean sus diminutas flores. Esta variedad compacta de bugambilia florece abundantemente en climas cálidos y templados.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BMI20L132', 0, '["trepadora", "arbusto", "floración abundante", "exterior", "resistente", "sol pleno"]', '["bolsa 20 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134252/plantas/bmi20l132.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BPL06L006', 'Bambu Plumoso', 'Phyllostachys aurea', 'ornamental', 'El Bambú Plumoso (Phyllostachys aurea) es una especie de bambú con follaje denso y plumoso, caracterizado por hojas largas y estrechas. Sus cañas, inicialmente verdes, adquieren un tono dorado con la edad, lo que lo convierte en una planta ornamental muy valorada. Es resistente y se adapta bien a diversas condiciones climáticas y tipos de suelo.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'BPL06L006', 0, '["exterior", "rápido crecimiento", "seto", "pantalla de privacidad", "resistente", "invasivo", "popular"]', '["bolsa 6 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134290/plantas/bpl06l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BRO06P121', 'Bromelia Pink', 'Aechmea fasciata', 'ornamental', 'La Aechmea fasciata, conocida como Bromelia Rosada o planta de urna, es una planta tropical ornamental que destaca por sus hojas arqueadas con bandas plateadas y una espectacular bráctea floral de color rosa que puede durar meses. Es originaria de las selvas tropicales de Brasil y se cultiva por su belleza exótica.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BRO06P121', 0, '["ornamental", "tropical", "interior", "flor rosada", "no tóxica", "epífita"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134310/plantas/bro06p121.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BRO08P109', 'Bromelia Aechmea', 'Aechmea fasciata', 'ornamental', 'La Aechmea fasciata es una bromelia ornamental de interior, conocida por sus hojas rígidas de color verde-gris con rayas plateadas y bordes espinosos. Su llamativa inflorescencia, que a menudo presenta brácteas rosadas y pequeñas flores azules, emerge del centro de la roseta. Es una planta tropical epífita, apreciada por su belleza y facilidad de cultivo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BRO08P109', 0, '["bromelia", "interior", "tropical", "epífita", "hojas plateadas", "flor rosa", "fácil cuidado", "popular"]', '["maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134329/plantas/bro08p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BRU04L010', 'Brunfelsia', 'Brunfelsia', 'ornamental', 'La Brunfelsia es un género de arbustos o pequeños árboles perennes, originarios de América del Sur, apreciados por sus vistosas flores que cambian de color, generalmente del violeta al blanco, y por su fragancia dulce e intensa. Sus flores, que a menudo se presentan en diferentes tonos simultáneamente, la convierten en una planta ornamental muy popular para jardines y patios. Pertenece a la familia Solanaceae.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'BRU04L010', 0, '["arbusto", "flores perfumadas", "cambio de color", "tropical", "ornamental", "exterior"]', '["bolsa 4 litros", "bolsa 20 litros", "bolsa 10 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134350/plantas/bru04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BSV07L114', 'Bugambilia San Vicente', 'Bougainvillea spp.', 'ornamental', 'La bugambilia es un género de arbustos, enredaderas o pequeños árboles espinosos, conocidos por sus vistosas brácteas de colores brillantes (rosado, morado, rojo, naranja, blanco, amarillo) que rodean pequeñas flores blancas. Es una planta de rápido crecimiento que puede alcanzar hasta 12 metros de altura, ideal para cubrir muros y pérgolas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BSV07L114', 0, '["trepadora", "arbusto", "flores", "brácteas", "tropical", "resistente", "espinosa", "Sudamérica", "exterior", "medicinal"]', '["bolsa 7 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134371/plantas/bsv07l114.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BUG07L128', 'Bugambilia Surtida', 'Bougainvillea spp.', 'ornamental', 'La bugambilia es una planta trepadora o arbustiva, conocida por sus llamativas brácteas de colores vibrantes como fucsia, rosa, rojo, blanco, naranja o violeta, que rodean pequeñas flores poco vistosas. Posee tallos leñosos y espinosos, y es nativa de Sudamérica. Se cultiva ampliamente como planta ornamental en regiones tropicales y subtropicales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BUG07L128', 0, '["trepadora", "arbusto", "flores vistosas", "exterior", "resistente", "espinosa", "popular"]', '["bolsa 7 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134410/plantas/bug07l128.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BUG12L200', 'Bugambilia', 'Bougainvillea', 'ornamental', 'Es un género de enredaderas, arbustos y árboles ornamentales espinosos, nativos de Sudamérica. Se caracteriza por sus vistosas brácteas de colores brillantes (rosa, morado, rojo, naranja, blanco o amarillo) que rodean pequeñas flores blancas, floreciendo abundantemente en climas cálidos.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'BUG12L200', 0, '["trepadora", "arbusto", "flores vibrantes", "resistente a la sequía", "sol directo", "exterior", "popular"]', '["bolsa 12 litros", "bolsa 20 litros", "bolsa 10 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134389/plantas/bug12l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('BUG50L128', 'Bugambilia Tronco', 'Bougainvillea spp.', 'ornamental', 'La bugambilia es un arbusto trepador vigoroso, que puede ser perennifolio o caducifolio según el clima, conocido por sus vistosas brácteas de colores intensos que rodean pequeñas flores. Sus tallos son leñosos y espinosos, y se puede entrenar para crecer con un tronco robusto, asemejándose a un árbol pequeño.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'BUG50L128', 0, '["trepadora", "arbusto", "espinosa", "floración abundante", "clima cálido", "jardín", "popular"]', '["bolsa 50 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134454/plantas/bug50l128.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAC02L010', 'Cacahuatillo', 'Senna uniflora', 'ornamental', 'Es una planta perenne arbustiva que se caracteriza por sus pequeñas flores de color amarillo brillante, de floración solitaria y erguida. Sus hojas se componen de foliolos estrechos que se cierran en la oscuridad, una adaptación que le ayuda a minimizar la pérdida de agua. Su crecimiento compacto y resistencia le permiten prosperar en diversas condiciones.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CAC02L010', 0, '["flores amarillas", "perenne", "arbustiva", "leguminosa", "resistente", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134480/plantas/cac02l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAC02L077', 'Cacao', 'Theobroma cacao', 'árbol', 'El cacao (Theobroma cacao) es un árbol perenne de tamaño pequeño a mediano, nativo de las regiones tropicales de América Central y del Sur. Se caracteriza por producir sus flores y frutos, conocidos como mazorcas, directamente del tronco y las ramas principales. Sus semillas, los granos de cacao, son la materia prima para la elaboración del chocolate.', 'media sombra', 'alto', 'difícil', 'disponible', 'ambas', 'tóxica', 'CAC02L077', 0, '["árbol tropical", "frutal", "chocolate", "Malvaceae", "cultivo", "perenne", "popular"]', '["bolsa 2 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134500/plantas/cac02l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAF08L124', 'Cafe', 'Coffea arabica', 'ornamental', 'El cafeto es un arbusto o pequeño árbol de hojas perennes, verdes y brillantes. Produce fragantes flores blancas que dan lugar a frutos rojos, conocidos como cerezas de café, que contienen las preciadas semillas.', 'luz indirecta', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CAF08L124', 2, '["tropical", "arbusto", "interior", "frutal", "aromática", "cafeína"]', '["bolsa 8 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134517/plantas/caf08l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAL04L010', 'Caliandra', 'Calliandra haematocephala', 'ornamental', 'La Caliandra es un arbusto o pequeño árbol de hoja perenne, conocido por sus llamativas flores en forma de "borla" o "pompones" de estambres rojos, rosados o blancos. Sus hojas son bipinnadas y se pliegan por la noche. Florece principalmente en otoño e invierno, pero puede tener floraciones esporádicas durante todo el año.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CAL04L010', 0, '["arbusto", "floración vistosa", "exterior", "clima cálido", "hoja perenne", "plumerillo rojo", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134543/plantas/cal04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAL08P109', 'Calathea', 'Calathea spp.', 'ornamental', 'Las Calatheas son plantas herbáceas rizomatosas originarias de las selvas tropicales de América, apreciadas por sus hojas grandes y vistosas con patrones y colores variados, a menudo con el envés púrpura. Son conocidas como "plantas de oración" debido a que sus hojas se pliegan por la noche y se despliegan por la mañana en respuesta a la luz. Son populares como plantas de interior ornamental y son seguras para mascotas.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'CAL08P109', 0, '["planta de interior", "hojas decorativas", "tropical", "purificadora de aire", "no tóxica", "planta de oración", "popular"]', '["maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134564/plantas/cal08p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAL30L105', 'Calistemo', 'Callistemon', 'ornamental', 'El Calistemo es un género de arbustos y árboles pequeños originarios de Australia, conocidos por sus distintivas flores en forma de cepillo de botella. Sus flores, que suelen ser rojas pero pueden variar, atraen a polinizadores como abejas y pájaros. Sus hojas son estrechas y a menudo desprenden un aroma cítrico al estrujarlas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CAL30L105', 0, '["arbusto", "árbol pequeño", "exterior", "flores llamativas", "resistente a la sequía", "atrae polinizadores", "popular"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134585/plantas/cal30l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAL60L103', 'Calistemo Llorón', 'Callistemon viminalis', 'árbol', 'El Calistemo Llorón es un arbusto o árbol pequeño perennifolio, nativo de Australia, que puede alcanzar hasta 8 metros de altura. Se caracteriza por sus ramas flexibles y colgantes, y sus llamativas inflorescencias rojas en forma de cepillo que aparecen en primavera y verano.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CAL60L103', 0, '["ornamental", "exterior", "arbusto", "flores rojas", "limpiatubos", "resistente a la sequía"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134609/plantas/cal60l103.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAM40L170', 'Camelia', 'Camellia japonica', 'ornamental', 'La Camelia es un arbusto o pequeño árbol de follaje perenne, con hojas coriáceas de color verde oscuro brillante. Sus vistosas flores, que aparecen en invierno y principios de primavera, varían en colores como blanco, rosa y rojo. Es muy apreciada por su valor ornamental en jardines y macetas.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CAM40L170', 0, '["arbusto", "flores de invierno", "hojas perennes", "planta acidófila", "jardín", "maceta"]', '["bolsa 40 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134632/plantas/cam40l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAN02L077', 'Canela', 'Cinnamomum verum', 'árbol', 'El Cinnamomum verum, conocido como canela de Ceilán o canelo, es un árbol perenne de tamaño pequeño a mediano, originario de Sri Lanka. Su corteza interna se cosecha y se seca para producir la especia de canela, apreciada por su sabor delicado, dulce y ligeramente cítrico. Posee hojas ovaladas y brillantes, y produce pequeñas flores de color amarillo pálido seguidas de frutos de color púrpura oscuro.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'CAN02L077', 1, '["especia", "medicinal", "aromática", "tropical", "exterior", "culinaria", "popular"]', '["bolsa 2 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134658/plantas/can02l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAN04L006', 'Cisus Antartica', 'Cissus antarctica', 'ornamental', 'La Cissus antarctica, también conocida como vid canguro, es una planta trepadora perenne de hoja perenne, nativa de Australia. Presenta hojas ovaladas, brillantes y de color verde oscuro con márgenes aserrados. Puede crecer como enredadera o como planta colgante, siendo popular por su atractivo follaje y su rápido crecimiento.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CAN04L006', 0, '["trepadora", "planta de interior", "hoja perenne", "follaje brillante", "Australia", "bajo mantenimiento"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134692/plantas/can04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAR03L077', 'Cariza Enana', 'Carissa macrocarpa', 'ornamental', 'La Carissa macrocarpa, conocida como Cariza Enana en sus variedades compactas, es un arbusto espinoso de hoja perenne con hojas verde oscuro brillante y flores blancas fragantes. Produce frutos rojos comestibles cuando están maduros. Es una planta rústica y de bajo mantenimiento, ideal para jardines tropicales y subtropicales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CAR03L077', 0, '["arbusto", "espinoso", "frutos comestibles", "seto", "bajo mantenimiento", "flor blanca", "exterior", "popular"]', '["bolsa 3 litros", "bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134711/plantas/car03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CAR04L133', 'Cedro Arizona', 'Cupressus arizonica', 'árbol', 'El Cedro Arizona (Cupressus arizonica) es un árbol conífero perenne de porte mediano a grande, que alcanza entre 10 y 25 metros de altura con una copa cónica. Su follaje denso y escamoso presenta tonalidades que van del verde grisáceo al azul verdoso, y su madera es conocida por un agradable aroma a cedro y cítricos. Es originario del suroeste de Estados Unidos y el norte de México.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'CAR04L133', 0, '["árbol", "conífera", "siempreverde", "ornamental", "resistente a la sequía", "seto"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134736/plantas/car04l133.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CBL03L169', 'Cedro Blanco', 'Cupressus lusitanica', 'árbol', 'El Cedro Blanco (Cupressus lusitanica) es un árbol perennifolio de gran altura, que puede alcanzar hasta 40 metros. Presenta una forma cónica o piramidal con ramas densas y una corteza distintiva de color gris-marrón que se exfolia. Su follaje es de color verde oscuro, dispuesto en escamas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'CBL03L169', 0, '["árbol", "ornamental", "conífera", "exterior", "madera", "resistente a sequía"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134760/plantas/cbl03l169.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CBR08L129', 'Cerezo Brasileño', 'Eugenia uniflora', 'árbol', 'El Cerezo Brasileño (Eugenia uniflora) es un arbusto grande o árbol pequeño de forma cónica, que puede alcanzar hasta 8 metros de altura. Sus hojas son brillantes, de color verde oscuro, y sus frutos acanalados cambian de verde a rojo intenso o casi negro al madurar, siendo comestibles y de sabor agridulce.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CBR08L129', 0, '["Frutal", "Tropical", "Ornamental", "Comestible", "Cerca viva", "Medicinal"]', '["bolsa 8 litros", "bolsa 60 litros", "bolsa 6 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134785/plantas/cbr08l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CCG08P006', 'Croto Cola De Gallo', 'Codiaeum variegatum', 'ornamental', 'La Codiaeum variegatum, conocida comúnmente como Croto o Croto Cola de Gallo, es una planta ornamental tropical apreciada por su follaje vibrante y variado. Sus hojas, de formas diversas, exhiben una mezcla de colores intensos como amarillo, rojo, naranja, verde y púrpura. Es un arbusto de hoja perenne que puede crecer hasta 3 metros en su hábitat natural, pero se mantiene más pequeña como planta de interior.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CCG08P006', 0, '["planta ornamental", "follaje colorido", "planta tropical", "planta de interior", "tóxica para mascotas", "arbusto", "popular"]', '["maceta negra 8 pulgadas", "bolsa 6 litros", "bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134806/plantas/ccg08p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CED01L125', 'Cedron', 'Aloysia citrodora', 'medicinal', 'El cedrón, conocido científicamente como Aloysia citrodora, es un arbusto aromático originario de América del Sur, que puede alcanzar hasta 3 metros de altura. Sus hojas lanceoladas de color verde brillante desprenden un agradable aroma a limón al frotarse. Produce pequeñas flores blanquecinas o rosadas agrupadas en espigas durante el verano.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CED01L125', 0, '["aromática", "medicinal", "digestiva", "exterior", "arbusto", "cítrica", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134842/plantas/ced01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CEI20L129', 'Ceiba', 'Ceiba pentandra', 'árbol', 'La Ceiba (Ceiba pentandra) es un árbol gigantesco y caducifolio, nativo de las regiones tropicales de América y África, que puede alcanzar hasta 70 metros de altura. Se caracteriza por su tronco recto y grueso, a menudo cubierto de espinas cónicas y con grandes raíces tabulares que actúan como contrafuertes. Produce hojas palmado-compuestas y flores perfumadas de tonos blancuzcos a rosados, y sus frutos contienen una fibra algodonosa conocida como kapok.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CEI20L129', 0, '["árbol", "caducifolio", "tropical", "kapok", "sagrado", "medicinal", "ornamental", "espinoso", "raíces tabulares"]', '["bolsa 20 litros", "bolsa 12 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134860/plantas/cei20l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CEL01L125', 'Celosia', 'Celosia argentea', 'ornamental', 'La Celosia es un género de plantas ornamentales conocido por sus vibrantes y llamativas flores que pueden ser plumosas, con forma de cresta de gallo o espigadas, en tonos de rojo, naranja, amarillo, rosa y morado. Es una planta anual o perenne tierna, fácil de cultivar y que prospera en climas cálidos y soleados. Sus flores son excelentes para arreglos frescos o secos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CEL01L125', 0, '["flor vibrante", "planta anual", "flor de corte", "resistente al calor", "fácil cuidado", "jardín", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134880/plantas/cel01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CEN15L006', 'Clavo Enano', 'Pittosporum tobira ''Nana''', 'ornamental', 'Es un arbusto perenne de crecimiento moderado, con hojas coriáceas de color verde oscuro brillante y flores blancas muy fragantes con aroma a azahar que aparecen en primavera. Alcanza una altura de 0.4 a 0.7 metros y un ancho de hasta 2 metros.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CEN15L006', 0, '["arbusto", "perenne", "fragante", "bajo mantenimiento", "seto", "cubresuelos", "popular"]', '["bolsa 15 litros", "bolsa 3 litros", "bolsa 6 litros", "bolsa 10 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134906/plantas/cen15l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CER12L077', 'Cerezo Lapins', 'Prunus avium ''Lapins''', 'árbol', 'El Cerezo Lapins es un árbol caducifolio de tamaño medio que produce cerezas grandes, firmes, jugosas y de color rojo oscuro con un sabor dulce. Florece en primavera con abundantes flores blancas y es conocido por su resistencia y ser autofértil.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CER12L077', 0, '["frutal", "árbol", "exterior", "cereza", "autofértil", "caducifolio"]', '["bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134924/plantas/cer12l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CFR04L112', 'Cariza De Fruta', 'Carissa macrocarpa', 'exterior', 'La Carissa macrocarpa, también conocida como Ciruelo de Natal, es un arbusto espinoso de hoja perenne, nativo del sur de África. Produce flores blancas fragantes en forma de estrella y frutos rojos comestibles. Sus hojas son coriáceas, de color verde oscuro brillante y ovaladas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CFR04L112', 0, '["arbusto", "espinoso", "frutos comestibles", "flores fragantes", "resistente", "seto", "medicinal"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134940/plantas/cfr04l112.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CGA03L003', 'Croto Gallo', 'Codiaeum variegatum', 'ornamental', 'El Croto, también conocido como Codiaeum variegatum, es un arbusto perenne tropical famoso por su follaje llamativo y variado. Sus hojas gruesas y brillantes exhiben una amplia gama de colores como verde, amarillo, naranja, rojo y púrpura, con diversas formas y patrones. Es originario de las regiones tropicales de Asia y el Pacífico occidental.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CGA03L003', 0, '["tropical", "interior", "exterior", "follaje colorido", "arbusto", "humedad", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134961/plantas/cga03l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CHI03L125', 'Chile', 'Capsicum annuum', 'exterior', 'La planta de chile es una herbácea cultivada por sus frutos comestibles, conocidos como pimientos, que varían en color y nivel de picor. Originaria de América, pertenece a la familia de las solanáceas y es apreciada en la gastronomía mundial.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CHI03L125', 0, '["comestible", "picante", "hortaliza", "medicinal", "ornamental", "solanácea", "popular"]', '["bolsa 3 litros", "bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777134983/plantas/chi03l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CHI05P109', 'Corazon En Un Hilo', 'Ceropegia woodii', 'suculenta', 'La Ceropegia woodii, también conocida como ''Corazón en un Hilo'', es una planta colgante suculenta originaria de Sudáfrica. Se caracteriza por sus delicadas hojas en forma de corazón y sus finas enredaderas que pueden alcanzar varios metros de longitud. Produce pequeñas flores de tonos rosados y magenta.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CHI05P109', 0, '["planta colgante", "suculenta", "hojas en forma de corazón", "fácil cuidado", "interior", "pet-friendly"]', '["maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135002/plantas/chi05p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CHI08L115', 'Chicozapote', 'Manilkara zapota', 'árbol', 'El chicozapote es un árbol perennifolio originario de Mesoamérica, que puede alcanzar hasta 45 metros de altura. Produce hojas simples, flores blancas perfumadas y frutos tipo baya con cáscara morena y pulpa muy dulce y jugosa. Su látex se utiliza para fabricar chicle.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CHI08L115', 0, '["frutal", "tropical", "perennifolio", "chicle", "madera", "dulce", "Mesoamérica"]', '["bolsa 8 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135021/plantas/chi08l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CIN04L010', 'Clavel De La India', 'Tagetes erecta', 'ornamental', 'El Clavel de la India, también conocido como Cempasúchil, es una planta herbácea anual ornamental con grandes flores de colores brillantes que van del amarillo al naranja profundo. Puede alcanzar entre 30 y 100 cm de altura, dependiendo de la variedad, y sus hojas son pequeñas y verdes. Además de su valor estético, es valorada por su capacidad para repeler insectos y nematodos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CIN04L010', 1, '["flor", "anual", "repelente de insectos", "jardín", "cempasúchil", "fácil cuidado", "popular"]', '["bolsa 4 litros", "bolsa 18 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135041/plantas/cin04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CIN06P121', 'Canto De La India', 'Dracaena reflexa', 'ornamental', 'La Dracaena reflexa, conocida como ''Canto de la India'', es un arbusto de hoja perenne apreciado por su atractivo follaje variegado. Sus hojas en forma de espada presentan centros verdes y márgenes de color crema o amarillo, dispuestas en espiral. Es una planta ornamental de crecimiento lento a moderado, ideal para interiores y exteriores en climas adecuados.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CIN06P121', 0, '["planta de interior", "follaje variegado", "tropical", "arbusto", "fácil cuidado", "exterior", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135059/plantas/cin06p121.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CIT30L006', 'Cipres Italiano', 'Cupressus sempervirens', 'árbol', 'El Ciprés Italiano (Cupressus sempervirens) es un árbol conífero perenne de tamaño mediano a grande, que puede alcanzar hasta 35 metros de altura, caracterizado por su forma columnar y follaje denso de hojas escamosas de color verde oscuro. Es una especie muy longeva, con ejemplares que superan los 1000 años, y es ampliamente valorado por su uso ornamental en jardines y paisajes mediterráneos. Es resistente a la sequía y de bajo mantenimiento.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CIT30L006', 0, '["árbol perenne", "conífera", "jardín mediterráneo", "resistente sequía", "ornamental", "seto", "popular"]', '["bolsa 30 litros", "bolsa 2 litros", "bolsa 60 litros", "bolsa 45 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135078/plantas/cit30l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CJA02L127', 'Criptomeria Japonica', 'Cryptomeria japonica', 'árbol', 'La Cryptomeria japonica, también conocida como cedro japonés o sugi, es una conífera perenne de gran porte, originaria de Japón y China. Puede alcanzar alturas considerables, con una copa cónica y follaje denso de hojas aciculares de color verde que pueden broncearse en invierno. Su corteza es rojiza y fibrosa.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CJA02L127', 0, '["conífera", "árbol ornamental", "jardín", "perenne", "sugi", "cedro japonés", "popular"]', '["bolsa 2 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135104/plantas/cja02l127.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CLE04L133', 'Cipres Leyland', 'Cupressus × leylandii', 'árbol', 'El Ciprés Leyland es un árbol conífero perenne de rápido crecimiento, conocido por su denso follaje verde oscuro y su forma piramidal o columnar. Es un híbrido utilizado ampliamente para la creación de setos, pantallas de privacidad y cortavientos en jardines y paisajes. Puede alcanzar alturas considerables si no se poda regularmente.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CLE04L133', 0, '["conífera", "seto", "crecimiento rápido", "exterior", "ornamental", "resistente", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135122/plantas/cle04l133.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CLI03L077', 'Cedro Limon', 'Cupressus macrocarpa ''Goldcrest''', 'árbol', 'Es una conífera perenne de forma columnar, apreciada por su follaje de color amarillo dorado brillante que desprende un fuerte aroma a limón al ser aplastado. Puede crecer rápidamente y alcanzar alturas considerables, siendo utilizada tanto en jardines como en interiores.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CLI03L077', 0, '["conífera", "aromática", "follaje amarillo", "exterior", "interior", "ornamental", "popular"]', '["bolsa 3 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135146/plantas/cli03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CLI04L006', 'Clivia', 'Clivia miniata', 'ornamental', 'La Clivia es una planta herbácea perenne originaria de Sudáfrica, conocida por sus hojas largas, gruesas y de color verde oscuro que crecen en forma de abanico. Produce llamativas flores acampanadas, generalmente de tonos naranja o rojo anaranjado, agrupadas en umbelas sobre un tallo floral alto. Puede alcanzar una altura de 50 a 70 centímetros.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CLI04L006', 0, '["planta de interior", "planta de exterior", "flores naranjas", "fácil cuidado", "Sudáfrica", "perenne", "popular"]', '["bolsa 4 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135163/plantas/cli04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CLO06P009', 'Clorofito', 'Chlorophytum comosum', 'ornamental', 'El clorofito, también conocido como cinta o malamadre, es una planta herbácea perenne con hojas largas y arqueadas que forman una roseta central. Produce estolones con pequeñas flores blancas y plántulas, creando un atractivo efecto de cascada. Es muy valorada por su fácil cuidado y su capacidad para purificar el aire.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CLO06P009', 0, '["planta de interior", "fácil cuidado", "purificadora de aire", "colgante", "resistente", "hijuelos", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135181/plantas/clo06p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CMA02L010', 'Croto Manzano', 'Codiaeum variegatum', 'ornamental', 'El crotón (Codiaeum variegatum) es una planta ornamental conocida por su follaje vibrante y multicolor, con tonos de amarillo, naranja y rojo intenso. Es un arbusto tropical de hojas grandes, gruesas, perennes y brillantes, muy valorado por su atractivo decorativo.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CMA02L010', 0, '["planta tropical", "follaje colorido", "arbusto", "decorativa", "exótica", "requiere humedad"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135200/plantas/cma02l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CMA06P109', 'Corazon De Maria', 'Lamprocapnos spectabilis', 'ornamental', 'La Corazón de María es una planta herbácea perenne conocida por sus distintivas flores colgantes en forma de corazón, que suelen ser rosadas o blancas. Florece en primavera, creando un efecto ornamental muy apreciado en jardines y zonas sombreadas. Puede alcanzar entre 30 y 90 centímetros de altura.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CMA06P109', 0, '["flor de corazón", "perenne", "sombra", "jardín", "primavera", "tóxica", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135226/plantas/cma06p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CMO06P006', 'Cuna De Moises', 'Spathiphyllum spp.', 'interior', 'La Cuna de Moisés es una planta herbácea perenne de hoja perenne, conocida por su elegante follaje verde oscuro y brillante. Produce una distintiva espata blanca o blanco-verdosa que envuelve un espádice, lo que le da su apariencia de flor. Es una planta ornamental muy popular, especialmente para interiores, debido a su belleza y facilidad de cuidado.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CMO06P006', 0, '["planta de interior", "purificadora de aire", "flores blancas", "follaje verde", "tropical", "bajo mantenimiento", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135244/plantas/cmo06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('COL03P126', 'Colorata', 'Echeveria colorata', 'suculenta', 'La Echeveria colorata es una suculenta que forma grandes rosetas de hojas carnosas, lanceoladas y de color verde plateado con puntas rojizas. Puede alcanzar hasta 40 cm de diámetro y produce flores acampanadas de tonos amarillos, rosas o naranjas en primavera. Es una planta de bajo mantenimiento, ideal para principiantes.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'COL03P126', 0, '["suculenta", "roseta", "hojas carnosas", "bajo mantenimiento", "planta de exterior", "ornamental"]', '["maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135277/plantas/col03p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('COL06P109', 'Coleo', 'Plectranthus scutellarioides', 'ornamental', 'El cóleo es una planta herbácea tropical, apreciada por sus hojas vibrantes y variegadas que exhiben una amplia gama de colores como verde, rojo, púrpura y amarillo. Puede crecer hasta 75 cm de altura y es popular por su valor ornamental. Aunque sus flores son pequeñas, el atractivo principal reside en su follaje vistoso.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'COL06P109', 0, '["planta tropical", "hojas coloridas", "planta de interior", "planta de exterior", "follaje decorativo", "fácil cuidado", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135296/plantas/col06p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CON10P009', 'Conchita', 'Echeveria secunda', 'suculenta', 'Es una planta suculenta perenne de la familia de las crasuláceas, originaria de México. Se caracteriza por su crecimiento en roseta y sus hojas carnosas de color verde azulado, lo que la convierte en una planta ornamental muy apreciada.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CON10P009', 0, '["suculenta", "roseta", "México", "fácil cuidado", "ornamental", "hojas carnosas"]', '["maceta negra 10 pulgadas", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135325/plantas/con10p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('COR01L125', 'Col De Ornato', 'Brassica oleracea var. acephala', 'exterior', 'La col ornamental es una planta bienal cultivada como anual, apreciada por sus hojas grandes, rizadas o lisas, que forman rosetas de colores vibrantes como verde, morado, rosa y blanco. Su colorido se intensifica con las bajas temperaturas, siendo ideal para decorar jardines en otoño e invierno.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'COR01L125', 0, '["follaje colorido", "planta de invierno", "resistente al frío", "jardín", "maceta", "fácil cuidado", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135346/plantas/cor01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('COR04L006', 'Croto Orange', 'Codiaeum variegatum', 'ornamental', 'El Crotón (Codiaeum variegatum) es una planta tropical vibrante, apreciada por su llamativo follaje multicolor. Sus hojas presentan una rica paleta de verdes, amarillos, naranjas y rojos, a menudo con formas y patrones variados. Es una planta ornamental popular tanto para interiores como para exteriores en climas cálidos.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'COR04L006', 0, '["tropical", "follaje colorido", "planta de interior", "planta de exterior", "arbusto", "variedad"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135366/plantas/cor04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CPE03L006', 'Croto Petra', 'Codiaeum variegatum ''Petra''', 'ornamental', 'El Croton Petra (Codiaeum variegatum ''Petra'') es una planta tropical perenne conocida por su vibrante y variado follaje en tonos de verde, amarillo, naranja y rojo. Sus hojas brillantes y coriáceas la convierten en una planta ornamental popular, ideal para añadir un toque de color exótico en interiores. Puede alcanzar hasta un metro de altura en condiciones óptimas.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CPE03L006', 0, '["planta tropical", "follaje colorido", "planta de interior", "decorativa", "arbusto", "variedad", "popular"]', '["bolsa 3 litros", "bolsa 6 litros", "bolsa 2 litros", "maceta negra 7 pulgadas", "maceta negra 6 pulgadas", "bolsa 15 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135394/plantas/cpe03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CPE04L006', 'Croto Petra Amarillo', 'Codiaeum variegatum ''Petra''', 'ornamental', 'El Croton Petra es una planta ornamental tropical conocida por su espectacular follaje multicolor. Sus hojas brillantes combinan tonos verdes intensos con vetas amarillas, naranjas y rojas, creando un efecto decorativo único. Es una planta de interior popular que puede alcanzar hasta 1 metro de altura.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CPE04L006', 0, '["ornamental", "tropical", "follaje colorido", "planta de interior", "arbusto", "exótica", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135414/plantas/cpe04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CPG03L006', 'Croto Pluma De Gallo', 'Celosia argentea var. plumosa', 'ornamental', 'La celosía plumosa es una planta anual muy llamativa por sus inflorescencias erectas y plumosas, que recuerdan a coloridas plumas de aves. Sus flores, que pueden ser rojas, rosadas, anaranjadas o amarillas, destacan sobre sus hojas de verde intenso. Es ideal para jardines, balcones y terrazas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CPG03L006', 0, '["planta anual", "flores plumosas", "colores vibrantes", "jardín", "balcón", "terraza", "fácil cuidado"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135436/plantas/cpg03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CRI01L127', 'Criptomeria', 'Cryptomeria japonica', 'árbol', 'La Criptomeria, cuyo nombre científico es Cryptomeria japonica, es una conífera perenne de gran tamaño, originaria de Japón. Se caracteriza por su corteza rojiza que se desprende en tiras verticales y su denso follaje acicular de color verde que puede adquirir tonos bronceados en invierno. Es muy valorada como árbol ornamental y para la producción de madera.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CRI01L127', 0, '["Árbol", "Conífera", "Ornamental", "Jardín", "Exterior", "Resistente a heladas", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135458/plantas/cri01l127.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CRI03L009', 'Crinum Enano', 'Crinum sp.', 'ornamental', 'Es una planta bulbosa perenne que produce vistosas flores grandes y fragantes, similares a los lirios, en tonos de blanco, rosa o rojo. Sus hojas son largas y en forma de cinta. Las variedades ''enanas'' son más compactas, ideales para espacios pequeños o macetas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CRI03L009', 0, '["Bulbosa", "Flores grandes", "Fragante", "Perenne", "Jardín", "Tropical"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135477/plantas/cri03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CRI06P121', 'Criptantus', 'Cryptanthus', 'ornamental', 'Cryptanthus es un género de plantas fanerógamas de la familia Bromeliaceae, originario de Brasil. Son conocidas como "Estrellas de la Tierra" por sus hojas en forma de roseta, que vienen en varios colores y patrones. Son plantas terrestres, lo que significa que crecen en el suelo en lugar de adherirse a los árboles.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CRI06P121', 0, '["planta de interior", "bromelia", "estrella de tierra", "follaje colorido", "tropical", "bajo mantenimiento"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135495/plantas/cri06p121.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CRI15L006', 'Crinum', 'Crinum', 'ornamental', 'El Crinum es un género de plantas bulbosas perennes, conocido por sus grandes bulbos y largas hojas en forma de cinta. Produce vistosas flores en forma de trompeta, a menudo fragantes, que pueden ser blancas, rosadas o rojas, y que emergen en tallos altos sin hojas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CRI15L006', 0, '["bulbosa", "perenne", "floración estival", "fragante", "resistente", "jardín"]', '["bolsa 15 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135517/plantas/cri15l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CSA03L077', 'Cerezo Sakura Rellena R Bonsai', 'Prunus serrulata ''Kanzan''', 'ornamental', 'El Cerezo Sakura ''Kanzan'' es un árbol caducifolio ornamental, muy apreciado por sus espectaculares y abundantes flores dobles de color rosa intenso que aparecen en primavera, a menudo antes de que broten las hojas. Sus hojas emergen en tono bronce, maduran a verde brillante y adquieren tonalidades naranja-bronce o rojizas en otoño. Es una variedad popular para bonsái debido a su vigor y hermosa floración.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'CSA03L077', 0, '["bonsái", "floración primaveral", "cerezo japonés", "doble flor", "exterior", "árbol"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135536/plantas/csa03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CSE12P114', 'Cuna Sensacion', 'Spathiphyllum ''Sensation''', 'interior', 'La Cuna Sensación es una variedad de Spathiphyllum, conocida por su gran tamaño y sus elegantes flores blancas en forma de espata. Posee hojas verdes brillantes y es muy apreciada como planta de interior por su belleza ornamental y su capacidad para purificar el aire. Puede alcanzar hasta 1.5 metros de altura, convirtiéndose en un punto focal en cualquier espacio.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CSE12P114', 0, '["Planta de interior", "Purificadora de aire", "Flor blanca", "Hojas grandes", "Tropical", "Fácil cuidado", "popular"]', '["maceta negra 12 pulgadas", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135553/plantas/cse12p114.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CTO03L003', 'Croto Tornillo', 'Codiaeum variegatum', 'ornamental', 'El Croto Tornillo es una variedad de Codiaeum variegatum, conocido por sus hojas alargadas y retorcidas que recuerdan a un tornillo. Presenta una vibrante mezcla de colores que van desde el verde oscuro hasta tonos rojos, amarillos y naranjas. Es un arbusto perenne tropical que puede alcanzar hasta 1.5 metros de altura en exteriores.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CTO03L003', 0, '["hojas retorcidas", "colores vibrantes", "tropical", "arbusto", "planta de interior", "planta de exterior", "popular"]', '["bolsa 3 litros", "bolsa 2 litros", "bolsa 15 litros", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135582/plantas/cto03l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CTO10L010', 'Clavo Tobira', 'Pittosporum tobira', 'ornamental', 'El Clavo Tobira, o Pittosporum tobira, es un arbusto o pequeño árbol perennifolio originario de Japón, Corea y China. Se caracteriza por sus hojas coriáceas de color verde oscuro brillante y sus fragantes flores blancas que aparecen en primavera, tornándose amarillentas. Es una planta ornamental muy apreciada por su adaptabilidad y resistencia, utilizada en jardinería para setos o como ejemplar aislado.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CTO10L010', 0, '["arbusto", "siempreverde", "flores fragantes", "jardinería", "resistente", "seto"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135601/plantas/cto10l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CUA30L129', 'Cuatecomate', 'Crescentia alata Kunth', 'medicinal', 'El Cuatecomate es un árbol que puede alcanzar hasta 14 metros de altura, con corteza café claro y hojas agrupadas de tres en tres. Su fruto es ampliamente valorado y utilizado en la medicina tradicional mexicana para diversas afecciones, especialmente respiratorias y ginecológicas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CUA30L129', 0, '["medicinal", "árbol", "tropical", "fruto", "tradicional", "bajo mantenimiento"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135620/plantas/cua30l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CVE02L164', 'Clavo Verde', 'Pittosporum tobira', 'ornamental', 'Es un arbusto vigoroso de hoja perenne, con hojas verdes brillantes y densas. Produce pequeñas flores muy fragantes de color blanco a amarillo en primavera y principios de verano, seguidas de frutos en cápsulas con semillas pegajosas. Puede alcanzar hasta 7 metros de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'CVE02L164', 0, '["arbusto", "perenne", "seto", "fragante", "bajo mantenimiento", "exterior", "azahar de la china", "clavo verde asiático", "popular"]', '["bolsa 2 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135642/plantas/cve02l164.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('CVE45L077', 'Ciruelo Verde', 'Prunus domestica ''Reine-Claude Verte''', 'árbol', 'El Ciruelo Verde, o Reina Claudia Verde, es un árbol frutal caducifolio que produce ciruelas de tamaño pequeño a mediano, de piel verde-amarillenta y pulpa dulce y jugosa. Florece en primavera con flores blancas y sus frutos maduran a finales de agosto.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'CVE45L077', 0, '["árbol frutal", "caducifolio", "ciruela", "Reina Claudia", "frutos dulces", "exterior"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135659/plantas/cve45l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DAY03L009', 'Dayanela', 'Dianella', 'ornamental', 'La Dianella, también conocida como lirio de lino, es una planta herbácea perenne que forma matas con follaje alargado y similar a cintas. Produce pequeñas flores azules o blancas, seguidas de atractivas bayas azules. Es muy valorada en jardinería por su bajo mantenimiento y su capacidad para añadir textura y color a los paisajes.', 'media sombra', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'DAY03L009', 0, '["ornamental", "follaje", "bajo mantenimiento", "lirio de lino", "exterior", "resistente sequía"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135681/plantas/day03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DCO06P121', 'Dracena Compacta', 'Dracaena fragrans ''Compacta''', 'interior', 'La Dracaena Compacta es una planta de interior muy popular, conocida por su apariencia compacta y sus hojas de color verde oscuro y brillante. Es un arbusto de crecimiento lento, con hojas cortas y rígidas que forman rosetas densas, ideal para espacios reducidos y para purificar el aire.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DCO06P121', 0, '["planta de interior", "fácil cuidado", "purificadora de aire", "hojas verdes", "crecimiento lento", "compacta", "popular"]', '["maceta negra 6 pulgadas", "bolsa 20 litros", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135699/plantas/dco06p121.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DCU08L009', 'Duranta Cuba', 'Duranta erecta ''Cuban Gold''', 'ornamental', 'La Duranta erecta ''Cuban Gold'' es un arbusto perenne conocido por su vibrante follaje amarillo dorado a chartreuse. Produce racimos de pequeñas flores de color lila o azul, seguidas de atractivas bayas doradas. Es una planta ornamental popular en jardines tropicales y subtropicales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DCU08L009', 0, '["Arbusto", "Exterior", "Follaje dorado", "Flores azules", "Bayas tóxicas", "Fácil cuidado", "popular"]', '["bolsa 8 litros", "bolsa 4 litros", "bolsa 45 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135719/plantas/dcu08l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DDI20L077', 'Durazno Nectarino', 'Prunus persica var. nucipersica', 'árbol', 'El durazno nectarino es un árbol frutal caducifolio, una variedad del durazno que se distingue por su piel lisa y sin vello. Produce frutos jugosos y dulces, de color rojizo o amarillo, y en primavera se adorna con hermosas flores rosadas. Es apreciado tanto por su valor ornamental como por su producción de fruta fresca.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'DDI20L077', 0, '["frutal", "caducifolio", "exterior", "floración primaveral", "frutos comestibles", "piel lisa"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135739/plantas/ddi20l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DEB03P126', 'Debi', '×Graptoveria ''Debbie''', 'suculenta', 'La Graptoveria ''Debbie'' es una suculenta híbrida que forma rosetas densas de hojas carnosas, lanceoladas, de color rosa escarchado a violeta rosado. Sus colores se intensifican con temperaturas más frías o estrés, y puede alcanzar hasta 20 cm de diámetro. Produce pequeñas flores de color albaricoque en primavera.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'DEB03P126', 0, '["suculenta", "roseta", "híbrido", "fácil cuidado", "exterior", "ornamental"]', '["maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135757/plantas/deb03p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DGO20L009', 'Duranta Gold', 'Duranta erecta ''Gold Mound''', 'ornamental', 'La Duranta ''Gold Mound'' es un arbusto de crecimiento rápido con un follaje dorado-verde muy luminoso. Produce flores lilas o azul claro que atraen polinizadores y, posteriormente, bayas decorativas de color naranja. Es ideal para setos, bordes o como planta ornamental en jardines y terrazas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DGO20L009', 0, '["arbusto", "follaje dorado", "exterior", "seto", "crecimiento rápido", "atrae polinizadores", "popular"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135774/plantas/dgo20l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DIC10P109', 'Dichondria', 'Dichondra repens', 'ornamental', 'Es una planta perenne rastrera que forma una densa alfombra verde brillante con hojas pequeñas y redondeadas, a menudo utilizada como alternativa al césped. Se extiende rápidamente y puede trepar o colgar, ofreciendo un aspecto ornamental.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'DIC10P109', 0, '["cubresuelos", "alternativa césped", "bajo mantenimiento", "perenne", "rastrera", "jardín"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135795/plantas/dic10p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DIN40L157', 'Dracena Indivisa España', 'Cordyline indivisa', 'ornamental', 'La Cordyline indivisa, también conocida como Dracena Indivisa, es un árbol o arbusto monocotiledóneo originario de Nueva Zelanda. Se caracteriza por su tronco robusto y sus hojas largas, en forma de correa, de color verde azulado a verde, a menudo con venas rojizas o amarillentas. Es apreciada por su follaje dramático y su aspecto tropical, utilizada tanto en jardines como en macetas.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DIN40L157', 0, '["árbol", "arbusto", "follaje atractivo", "planta de exterior", "planta de interior", "tropical"]', '["bolsa 40 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135818/plantas/din40l157.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DIP06P200', 'Diplademia', 'Mandevilla spp.', 'ornamental', 'La dipladenia, también conocida como mandevilla, es una planta trepadora tropical apreciada por sus vistosas flores en forma de trompeta. Sus flores, que pueden ser blancas, rosas o rojas, florecen desde primavera hasta otoño, ofreciendo un espectáculo visual duradero. Es una planta de fácil cuidado, ideal para embellecer jardines, balcones o interiores bien iluminados.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DIP06P200', 0, '["Planta trepadora", "Flores vistosas", "Floración duradera", "Planta ornamental", "Tóxica", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135842/plantas/dip06p200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DMA20L001', 'Dracena Marginata', 'Dracaena marginata', 'interior', 'La Dracaena marginata, también conocida como drácena de Madagascar, es una planta arbustiva de origen tropical, popular por sus esbeltos troncos y hojas perennes de color verde oscuro con bordes rojizos. Es muy apreciada como planta de interior por su atractivo ornamental y su capacidad para purificar el aire. Su crecimiento es lento y rara vez florece en ambientes domésticos.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'DMA20L001', 0, '["planta de interior", "follaje decorativo", "fácil cuidado", "tropical", "purificadora de aire", "tóxica para mascotas"]', '["bolsa 20 litros", "bolsa 10 litros", "maceta negra 11 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135864/plantas/dma20l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DOL04L115', 'Dolar', 'Plectranthus verticillatus', 'ornamental', 'Es una planta perenne de interior popular, conocida por sus hojas redondas, verdes y brillantes, y sus tallos colgantes. Originaria de Sudáfrica, es apreciada por su facilidad de cuidado y su atractivo decorativo. Se asocia comúnmente con la buena suerte y la fortuna.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'DOL04L115', 0, '["Planta del dinero", "Hiedra sueca", "Colgante", "Fácil cuidado", "Buena suerte", "Decorativa"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135884/plantas/dol04l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DRA45L006', 'Dracena Draco', 'Dracaena draco', 'árbol', 'La Dracaena draco, conocida como drago o árbol dragón de Canarias, es un árbol subtropical de crecimiento lento originario de Macaronesia. Se distingue por su tronco grueso y ramificado, y rosetas de hojas largas, en forma de espada y de color azul-verde. Produce una savia rojiza, llamada "sangre de dragón", que le confiere su nombre popular.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'DRA45L006', 0, '["árbol dragón", "Canarias", "suculenta", "resistente a la sequía", "ornamental", "exterior"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135902/plantas/dra45l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DRO04L200', 'Dracena Roja', 'Dracaena marginata', 'ornamental', 'La Dracaena marginata, conocida como Dracena Roja o Dragón de Madagascar, es una planta ornamental de interior muy popular. Se caracteriza por sus hojas largas, finas y puntiagudas con distintivos bordes rojizos, que crecen en tallos delgados y ramificados. Es una planta resistente y de fácil cuidado, apreciada también por su capacidad para purificar el aire.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DRO04L200', 0, '["planta de interior", "purifica el aire", "bajo mantenimiento", "hojas rojizas", "tropical", "decorativa", "popular"]', '["bolsa 4 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135922/plantas/dro04l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DUR70L077', 'Durazno Oro Azteka', 'Prunus persica', 'árbol', 'El Durazno Oro Azteka es un árbol frutal de tamaño mediano, que puede alcanzar entre 5 y 8 metros de altura. Produce frutos de pulpa amarilla o naranja, dulces y jugosos, con cáscara que puede ser naranja, amarilla o roja. Sus flores son rosadas y muy vistosas.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'DUR70L077', 0, '["frutal", "árbol", "durazno", "exterior", "sol", "dulce"]', '["bolsa 70 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135947/plantas/dur70l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('DWA12P157', 'Dracena Warneki Lemon', 'Dracaena fragrans ''Lemon Lime''', 'interior', 'La Dracaena fragrans ''Lemon Lime'' es una planta de interior llamativa, conocida por sus hojas vibrantes con rayas verdes y amarillas. Crece en forma de roseta o de tallo similar a una caña, pudiendo alcanzar hasta 3 metros de altura en interiores. Es apreciada por su follaje colorido y su fácil cuidado, siendo una excelente opción para principiantes.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'DWA12P157', 0, '["planta de interior", "follaje variegado", "fácil cuidado", "purificadora de aire", "tropical", "ornamental"]', '["maceta negra 12 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135966/plantas/dwa12p157.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EAM06P006', 'Euphorbia Mini Roja', 'Euphorbia milii', 'ornamental', 'La Euphorbia milii, conocida comúnmente como Corona de Cristo, es un arbusto suculento leñoso originario de Madagascar. Se caracteriza por sus tallos espinosos y sus vistosas brácteas de colores, a menudo rojas, que parecen flores. Esta planta puede florecer durante gran parte del año en condiciones adecuadas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'EAM06P006', 0, '["suculenta", "espinosa", "floración prolongada", "planta de interior", "planta de exterior", "Corona de Cristo", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777135985/plantas/eam06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EBA60L145', 'Ebano', 'Diospyros ebenum J. Koenig ex Retz.', 'árbol', 'Es un árbol tropical de hoja perenne y crecimiento lento, que puede alcanzar entre 20 y 30 metros de altura. Es altamente valorado por su duramen denso y de color negro azabache, utilizado en ebanistería fina e instrumentos musicales. Sus hojas son elípticas y sus pequeños frutos se asemejan a un caqui.', 'sol directo', 'medio', 'difícil', 'disponible', 'ambas', 'tóxica', 'EBA60L145', 0, '["árbol tropical", "madera preciosa", "ebanistería", "crecimiento lento", "ornamental", "medicinal"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136018/plantas/eba60l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EES02L105', 'Esparrago Springueri', 'Asparagus densiflorus ''Sprengeri''', 'ornamental', 'El Espárrago Sprengeri es una planta herbácea perenne con tallos arqueados y un follaje fino y plumoso compuesto por cladodios en forma de aguja. Produce pequeñas flores blancas fragantes seguidas de llamativas bayas rojas. Es apreciada por su adaptabilidad y su atractivo follaje verde brillante.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'EES02L105', 0, '["helecho de espárrago", "planta de interior", "planta de exterior", "follaje decorativo", "resistente", "bayas rojas", "popular"]', '["bolsa 2 litros", "maceta negra 10 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136038/plantas/ees02l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ELE03L009', 'Eleagnus', 'Elaeagnus x ebbingei', 'exterior', 'El Eleagnus x ebbingei es un arbusto perenne vigoroso, conocido por sus hojas de color verde oscuro en el haz y plateadas en el envés. Produce pequeñas flores fragantes en otoño y frutos rojizos comestibles en primavera. Es una planta muy rústica y adaptable, ideal para setos y jardines.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ELE03L009', 0, '["arbusto", "perenne", "resistente", "fácil cuidado", "seto", "fijador de nitrógeno", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136064/plantas/ele03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ELI01L125', 'Elia', 'Dimorphotheca ecklonis', 'ornamental', 'Es una planta perenne semiarbustiva con flores parecidas a margaritas, que pueden ser moradas, blancas, amarillas o bicolores. Puede alcanzar hasta 70 cm de altura en maceta y hasta 2 metros en exterior, formando grandes matas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ELI01L125', 0, '["margarita", "floración prolongada", "resistente", "exterior", "sempervirente", "polinizadores"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136096/plantas/eli01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EME06P006', 'Esparrago Meyeri', 'Asparagus densiflorus ''Myers''', 'ornamental', 'El Espárrago Meyeri, o helecho cola de zorro, es una planta perenne ornamental con tallos erguidos y densos, cubiertos de hojas finas y suaves que le dan una apariencia plumosa. Produce pequeñas flores blancas y bayas rojas decorativas. Es apreciada por su textura y contraste en jardines y macetas.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'EME06P006', 0, '["helecho cola de zorro", "planta ornamental", "follaje denso", "maceta", "exterior", "interior", "popular"]', '["maceta negra 6 pulgadas", "bolsa 6 litros", "bolsa 2 litros", "bolsa 8 litros", "bolsa 3 litros", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136117/plantas/eme06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EPL06P006', 'Esparrago Plumoso', 'Asparagus setaceus', 'ornamental', 'El Espárrago Plumoso es una planta perenne de follaje fino y suave, que le confiere un aspecto plumoso y delicado. No es un helecho verdadero, sino una planta trepadora con tallos alambrados que pueden crecer o colgar. Produce pequeñas flores blanquecinas poco vistosas, seguidas de bayas verdes que maduran a negras.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'EPL06P006', 0, '["Planta de interior", "Follaje plumoso", "Trepador", "Ornamental", "Fácil cuidado", "Tóxica para mascotas", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136141/plantas/epl06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EPL18L010', 'Eleagnus Plateado', 'Elaeagnus x ebbingei', 'exterior', 'El Elaeagnus x ebbingei es un arbusto perenne de follaje denso, con hojas elípticas de color verde oscuro en el haz y plateado en el envés. Produce pequeñas flores blancas fragantes en otoño, seguidas de frutos rojos comestibles en primavera.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'EPL18L010', 0, '["arbusto", "perenne", "follaje plateado", "seto", "resistente", "exterior", "popular"]', '["bolsa 18 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136163/plantas/epl18l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ERI03L125', 'Erika', 'Erica', 'exterior', 'La Erica es un género de arbustos perennes conocido por sus diminutas hojas aciculares y su abundante floración. Sus flores, que varían en color desde el blanco al rosa y púrpura, aparecen en diversas épocas del año, ofreciendo un atractivo ornamental. La mayoría de las especies son de tamaño modesto, aunque algunas pueden alcanzar varios metros de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ERI03L125', 0, '["arbusto", "ornamental", "perenne", "flores", "acidófila", "resistente"]', '["bolsa 3 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136187/plantas/eri03l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ERO60L006', 'Encino Rojo', 'Quercus rubra', 'árbol', 'El Encino Rojo (Quercus rubra) es un árbol caducifolio de tamaño mediano a grande, nativo de Norteamérica. Se distingue por su copa redondeada y extendida, y por el espectacular color rojo intenso que adquieren sus hojas en otoño. Es una especie resistente y valorada tanto por su madera como por su uso ornamental y medicinal.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ERO60L006', 0, '["árbol de sombra", "follaje otoñal", "resistente", "nativo de Norteamérica", "madera", "medicinal"]', '["bolsa 60 litros", "bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136210/plantas/ero60l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ESA06P003', 'Euphorbia Salmon', 'Euphorbia x lomi ''Salmon''', 'suculenta', 'La Euphorbia x lomi ''Salmon'' es un arbusto suculento de hoja perenne que alcanza entre 60 y 90 cm de altura, con tallos espinosos de color gris. Sus vistosas brácteas florales, de color salmón, pueden aparecer durante todo el año en climas suaves. Es una planta de bajo mantenimiento, ideal para jardines de rocas o macetas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ESA06P003', 0, '["arbusto", "ornamental", "espinosa", "floración prolongada", "exterior", "resistente a la sequía", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136227/plantas/esa06p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EST01L125', 'Estafiate', 'Artemisia ludoviciana', 'medicinal', 'El estafiate es una hierba perenne aromática, conocida por su follaje plateado o gris-verdoso y su uso tradicional en la medicina. Alcanza hasta un metro de altura y sus pequeñas flores amarillentas son discretas. Es una planta resistente que se propaga vigorosamente por rizomas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'EST01L125', 0, '["planta medicinal", "hierba aromática", "follaje plateado", "resistente a sequía", "invasiva", "usos tradicionales"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136256/plantas/est01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ESV60L124', 'Encino Siempre Verde', 'Quercus virginiana', 'árbol', 'El Encino Siempre Verde es un árbol perenne de gran tamaño, nativo del sur de Estados Unidos y norte de México. Puede alcanzar alturas de 12 a 24 metros con una copa frondosa que proporciona una sombra densa. Sus hojas son de color verde oscuro y produce bellotas, que son un alimento importante para la fauna silvestre.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ESV60L124', 0, '["árbol perenne", "sombra", "bellotas", "resistente a la sequía", "fácil cuidado", "exterior"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136273/plantas/esv60l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ETI01L003', 'Euphorbia Tirucalli', 'Euphorbia tirucalli L.', 'suculenta', 'La Euphorbia tirucalli, conocida como Árbol de los dedos o Planta lápiz, es una suculenta arbustiva o pequeño árbol originaria de África. Se caracteriza por sus tallos cilíndricos, carnosos y ramificados, de color verde que pueden tornarse rojizos o anaranjados con la exposición al sol. Sus hojas son diminutas y caducas, realizando la fotosíntesis principalmente a través de sus distintivos tallos.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ETI01L003', 0, '["Árbol de los dedos", "Planta lápiz", "Suculenta", "Tóxica", "Fácil cuidado", "Exterior", "popular"]', '["bolsa 1 litros", "maceta negra 6 pulgadas", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136296/plantas/eti01l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EUC06P106', 'Eucharis', 'Eucharis', 'ornamental', 'Eucharis es un género de plantas herbáceas, perennes y bulbosas, conocidas popularmente como "lirios del Amazonas". Produce atractivas flores blancas, fragantes y colgantes que se asemejan a los narcisos. Sus hojas son grandes, de color verde brillante y forma ovalada.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'EUC06P106', 0, '["bulbosa", "flores blancas", "fragante", "tropical", "interior", "exterior"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136315/plantas/euc06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EUF06P006', 'Euphorbia Mini', 'Euphorbia milii', 'ornamental', 'La Euphorbia milii, comúnmente conocida como Corona de Cristo, es un arbusto suculento y espinoso originario de Madagascar. Se distingue por sus tallos leñosos cubiertos de espinas y sus pequeñas flores rodeadas de vistosas brácteas de colores variados. Esta planta es apreciada por su floración prolongada, que puede durar gran parte del año en condiciones adecuadas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'EUF06P006', 0, '["espinosa", "arbusto", "suculenta", "floración prolongada", "Madagascar", "resistente a la sequía", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136335/plantas/euf06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EUG30L170', 'Eugenia', 'Eugenia', 'ornamental', 'Eugenia es un género de plantas con flores perteneciente a la familia Myrtaceae, que incluye arbustos y árboles perennes. Se caracteriza por su atractivo follaje brillante, a menudo con brotes rojizos en los brotes jóvenes, y sus flores blancas que dan lugar a frutos tipo baya. Muchas de sus especies son cultivadas como ornamentales por su valor estético y algunas producen frutos comestibles.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'EUG30L170', 0, '["Ornamental", "Arbusto", "Follaje brillante", "Fácil cuidado", "Exterior", "Frutal"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136365/plantas/eug30l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EUP06P011', 'Euphorbia', 'Euphorbia', 'ornamental', 'Euphorbia es un género muy extenso y diverso de plantas, que incluye desde pequeños árboles y arbustos hasta plantas herbáceas y suculentas, distribuidas mundialmente. Se caracterizan por su savia lechosa (látex), que es irritante y tóxica, y por su inflorescencia única llamada ciatio. Muchas especies son valoradas como plantas ornamentales, adaptándose a una variedad de climas y condiciones.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'EUP06P011', 0, '["suculenta", "planta ornamental", "savia lechosa", "diversa", "tóxica", "ciatio"]', '["maceta negra 6 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136388/plantas/eup06p011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('EVO01L077', 'Evonimo', 'Euonymus', 'ornamental', 'El Evónimo es un género diverso de arbustos, pequeños árboles y trepadoras, tanto caducifolios como perennifolios. Se valora por su atractivo follaje, que a menudo presenta colores otoñales vibrantes, y por sus decorativas bayas. Sus hojas son típicamente opuestas, simples, ovoides, coriáceas y brillantes.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'EVO01L077', 0, '["Arbusto", "Perennifolio", "Seto", "Follaje colorido", "Resistente", "Tóxica", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136414/plantas/evo01l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FBA07P168', 'Ficus Bambino', 'Ficus lyrata ''Bambino''', 'interior', 'La Ficus lyrata ''Bambino'' es una variedad enana del popular Ficus lyrata, conocida por sus hojas más pequeñas, compactas y brillantes en forma de violín. Crece de forma erguida y es ideal para espacios interiores pequeños, añadiendo un toque elegante y exuberante.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'FBA07P168', 0, '["planta de interior", "Ficus", "hoja de violín", "compacta", "follaje verde", "tropical"]', '["maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136430/plantas/fba07p168.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FBE10L136', 'Ficus Benjamina', 'Ficus benjamina L.', 'ornamental', 'El Ficus benjamina es un árbol ornamental muy popular, conocido por su follaje denso y brillante, y su forma elegante. En condiciones naturales puede alcanzar hasta 30 metros de altura, pero en interiores se cultiva como un árbol pequeño o bonsái. Sus hojas son pequeñas, ovales, de color verde brillante y con un ápice acuminado.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'FBE10L136', 0, '["planta de interior", "árbol", "follaje verde", "decorativa", "sensible a cambios", "tóxica para mascotas"]', '["bolsa 10 litros", "bolsa 6 litros", "bolsa 20 litros", "bolsa 30 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136446/plantas/fbe10l136.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FEI45L124', 'Feijoa', 'Acca sellowiana', 'árbol', 'La Feijoa, también conocida como guayabo del Brasil, es un arbusto o pequeño árbol frutal perenne, valorado por su fragante floración y sus deliciosos frutos comestibles de sabor tropical. Alcanza entre 2 y 4 metros de altura, con hojas elípticas de haz verde brillante y envés blanquecino.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'FEI45L124', 0, '["frutal", "ornamental", "perenne", "exterior", "resistente", "comestible"]', '["bolsa 45 litros", "bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136475/plantas/fei45l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FHE45L077', 'Ficus Hector', 'Ficus carica ''All Year Héctor®''', 'árbol', 'Es una variedad de higuera (Ficus carica) registrada, conocida por producir frutos grandes y alargados, de color rojo oscuro con pulpa roja. Fructifica desde una edad temprana y durante casi todo el año en condiciones óptimas. Puede cultivarse tanto en interiores como en exteriores.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'FHE45L077', 0, '["Higuera", "Frutal", "Interior", "Exterior", "Ficus", "Tóxica"]', '["bolsa 45 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136520/plantas/fhe45l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FMA65L140', 'Flor De Mayo', 'Plumeria rubra', 'árbol', 'La Plumeria rubra, conocida como Flor de Mayo, es un árbol o arbusto tropical de 3 a 8 metros de altura, con ramas gruesas y hojas grandes. Sus flores son muy fragantes, con cinco pétalos en forma de hélice, y varían en colores como blanco, rosa, amarillo o rojo. Es apreciada por su valor ornamental y su intenso aroma.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'FMA65L140', 0, '["árbol tropical", "flores fragantes", "ornamental", "exterior", "resistente a sequía", "savia tóxica"]', '["bolsa 65 litros", "bolsa 10 litros", "bolsa 75 litros", "bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136542/plantas/fma65l140.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FMO15L077', 'Ficus Moclame', 'Ficus microcarpa ''Moclame''', 'interior', 'El Ficus microcarpa ''Moclame'' es una planta tropical de interior con follaje denso y compacto, caracterizado por sus hojas pequeñas, ovaladas y de un verde brillante. Es apreciado por su forma esférica y su adaptabilidad a diferentes entornos interiores, pudiendo alcanzar hasta 3 metros de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'FMO15L077', 0, '["planta de interior", "follaje verde", "fácil cuidado", "tropical", "purificadora de aire", "árbol pequeño"]', '["bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136563/plantas/fmo15l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FOR04L077', 'Forneo Verde', 'Phormium tenax', 'ornamental', 'Planta herbácea perenne con hojas rígidas en forma de espada, de color verde oscuro, que crecen en rosetas basales y pueden alcanzar hasta 3 metros de altura. Produce panículas de flores tubulares rojas en tallos altos durante el verano. Es muy valorada por su uso ornamental y sus fibras textiles.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'FOR04L077', 0, '["herbácea", "perenne", "exterior", "bajo mantenimiento", "hojas en forma de espada", "fibra"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136588/plantas/for04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FPA04L077', 'Ficus Pandurata', 'Ficus lyrata', 'ornamental', 'El Ficus lyrata, también conocido como Ficus pandurata o higuera hoja de violín, es un árbol o arbusto de hoja perenne originario de África tropical. Se caracteriza por sus grandes hojas coriáceas, brillantes y con venas prominentes, que recuerdan la forma de una lira o violín. Es muy apreciado como planta ornamental de interior por su atractivo follaje.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'FPA04L077', 0, '["planta de interior", "hojas grandes", "árbol lira", "tropical", "decorativa", "Ficus", "popular"]', '["bolsa 4 litros", "bolsa 20 litros", "bolsa 60 litros", "maceta negra 8 pulgadas", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136608/plantas/fpa04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FPE06P006', 'Ficus Petiolaris', 'Ficus petiolaris', 'suculenta', 'El Ficus petiolaris es un árbol o arbusto suculento nativo de México, conocido por su distintivo caudex hinchado y sus hojas acorazonadas de color verde grisáceo con venas prominentes. Es una planta de crecimiento lento que puede cultivarse como árbol pequeño, arbusto o bonsái, y es apreciada por su tolerancia a la sequía. Su savia es irritante y la planta es tóxica si se ingiere, especialmente para mascotas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'FPE06P006', 0, '["suculenta", "árbol", "caudiciforme", "México", "hojas acorazonadas", "bonsái", "popular"]', '["maceta negra 6 pulgadas", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136629/plantas/fpe06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FRE02L113', 'Fresno', 'Fraxinus excelsior', 'árbol', 'El fresno es un árbol de hoja caduca que puede alcanzar entre 10 y 40 metros de altura, con un tronco recto y una copa amplia y redondeada. Sus hojas son compuestas, formadas por varios folíolos, y produce pequeñas flores seguidas de frutos alados llamados sámaras. Es valorado por su robustez, rápido crecimiento y la sombra que proporciona.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'FRE02L113', 0, '["árbol caducifolio", "sombra", "madera", "ornamental", "exterior", "resistente al frío"]', '["bolsa 2 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136650/plantas/fre02l113.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FRE06P125', 'Fresa', 'Fragaria x ananassa', 'exterior', 'La fresa (Fragaria x ananassa) es una planta herbácea perenne y rastrera, conocida por sus estolones y hojas trifoliadas. Es ampliamente cultivada por su delicioso fruto comestible, que es en realidad un engrosamiento del receptáculo floral. Además de su valor culinario, se le atribuyen propiedades medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'FRE06P125', 0, '["fruta", "herbácea", "perenne", "comestible", "huerto", "rastrera", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136672/plantas/fre06p125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FRO30L103', 'Falso Romero', 'Teucrium fruticans', 'ornamental', 'El Falso Romero, o Teucrium fruticans, es un arbusto perenne muy ramificado, nativo de la cuenca mediterránea. Se caracteriza por sus pequeñas hojas elípticas de color verde grisáceo con un envés afelpado, que le confieren un aspecto plateado. Produce pequeñas flores unilabiadas, generalmente de color lila, que aparecen desde finales del invierno hasta mediados del verano.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'FRO30L103', 0, '["arbusto", "mediterránea", "bajo mantenimiento", "follaje plateado", "resistente", "exterior", "popular"]', '["bolsa 30 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136689/plantas/fro30l103.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FSL10L153', 'Ficus Star Ligth', 'Ficus benjamina ''Starlight''', 'ornamental', 'El Ficus benjamina ''Starlight'' es una variedad del popular Ficus benjamina, caracterizado por sus atractivas hojas variegadas en tonos verdes y blancos o crema. Puede crecer como arbusto o árbol pequeño, siendo muy valorado por su follaje decorativo. Además, es conocida por su capacidad para purificar el aire en interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'FSL10L153', 0, '["interior", "variegada", "fácil cuidado", "purificadora de aire", "árbol pequeño", "follaje decorativo"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136710/plantas/fsl10l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('FTR04L010', 'Ficus Triangularis', 'Ficus triangularis', 'interior', 'El Ficus triangularis es una planta única de la familia de las higueras, reconocida por sus hojas gruesas y distintivas en forma de corazón o triángulo. Presenta un hábito de crecimiento leñoso y rígido, y puede alcanzar hasta 2.5 metros de altura en cultivo, aunque como planta de interior suele ser más pequeña. Es apreciada por su silueta arquitectónica y su follaje brillante.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'FTR04L010', 0, '["hojas triangulares", "planta de interior", "ornamental", "ficus", "fácil cuidado"]', '["bolsa 4 litros", "bolsa 10 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136731/plantas/ftr04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GAR20L170', 'Gardenia', 'Gardenia jasminoides', 'ornamental', 'La Gardenia jasminoides es un arbusto perennifolio originario de Asia, conocido por sus hojas verdes brillantes y sus vistosas flores blancas o crema de intenso y dulce aroma. Puede crecer hasta 2 metros de altura y es apreciada tanto en jardines como en interiores.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'GAR20L170', 0, '["arbusto", "flores fragantes", "hojas brillantes", "planta acidófila", "jardín", "interior"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136761/plantas/gar20l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GAS04P126', 'Gasteria', 'Gasteria spp.', 'suculenta', 'Las Gasterias son plantas suculentas originarias de Sudáfrica, caracterizadas por sus hojas gruesas, carnosas y en forma de lengua, que pueden ser lisas, rugosas o con protuberancias. Crecen en rosetas o en dos hileras opuestas, y producen flores tubulares con forma de estómago, generalmente en tonos rosados o anaranjados.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GAS04P126', 0, '["suculenta", "planta de interior", "fácil cuidado", "hojas decorativas", "tolerante a la sequía", "Sudáfrica"]', '["maceta negra 4 pulgadas", "maceta negra 6 pulgadas", "maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136779/plantas/gas04p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GCA12L010', 'Guayabo California', 'Acca sellowiana', 'árbol', 'Es un arbusto o árbol pequeño perenne, de 4 a 8 metros de altura, con follaje grisáceo y tronco tortuoso de corteza escamosa. Sus hojas son coriáceas, verde oscuro brillante en el haz y tomentosas en el envés. Produce flores ornamentales con pétalos blanco-rosados y estambres rojos o amarillos, y frutos comestibles en forma de baya oblonga de pulpa carnosa y aromática.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'GCA12L010', 0, '["frutal", "ornamental", "arbusto", "perenne", "subtropical", "comestible", "popular"]', '["bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136830/plantas/gca12l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GCA20L077', 'Guayabo Calvillo', 'Psidium guajava "Calvillo"', 'árbol', 'El Guayabo Calvillo es una variedad de guayaba (Psidium guajava) originaria de las regiones subtropicales de América, especialmente cultivada en Calvillo, Aguascalientes, México. Se caracteriza por sus frutos redondos de cáscara amarilla y pulpa blanca, con un aroma intenso y sabor dulce. Es altamente valorada por su alto contenido de vitamina C y sus cualidades nutritivas.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'GCA20L077', 0, '["Frutal", "Tropical", "Subtropical", "Vitamina C", "México", "Aguascalientes"]', '["bolsa 20 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136797/plantas/gca20l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GFI05P130', 'Goldfish', 'Nematanthus gregarius', 'ornamental', 'La planta Goldfish (Nematanthus gregarius) es una planta tropical perenne conocida por sus flores únicas en forma de pez dorado, de colores naranja, rojo o amarillo, que contrastan con su follaje verde oscuro y brillante. Tiene un hábito de crecimiento colgante o rastrero, lo que la hace ideal para cestas colgantes y como planta de interior decorativa. Es originaria de los bosques tropicales de Brasil.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GFI05P130', 0, '["planta de interior", "colgante", "flores naranjas", "follaje brillante", "tropical", "fácil cuidado"]', '["maceta negra 5 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136849/plantas/gfi05p130.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GOS04P003', 'Garrita De Oso Varigado', 'Cotyledon tomentosa f. variegata', 'suculenta', 'Es una pequeña suculenta arbustiva con hojas gruesas, aterciopeladas y en forma de cuña, rayadas en tonos verdes y crema, que se asemejan a las patas de un oso. Puede crecer hasta 50 cm de altura y produce flores de color coral pálido a blanco o amarillento.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'GOS04P003', 0, '["suculenta", "variegada", "hojas peludas", "crassulaceae", "planta de interior", "planta de exterior"]', '["maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136880/plantas/gos04p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GPE10L010', 'Guayaba Peruana', 'Psidium cattleianum', 'árbol', 'Es un arbusto o árbol pequeño perennifolio, que alcanza entre 1 y 4 metros de altura. Sus hojas son de color verde oscuro y brillantes, y produce flores blancas. Los frutos son bayas esféricas de color rojo o morado al madurar, dulces y comestibles.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GPE10L010', 0, '["Frutal", "Ornamental", "Arbusto", "Perennifolio", "Comestible", "Subtropical"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136902/plantas/gpe10l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GPI30L006', 'Guayabo Piña', 'Acca sellowiana', 'árbol', 'La Acca sellowiana, conocida como Guayabo Piña, es un arbusto o árbol pequeño perenne que alcanza entre 1 y 7 metros de altura. Posee hojas oblongas de color verde oscuro en el haz y blanco plateado en el envés. Sus vistosas flores tienen pétalos blanquecinos y estambres rojos, produciendo frutos ovalados y verdes con un sabor que recuerda a la piña.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GPI30L006', 0, '["frutal", "ornamental", "perenne", "resistente a la sequía", "flores comestibles", "arbusto"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136924/plantas/gpi30l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GRA45L010', 'Granada', 'Punica granatum', 'árbol', 'El granado (*Punica granatum*) es un arbusto o pequeño árbol caducifolio que alcanza entre 1.5 y 5 metros de altura. Se caracteriza por sus hojas verdes brillantes, flores vistosas de color rojo anaranjado y frutos redondos con una piel coriácea y arilos jugosos y comestibles. Es una planta cultivada desde la antigüedad por su fruto y su valor ornamental.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GRA45L010', 0, '["frutal", "ornamental", "caducifolio", "resistente a la sequía", "exterior", "mediterráneo"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136946/plantas/gra45l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GRE30L113', 'Grevilia', 'Grevillea', 'ornamental', 'Grevillea es un género de plantas perennes, en su mayoría arbustos o árboles originarios de Australia, conocidas por sus flores únicas, a menudo descritas como parecidas a arañas o cepillos. Su follaje es variado, desde hojas finamente divididas hasta en forma de aguja, y son muy valoradas en jardinería por su atractivo ornamental y su larga floración.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'GRE30L113', 0, '["arbusto", "árbol", "flores exóticas", "Australia", "resistente a la sequía", "bajo mantenimiento"]', '["bolsa 30 litros", "bolsa 65 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136967/plantas/gre30l113.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GUA02P116', 'Guanabana', 'Annona muricata', 'árbol', 'La guanábana (Annona muricata) es un árbol perenne de 3 a 10 metros de altura, con hojas verdes brillantes y un tronco ramificado. Produce un fruto grande, verde oscuro y espinoso, con pulpa blanca, jugosa y aromática.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'GUA02P116', 0, '["frutal", "tropical", "medicinal", "comestible", "árbol", "Annona muricata"]', '["maceta negra 2 pulgadas", "bolsa 30 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137002/plantas/gua02p116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GUA03L113', 'Guamuchil', 'Pithecellobium dulce', 'árbol', 'El guamúchil es un árbol espinoso de tamaño mediano, nativo de México y Centroamérica, que puede alcanzar entre 10 y 20 metros de altura. Produce vainas retorcidas con una pulpa dulce y comestible que rodea sus semillas. Es una especie robusta, valorada por su fruto, su sombra y sus usos medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GUA03L113', 0, '["fruto comestible", "árbol de sombra", "nativo de México", "resistente a sequía", "medicinal", "cercos vivos"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137024/plantas/gua03l113.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GUA03L129', 'Guaje', 'Leucaena leucocephala', 'árbol', 'El guaje (*Leucaena leucocephala*) es un arbusto o árbol de rápido crecimiento, que generalmente mide entre 2 y 10 metros de altura, aunque puede alcanzar hasta 20 metros. Se caracteriza por sus hojas bipinnadas, flores esféricas de color crema y vainas alargadas que contienen numerosas semillas. Es una especie versátil utilizada para forraje, leña, sombra y como ornamental, pero también es conocida por su carácter invasor en muchas regiones.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'GUA03L129', 0, '["árbol", "leguminosa", "forraje", "medicinal", "invasora", "ornamental"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137045/plantas/gua03l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GUA04L077', 'Guayabo Rosa', 'Psidium guajava ''Rosa''', 'árbol', 'El Guayabo Rosa es un pequeño árbol o arbusto perenne originario de América tropical, apreciado por sus frutos. Produce guayabas de pulpa rosada, dulce y muy aromática, ricas en vitamina C y antioxidantes. Se cultiva ampliamente por su valor frutal y sus propiedades medicinales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'GUA04L077', 0, '["Frutal", "Tropical", "Medicinal", "Perenne", "Vitamina C", "Antioxidante", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137067/plantas/gua04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('GUA12L124', 'Guayabo', 'Psidium guajava', 'árbol', 'El guayabo (Psidium guajava) es un arbusto o árbol pequeño perennifolio, nativo de América tropical, que puede alcanzar de 3 a 10 metros de altura. Su corteza es lisa y se desprende en placas, sus hojas son simples, opuestas y aromáticas, y produce flores blancas. Su fruto, la guayaba, es una baya redonda u ovoide que madura de verde a amarillo, con pulpa jugosa de color blanco, rosado o rojo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'GUA12L124', 0, '["frutal", "medicinal", "tropical", "perenne", "exterior", "vitamina C"]', '["bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137088/plantas/gua12l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HAM04L010', 'Hule Amarillo', 'Castilla elastica', 'árbol', 'El Hule Amarillo es un árbol tropical de rápido crecimiento, nativo de América, que puede alcanzar hasta 25 metros de altura. Se caracteriza por su tronco recto y sus hojas grandes y ásperas, y es conocido por producir látex.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'HAM04L010', 0, '["Árbol tropical", "Látex", "Crecimiento rápido", "América", "Restauración", "Ornamental"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137108/plantas/ham04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HAM12L116', 'Heliconia Amarilla', 'Heliconia spp.', 'ornamental', 'Las heliconias son plantas tropicales ornamentales, conocidas por sus vistosas inflorescencias que pueden ser amarillas, naranjas o rojas. Son plantas herbáceas perennes con grandes hojas similares a las del plátano, nativas de Centro y Sudamérica. Se utilizan ampliamente en paisajismo y como flor de corte.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HAM12L116', 0, '["tropical", "ornamental", "flor exótica", "platanillo", "jardín", "atrae colibríes", "popular"]', '["bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137130/plantas/ham12l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HAR05P130', 'Helecho Arroz', 'Pilea microphylla', 'ornamental', 'El Helecho Arroz, cuyo nombre científico es Pilea microphylla, es una planta originaria de América Central y del Sur. Se caracteriza por su follaje perenne de pequeñas hojas carnosas de color verde claro, a menudo confundida con un helecho a pesar de ser una especie de Pilea. Puede alcanzar hasta 50 cm de altura y es apreciada por su valor ornamental.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HAR05P130', 0, '["planta de interior", "planta de exterior", "no tóxica", "follaje verde", "fácil cuidado", "suculenta", "popular"]', '["maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141669/plantas/har05p130.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HAU11P077', 'Helecho Australiano', 'Cyathea cooperi', 'árbol', 'Es un helecho arborescente majestuoso, nativo de Australia, que puede alcanzar hasta 15 metros de altura con un tronco robusto. Sus grandes frondas, de color verde brillante y forma arqueada, pueden extenderse hasta 6 metros, creando una densa copa.', 'media sombra', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'HAU11P077', 0, '["helecho", "arborescente", "tropical", "ornamental", "exterior", "gran tamaño", "popular"]', '["maceta negra 11 pulgadas", "maceta negra 14 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137210/plantas/hau11p077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HAZ10P125', 'Hiedra Azul', 'Plectranthus purpuratus', 'ornamental', 'Plectranthus purpuratus, comúnmente conocida como Hiedra Azul o Hiedra Sueca Púrpura, es un subarbusto perenne y suculento de la familia Lamiaceae. Se distingue por su atractivo follaje de hojas carnosas, verde oscuro con el envés teñido de púrpura, y pequeñas flores tubulares blancas o malvas. Es una planta ornamental versátil, ideal para macetas colgantes, como cobertura vegetal o para interiores con luz abundante.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HAZ10P125', 0, '["colgante", "follaje púrpura", "fácil cuidado", "interior", "exterior", "suculenta", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137237/plantas/haz10p125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HBL08L006', 'Hule Blanco', 'Ficus elastica', 'ornamental', 'El Hule Blanco, una variedad de Ficus elastica, es una planta ornamental popular conocida por sus grandes hojas coriáceas y brillantes, a menudo con patrones variegados en tonos crema o rosados. Originaria del sudeste asiático, puede crecer como un árbol imponente en su hábitat natural, pero se adapta bien como planta de interior. Su savia lechosa fue utilizada históricamente para producir caucho.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HBL08L006', 0, '["planta de interior", "ornamental", "fácil cuidado", "hojas variegadas", "purificadora de aire", "tóxica para mascotas"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137258/plantas/hbl08l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HBO10P001', 'Helecho Boston', 'Nephrolepis exaltata ''Boston''', 'ornamental', 'El Helecho de Boston (Nephrolepis exaltata ''Boston'') es una planta ornamental popular, conocida por sus frondas largas, arqueadas y de color verde brillante. Es nativa de regiones tropicales y subtropicales, apreciada por su exuberante follaje y su capacidad para purificar el aire.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HBO10P001', 2, '["helecho", "interior", "purificador de aire", "tropical", "humedad", "fácil cuidado", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137275/plantas/hbo10p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HBS05P077', 'Helecho Blue Star', 'Phlebodium aureum ''Blue Star''', 'interior', 'El Helecho Blue Star es un helecho de porte elegante y exótico, conocido por el color azul verdoso de sus frondas, que son amplias, onduladas y ligeramente coriáceas. Es una planta epífita rizomatosa, nativa de las regiones tropicales y subtropicales de América. Su follaje distintivo lo convierte en una opción popular para la decoración de interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HBS05P077', 0, '["helecho", "planta de interior", "follaje azulado", "purificador de aire", "fácil cuidado", "epífita", "popular"]', '["maceta negra 5 pulgadas", "maceta negra 6 pulgadas", "maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137295/plantas/hbs05p077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HBU06P009', 'Hierba Buena', 'Mentha spicata', 'medicinal', 'La hierbabuena (Mentha spicata) es una hierba perenne aromática, conocida por su intenso y fresco aroma mentolado. Sus hojas son lanceoladas y serradas, y produce pequeñas flores de color lila, rosa o blanco. Puede alcanzar hasta 50 cm de altura y es ampliamente utilizada en gastronomía y medicina tradicional.', 'media sombra', 'alto', 'fácil', 'disponible', 'ambas', 'tóxica', 'HBU06P009', 0, '["aromática", "culinaria", "digestiva", "perenne", "exterior", "interior", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137317/plantas/hbu06p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HCA06P106', 'Helecho Cuerno De Alce', 'Platycerium bifurcatum', 'ornamental', 'El Helecho Cuerno de Alce (Platycerium bifurcatum) es un helecho epífito distintivo, conocido por sus frondas bifurcadas que recuerdan a las astas de un alce. Posee dos tipos de hojas: unas estériles y redondeadas que protegen sus raíces y recogen nutrientes, y otras fértiles y alargadas que producen esporas. Es originario de regiones tropicales y subtropicales de África, Asia, Australia y América del Sur, donde crece adherido a los troncos de los árboles.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'HCA06P106', 0, '["Helecho", "Epífita", "Ornamental", "Planta de interior", "Humedad alta", "Frondas decorativas", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 4 pulgadas", "maceta negra 10 pulgadas", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137360/plantas/hca06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HCA06P200', 'Hoya Carnosa', 'Hoya carnosa', 'ornamental', 'La Hoya carnosa, también conocida como flor de cera o flor de nácar, es una planta trepadora o colgante con tallos largos y hojas gruesas, ovales y cerosas de color verde oscuro. Produce flores estrelladas y aromáticas, de apariencia cerosa, que se agrupan en umbelas y suelen ser blancas o rosadas con un centro más oscuro. Es muy apreciada como planta ornamental por su belleza y bajo mantenimiento.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HCA06P200', 0, '["trepadora", "colgante", "flor de cera", "flor de nácar", "aromática", "hojas cerosas"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137381/plantas/hca06p200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HCA11P006', 'Hule Cavernet', 'Ficus elastica ''Cabernet''', 'interior', 'El Hule Cabernet es una variedad del Ficus elastica, conocido por sus hojas grandes, brillantes y de color verde oscuro con tonalidades rojizas o vino. Es una planta ornamental popular que puede crecer considerablemente, adaptándose bien a interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HCA11P006', 0, '["ornamental", "ficus", "hojas grandes", "follaje oscuro", "planta de interior", "árbol", "popular"]', '["maceta negra 11 pulgadas", "maceta negra 10 pulgadas", "bolsa 2 litros", "maceta negra 12 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137335/plantas/hca11p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HCI06P106', 'Helecho Cilantrillo', 'Adiantum capillus-veneris', 'interior', 'El Helecho Cilantrillo, cuyo nombre científico es Adiantum capillus-veneris, es un pequeño helecho perenne que alcanza entre 10 y 40 cm de altura. Se caracteriza por sus frondas finamente pinnadas y delicadas, sostenidas por tallos delgados de color negro. Es una planta apreciada por su valor ornamental y su adaptabilidad a entornos sombríos y húmedos.', 'media sombra', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'HCI06P106', 0, '["helecho", "planta de interior", "humedad", "sombra", "delicada", "medicinal", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137412/plantas/hci06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HCV06P106', 'Helecho Cuero Varigado', 'Rumohra adiantiformis ''Variegata''', 'ornamental', 'Es un helecho perenne de frondas brillantes de color verde medio con una distintiva raya verde lima en el centro. Presenta un hábito de crecimiento rastrero y extendido, y sus frondas son muy apreciadas en arreglos florales por su durabilidad.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HCV06P106', 0, '["helecho", "variegado", "follaje", "interior", "exterior", "sombra"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137442/plantas/hcv06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HDA06P106', 'Helecho Davalia', 'Davallia canariensis', 'ornamental', 'El helecho Davalia es una planta epífita conocida por sus rizomas peludos y rojizos que sobresalen de la maceta, asemejándose a patas de conejo. Sus frondas son ramificadas y de un color verde pálido, lo que la convierte en una planta ornamental popular, especialmente para colgar. Requiere ambientes húmedos y luz indirecta para prosperar.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HDA06P106', 0, '["helecho", "planta colgante", "rizomas peludos", "pata de conejo", "interior", "humedad", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137468/plantas/hda06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HEM03L105', 'Hemerocalis', 'Hemerocallis spp.', 'ornamental', 'Las Hemerocallis son plantas herbáceas perennes y rizomatosas, conocidas por sus grandes y vistosas flores que, aunque cada una dura solo un día, se suceden continuamente durante un largo periodo. Sus hojas son largas y estrechas, formando matas atractivas. Son muy populares en jardinería por su bajo mantenimiento y su explosión de color.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HEM03L105', 0, '["planta perenne", "flores vistosas", "jardín", "rizomatosa", "fácil cuidado", "lirio de día", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137498/plantas/hem03l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HEN03L077', 'Heliconia Enana', 'Heliconia psittacorum', 'ornamental', 'La Heliconia Enana es una planta tropical perenne conocida por sus llamativas brácteas de colores vivos que rodean pequeñas flores tubulares. Sus hojas son verdes brillantes, similares a las del plátano, y alcanza una altura de 60 cm a 1.2 m, ideal para espacios reducidos. Es apreciada por su belleza ornamental y su resistencia.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HEN03L077', 0, '["tropical", "flores exóticas", "perenne", "bajo mantenimiento", "jardín", "planta ornamental", "popular"]', '["bolsa 3 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137518/plantas/hen03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HGA01L125', 'Hiedra Galvia Española', 'Hedera helix', 'ornamental', 'La hiedra común es una planta trepadora de hojas perennes, con hojas lobuladas en tallos jóvenes y enteras en tallos florales. Produce pequeñas flores verdosas amarillentas y bayas oscuras que maduran en invierno. Es valorada por su follaje y su capacidad para cubrir muros y suelos.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HGA01L125', 0, '["trepadora", "perenne", "follaje", "sombra", "exterior", "interior", "cubresuelos", "purificadora de aire", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137537/plantas/hga01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HIN01L125', 'Hinojo', 'Foeniculum vulgare', 'exterior', 'El hinojo (Foeniculum vulgare) es una planta herbácea perenne, sumamente aromática, nativa de la región mediterránea. Se caracteriza por sus hojas plumosas, flores amarillas en umbelas y un bulbo comestible. Es ampliamente cultivada por su sabor anisado y sus usos culinarios y medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HIN01L125', 0, '["aromática", "culinaria", "medicinal", "perenne", "huerto", "sabor anisado"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137558/plantas/hin01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HKE05P168', 'Hoya Kerry', 'Hoya kerrii', 'ornamental', 'La Hoya kerrii es una planta trepadora epífita originaria del sudeste asiático, conocida por sus hojas gruesas y carnosas en forma de corazón. Produce flores cerosas en forma de estrella, generalmente blancas o cremosas con el centro rosado, que desprenden un aroma suave por la noche. Es una suculenta de crecimiento lento que puede alcanzar varios metros de altura.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HKE05P168', 0, '["suculenta", "trepadora", "planta corazón", "interior", "epífita", "flor de cera", "popular"]', '["maceta negra 5 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137578/plantas/hke05p168.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HMI06P077', 'Helecho Microsorum', 'Microsorum', 'ornamental', 'Los helechos del género Microsorum son plantas tropicales, a menudo epífitas o litófitas, que crecen a partir de rizomas. Presentan frondas de diversas formas, desde alargadas hasta lobuladas, con una textura que puede ser brillante o incluso recordar la piel de un cocodrilo. Son apreciados por su resiliencia y facilidad de cuidado.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HMI06P077', 0, '["helecho", "tropical", "ornamental", "interior", "epífita", "bajo mantenimiento", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137605/plantas/hmi06p077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HMO08L129', 'Guayacan Rosa', 'Tabebuia rosea', 'árbol', 'El Guayacán Rosa es un árbol caducifolio de tamaño mediano a grande, nativo de América Central y del Sur, que puede alcanzar hasta 30 metros de altura. Es muy apreciado por su espectacular floración de flores rosadas a rosado-púrpura en forma de trompeta, que a menudo aparecen cuando el árbol está sin hojas durante la estación seca. Es una especie popular como árbol ornamental y de sombra.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HMO08L129', 0, '["árbol ornamental", "flores rosadas", "árbol caducifolio", "sol pleno", "América Central", "árbol de sombra"]', '["bolsa 8 litros", "bolsa 45 litros", "bolsa 80 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777136986/plantas/hmo08l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HMO10P003', 'Hiedra Morada', 'Cobaea scandens', 'ornamental', 'Cobaea scandens es una planta trepadora originaria de México, conocida por sus tallos que pueden alcanzar hasta 6 metros de altura. Sus vistosas flores, de aproximadamente 5 cm, cambian de color, pasando de tonos blancos o crema a un morado intenso al madurar. Es apreciada por su rápido crecimiento y su capacidad para cubrir muros, pérgolas y otras estructuras.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HMO10P003', 0, '["trepadora", "enredadera", "flores moradas", "ornamental", "rápido crecimiento", "México", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137630/plantas/hmo10p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HNA01L127', 'Hinoki Nana', 'Chamaecyparis obtusa ''Nana Gracilis''', 'ornamental', 'La ''Hinoki Nana'' es un arbusto conífera enana de crecimiento lento, caracterizado por su denso follaje verde oscuro dispuesto en forma de concha o abanico. Desarrolla una forma compacta, que puede ser redondeada o cónica, lo que la hace ideal para diversos diseños de paisajismo.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HNA01L127', 0, '["conífera", "enana", "arbusto", "exterior", "jardín de rocas", "crecimiento lento", "popular"]', '["bolsa 1 litros", "bolsa 2 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137653/plantas/hna01l127.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HNA06P106', 'Helecho Nido De Ave', 'Asplenium nidus', 'ornamental', 'El Helecho Nido de Ave (Asplenium nidus) es un helecho epífito tropical conocido por sus grandes frondas simples, de color verde brillante y forma de correa, que crecen en una roseta que se asemeja a un nido. Sus hojas tienen un nervio central oscuro y márgenes ondulados, aportando una atmósfera de bosque tropical. Es una planta ornamental popular por su fácil cuidado y su capacidad para prosperar en interiores con luz indirecta.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HNA06P106', 0, '["helecho", "epífita", "tropical", "hojas onduladas", "planta de interior", "planta de exterior", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137671/plantas/hna06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HNO06P125', 'Huele De Noche', 'Cestrum nocturnum', 'ornamental', 'Arbusto perenne conocido por sus flores tubulares de color blanco cremoso a verde pálido que se abren por la noche, liberando una fragancia dulce e intensa. Puede crecer como un arbusto denso o extendido, alcanzando entre 1 y 4 metros de altura.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'HNO06P125', 0, '["arbusto", "fragante", "flores nocturnas", "exterior", "tropical", "venenosa", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137690/plantas/hno06p125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HOR08P003', 'Hortencia', 'Hydrangea macrophylla', 'ornamental', 'Las hortensias son arbustos caducifolios conocidos por sus grandes y vistosas inflorescencias en tonos de rosa, azul, blanco o morado, cuyo color puede variar según el pH del suelo. Son originarias de Asia y América, y sus hojas son grandes, simples y generalmente serradas. Florecen desde principios de primavera hasta finales de otoño, siendo muy populares en jardines y macetas.', 'media sombra', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'HOR08P003', 0, '["arbusto", "flores grandes", "cambio de color", "jardín", "sombra", "humedad", "popular"]', '["maceta negra 8 pulgadas", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137717/plantas/hor08p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HOS03P106', 'Helecho Osaka', 'Asplenium antiquum ''Osaka''', 'interior', 'El Helecho Osaka es una variedad de helecho nido de pájaro que se distingue por sus hojas largas, onduladas y lustrosas, de un vibrante color verde. Estas hojas emergen en forma de roseta, creando un follaje denso y muy decorativo. Es una planta de interior popular por su apariencia única y su fácil mantenimiento.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HOS03P106', 0, '["helecho", "interior", "ornamental", "hojas onduladas", "fácil cuidado", "tropical"]', '["maceta negra 3 pulgadas", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137735/plantas/hos03p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HPA10L153', 'Hamelia Patens', 'Hamelia patens Jacq.', 'ornamental', 'Hamelia patens es un arbusto grande perenne o árbol pequeño, nativo de las regiones subtropicales y tropicales de América. Se caracteriza por sus flores tubulares de color rojo anaranjado que atraen colibríes y mariposas. Sus hojas ovaladas de color verde grisáceo pueden adquirir tonos rojizos en otoño.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HPA10L153', 0, '["arbusto", "exterior", "medicinal", "atrae colibríes", "atrae mariposas", "tolerante a la sequía", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137752/plantas/hpa10l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HPT08L116', 'Heliconia Pico De Tucan', 'Heliconia rostrata', 'ornamental', 'La Heliconia rostrata, también conocida como "Pico de Tucán", es una planta herbácea perenne tropical, reconocida por sus grandes hojas verdes similares a las del plátano. Produce vistosas inflorescencias colgantes de brácteas rojas y amarillas que recuerdan la forma del pico de un tucán o garras de langosta. Es una planta muy ornamental que atrae a los colibríes.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'HPT08L116', 0, '["tropical", "exótica", "ornamental", "flor colgante", "jardín", "colibríes", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137784/plantas/hpt08l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HRU08P006', 'Hule Rubi', 'Ficus elastica ''Ruby''', 'ornamental', 'El Ficus elastica ''Ruby'' es un cultivar llamativo del árbol de caucho, apreciado por sus grandes y brillantes hojas con variegaciones en tonos burdeos, rosa y verde. Es originario de las regiones tropicales de la India y Malasia. Esta planta es popular como planta de interior debido a su atractivo follaje y sus cualidades purificadoras de aire.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'HRU08P006', 0, '["Planta de interior", "Ornamental", "Follaje variegado", "Purificadora de aire", "Ficus", "Árbol de caucho"]', '["maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137803/plantas/hru08p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HRU10P077', 'Helecho Rufles', 'Nephrolepis exaltata ''Fluffy Ruffles''', 'ornamental', 'Es una variedad enana del helecho de Boston (Nephrolepis exaltata) con frondas delicadas, intrincadamente rizadas y de un hermoso color verde fresco. Su crecimiento compacto y voluminoso le confiere una apariencia de encaje, ideal para interiores.', 'luz indirecta', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HRU10P077', 0, '["helecho", "planta de interior", "follaje", "ornamental", "humedad", "compacta"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137822/plantas/hru10p077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HSL06P106', 'Helecho Silver Lady', 'Blechnum gibbum ''Silver Lady''', 'ornamental', 'Es un helecho arbóreo enano elegante, nativo de regiones tropicales y subtropicales. Presenta una corona simétrica de frondas brillantes de color verde claro, con forma de pluma, que crecen en roseta sobre un tronco corto. Puede alcanzar entre 91 cm y 1.2 metros de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HSL06P106', 0, '["helecho", "tropical", "planta de interior", "planta ornamental", "frondas verdes", "bajo mantenimiento", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137853/plantas/hsl06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HUI18L129', 'Huizache', 'Vachellia farnesiana (L.) Wight & Arn.', 'árbol', 'El huizache, cuyo nombre científico es Vachellia farnesiana, es un arbusto o árbol pequeño, perennifolio o subcaducifolio, que puede alcanzar de 3 a 10 metros de altura. Se caracteriza por sus hojas bipinnadas, espinas y flores esféricas de color amarillo brillante y muy fragantes. Produce frutos en forma de vainas leñosas y es valorado por su uso ornamental, medicinal y en la industria de la perfumería.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HUI18L129', 0, '["árbol", "ornamental", "espinoso", "aromático", "resistente a la sequía", "medicinal", "forrajero"]', '["bolsa 18 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137886/plantas/hui18l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HUV18L010', 'Hule Cavernet Bonsai', 'Ficus elastica ''Cabernet''', 'ornamental', 'El Ficus elastica, conocido comúnmente como árbol del caucho o gomero, es una planta ornamental popular. La variedad ''Cabernet'' se distingue por sus hojas brillantes y variegadas en tonos verdes, crema y rosados. Cultivada como bonsái, esta planta se mantiene en un tamaño miniatura, exhibiendo la forma de un árbol.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'HUV18L010', 0, '["Ficus", "árbol del caucho", "gomero", "bonsái", "planta de interior", "variegada"]', '["bolsa 18 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137911/plantas/huv18l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('HYP06P109', 'Hypoeste', 'Hypoestes phyllostachya', 'ornamental', 'Es un arbusto perenne conocido por sus hojas ovaladas y puntiagudas, intensamente salpicadas de manchas rosas, blancas o rojas, lo que le da un aspecto de "planta de lunares". Originaria de Madagascar, alcanza una altura de 30 a 60 cm y es muy apreciada por su follaje decorativo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'HYP06P109', 0, '["planta de lunares", "hoja de sangre", "follaje colorido", "planta tropical", "planta de interior", "fácil cuidado", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137929/plantas/hyp06p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ICA03L006', 'Ixora Carla', 'Ixora coccinea ''Carla''', 'ornamental', 'Es un arbusto perenne de forma redondeada con hojas brillantes de color verde oscuro. Produce vistosos racimos de pequeñas flores de cuatro pétalos, generalmente rojas, que florecen durante gran parte del año. Es una planta ornamental muy popular en climas tropicales y subtropicales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ICA03L006', 0, '["arbusto", "floración abundante", "tropical", "flores rojas", "jardín", "maceta", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137949/plantas/ica03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('IEN03L006', 'Ixora Enana Surtida-.30', 'Ixora coccinea', 'ornamental', 'La Ixora enana es un arbusto perenne compacto, conocido por sus densos racimos de pequeñas flores en forma de estrella que pueden ser rojas, amarillas, anaranjadas o rosadas. Sus hojas son brillantes, coriáceas y oblongas, y florece la mayor parte del año. Es ideal para jardines, macetas y setos bajos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'IEN03L006', 0, '["arbusto", "flores", "tropical", "jardín", "maceta", "perenne", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777137971/plantas/ien03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('IRE08L006', 'Ixora Reyna', 'Ixora coccinea', 'ornamental', 'La Ixora Reyna es un arbusto de hoja perenne originario de las zonas tropicales de Asia. Produce magníficas inflorescencias terminales con flores en tonos rojos, rosados, amarillos o naranjas, floreciendo casi todo el año. Es muy apreciada en jardinería por su belleza y resistencia.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'IRE08L006', 0, '["arbusto", "flores", "tropical", "jardín", "seto", "perenne", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138006/plantas/ire08l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('IRI06P125', 'Iris', 'Iris L.', 'ornamental', 'El Iris es un género de plantas rizomatosas o bulbosas de la familia Iridaceae, conocido por sus vistosas flores que presentan una amplia gama de colores. Sus hojas son largas, estrechas y en forma de espada, y la planta puede alcanzar alturas variables.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'IRI06P125', 0, '["flor", "perenne", "rizomatosa", "bulbosa", "jardín", "colores variados", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138025/plantas/iri06p125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAB20L105', 'Jaboticabo', 'Myrciaria cauliflora', 'árbol', 'El jaboticabo es un árbol frutal tropical de crecimiento lento, conocido por producir sus frutos directamente en el tronco y las ramas. Sus frutos son esféricos, de color púrpura oscuro a negro cuando maduran, con una pulpa blanca gelatinosa y dulce, similar a la uva. La corteza del árbol se desprende, dándole una apariencia atractiva y moteada.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'JAB20L105', 0, '["frutal", "árbol tropical", "caulifloria", "corteza exfoliante", "fruto comestible", "bonsái"]', '["bolsa 20 litros", "bolsa 18 litros", "bolsa 50 litros", "bolsa 10 litros", "bolsa 40 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138049/plantas/jab20l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAC04L077', 'Jacaranda', 'Jacaranda mimosifolia', 'árbol', 'El Jacarandá (Jacaranda mimosifolia) es un árbol de tamaño mediano a grande, conocido por su espectacular floración de flores tubulares de color azul-violeta que aparecen en primavera antes o junto con sus hojas. Posee un follaje delicado y pinnado, similar al de los helechos, y produce frutos en forma de cápsulas leñosas y aplanadas. Es ampliamente valorado como árbol ornamental en climas cálidos y templados.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'JAC04L077', 0, '["árbol ornamental", "flores violetas", "caducifolio", "clima cálido", "floración primaveral", "árbol urbano", "popular"]', '["bolsa 4 litros", "bolsa 2 litros", "bolsa 65 litros", "bolsa 45 litros", "bolsa 60 litros", "bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138070/plantas/jac04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAC60L170', 'Jacaranda Bca', 'Jacaranda mimosifolia ''Alba''', 'árbol', 'Es un árbol caducifolio subtropical conocido por sus espectaculares flores blancas en forma de campana que aparecen en primavera y principios de verano. Posee un follaje delicado similar a helechos y forma una copa elegante y extendida. Originario de Sudamérica, es ampliamente cultivado como árbol ornamental en climas cálidos.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'JAC60L170', 0, '["árbol", "ornamental", "flores blancas", "caducifolio", "clima cálido", "Sudamérica"]', '["bolsa 60 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138090/plantas/jac60l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAD15L130', 'Jade', 'Crassula ovata', 'suculenta', 'La Crassula ovata, comúnmente conocida como planta o árbol de Jade, es una suculenta de crecimiento lento con hojas carnosas, ovaladas y de un verde vibrante que pueden desarrollar bordes rojizos con luz intensa. Con el tiempo, su tallo se vuelve leñoso, dándole la apariencia de un pequeño árbol que puede alcanzar hasta 3 metros de altura. Es una planta muy popular por su fácil cuidado y su valor ornamental.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JAD15L130', 0, '["suculenta", "ornamental", "interior", "exterior", "fácil cuidado", "árbol de dinero"]', '["bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138112/plantas/jad15l130.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAR10L009', 'Jazmin De Arabia', 'Jasminum sambac', 'ornamental', 'El Jazmín de Arabia (Jasminum sambac) es un arbusto o enredadera perenne, valorado por sus pequeñas flores blancas de intenso y dulce aroma que florecen durante gran parte del año. Es una planta ornamental muy popular, utilizada también para aromatizar tés y perfumes. Puede alcanzar entre 0.5 y 3 metros de altura.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'JAR10L009', 0, '["fragante", "arbusto", "trepadora", "flores blancas", "tropical", "ornamental", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138130/plantas/jar10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAR30L125', 'Jarilla', 'Larrea divaricata', 'medicinal', 'La Jarilla es un arbusto silvestre, ramoso y resinoso, que puede alcanzar hasta 3 metros de altura. Sus hojas son pequeñas, elípticas y de color verde oscuro, mientras que sus flores son amarillas y solitarias. Es nativa de regiones áridas y montañosas de América del Sur, especialmente Argentina y Chile.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JAR30L125', 0, '["arbusto", "medicinal", "nativa", "árida", "resinosa", "flores amarillas"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138159/plantas/jar30l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JAZ20L006', 'Junipero Azul', 'Juniperus squamata ''Blue Star''', 'ornamental', 'Es un arbusto enano de hoja perenne y crecimiento lento, con un hábito de crecimiento redondeado y denso. Presenta un follaje de color azul plateado brillante en forma de aguja que puede adquirir tonos púrpura en invierno. Se utiliza comúnmente como planta ornamental en jardines de rocas o como cobertura del suelo.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JAZ20L006', 0, '["arbusto", "perenne", "follaje azul", "bajo mantenimiento", "jardín de rocas", "cubresuelos", "popular"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138177/plantas/jaz20l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JES04L133', 'Junipero Sparta', 'Juniperus chinensis ''Spartan''', 'ornamental', 'El Junípero Sparta (Juniperus chinensis ''Spartan'') es una conífera de hoja perenne de crecimiento rápido, conocida por su forma columnar estrecha y densa. Su follaje verde oscuro y su silueta formal lo hacen ideal para pantallas de privacidad, setos y como acento vertical en jardines. Es una planta de bajo mantenimiento que tolera el calor, el frío y la sequía una vez establecida.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JES04L133', 0, '["árbol", "conífera", "exterior", "pantalla de privacidad", "bajo mantenimiento", "resistente a la sequía"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138199/plantas/jes04l133.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JES08L010', 'Junipero Estrella', 'Juniperus squamata ''Blue Star''', 'ornamental', 'El ''Junipero Estrella'' es una conífera enana de crecimiento lento, conocida por su follaje denso de color azul plateado. Sus agujas son pequeñas y puntiagudas, formando un patrón de crecimiento redondeado o extendido. Es un arbusto ornamental que añade un contraste de color atractivo en jardines.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JES08L010', 0, '["conífera", "arbusto", "exterior", "follaje azul", "cubre suelos", "resistente a la sequía", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138217/plantas/jes08l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JGM10L127', 'Junipero Green Mountain', 'Juniperus procumbens ''Nana''', 'ornamental', 'El Junípero Green Mountain es una conífera de hoja perenne, valorada por su follaje verde vibrante y su corteza rugosa. Es una variedad popular para bonsái, adaptándose a diversos estilos de diseño y manteniendo su verdor todo el año.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'JGM10L127', 0, '["bonsái", "conífera", "perenne", "exterior", "follaje verde", "arbusto", "popular"]', '["bolsa 10 litros", "maceta negra 12 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138241/plantas/jgm10l127.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JPN03L010', 'Junipero Procumbens Nana', 'Juniperus procumbens ''Nana''', 'exterior', 'El Juniperus procumbens ''Nana'' es un arbusto perenne, compacto y muy ramificado, de crecimiento lento. Presenta un follaje de color verde azulado a gris-verde que puede adquirir tonos púrpuras en invierno. Es una conífera rastrera que se utiliza a menudo como cobertura del suelo o en bonsáis.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'JPN03L010', 0, '["arbusto perenne", "rastrera", "cobertura del suelo", "bonsái", "follaje azul-verde", "resistente a la sequía", "popular"]', '["bolsa 3 litros", "bolsa 4 litros", "maceta negra 10 pulgadas", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138273/plantas/jpn03l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JSJ03L010', 'Junipero San Jose', 'Juniperus chinensis ''San Jose''', 'ornamental', 'El ''Junipero San Jose'' (Juniperus chinensis ''San Jose'') es una conífera perenne de bajo crecimiento, valorada por su follaje verde salvia que se mantiene atractivo todo el año. Forma una cubierta densa y extendida, alcanzando entre 30 y 60 cm de altura y hasta 1.8 a 2.4 metros de ancho. Es una planta ornamental muy versátil, ideal para paisajismo, cubresuelos y como bonsái.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JSJ03L010', 0, '["arbusto perenne", "cubresuelos", "conífera", "resistente a la sequía", "bonsái", "exterior", "popular"]', '["bolsa 3 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138297/plantas/jsj03l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('JTA20L006', 'Junipero Tapizante', 'Juniperus horizontalis', 'ornamental', 'El Junípero Tapizante es un arbusto conífera de porte rastrero y crecimiento lento, que forma una densa alfombra de follaje verde o azulado. Sus ramas se extienden horizontalmente, ideal para cubrir suelos, taludes y rocallas. Es una planta perenne muy resistente y de bajo mantenimiento.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'JTA20L006', 0, '["cubresuelos", "conífera", "resistente a sequía", "bajo mantenimiento", "exterior", "perenne", "popular"]', '["bolsa 20 litros", "bolsa 4 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138317/plantas/jta20l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LAF06P170', 'Lechero Africano', 'Euphorbia tirucalli', 'suculenta', 'La Euphorbia tirucalli, conocida como Lechero Africano o Árbol de dedos, es una planta suculenta arbustiva con tallos cilíndricos y delgados de color verde que pueden adquirir tonos rojizos con la exposición solar. Puede crecer como un arbusto o árbol pequeño, alcanzando varios metros de altura en su hábitat natural. Es apreciada por su apariencia moderna y escultural, ideal para decoración.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'LAF06P170', 0, '["árbol de dedos", "arbusto", "planta de interior", "planta de exterior", "resistente a la sequía", "látex tóxico", "ornamental"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138340/plantas/laf06p170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LAM10L136', 'Laurel Amarillo', 'Thevetia peruviana', 'ornamental', 'Es un arbusto o árbol pequeño perenne, de hojas brillantes y coriáceas. Produce vistosas flores tubulares de color amarillo, naranja o blanco, y frutos atractivos similares a castañas. Todas sus partes son altamente tóxicas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LAM10L136', 0, '["arbusto", "árbol pequeño", "flores amarillas", "tóxica", "exterior", "resistente a sequía"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138364/plantas/lam10l136.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LAN02L077', 'Lantana', 'Lantana camara', 'ornamental', 'La Lantana camara es un arbusto perennifolio de rápido crecimiento, nativo de las regiones tropicales de América. Puede alcanzar entre 1.5 y 3 metros de altura, destacando por sus hojas ásperas y sus pequeñas flores agrupadas en cabezuelas que cambian de color, abarcando tonos amarillos, naranjas, rojos, rosas y lilas. Es muy apreciada como planta ornamental por su abundante y prolongada floración.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'LAN02L077', 0, '["arbusto", "perenne", "flores coloridas", "resistente sequía", "exterior", "atrae mariposas", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138382/plantas/lan02l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LAV01L125', 'Lavanda', 'Lavandula angustifolia', 'ornamental', 'La lavanda es una planta sufruticosa perenne conocida por sus tallos leñosos, hojas estrechas de color verde grisáceo y pequeñas flores tubulares de tonalidad violeta o azul, agrupadas en espigas. Es muy apreciada por su característico y agradable aroma.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LAV01L125', 0, '["aromática", "arbusto", "flores moradas", "mediterránea", "repelente de insectos", "medicinal", "popular"]', '["bolsa 1 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138400/plantas/lav01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LBE04L105', 'Luz De Bengala', 'Russelia equisetiformis', 'ornamental', 'La Luz de Bengala es un arbusto perenne de rápido crecimiento, caracterizado por sus tallos finos y ramificados que pueden ser colgantes. Produce abundantes flores tubulares de color rojo intenso, floreciendo durante gran parte del año. Puede alcanzar hasta 1.5 metros de altura con tallos colgantes de hasta 3 metros.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'LBE04L105', 0, '["arbusto", "colgante", "flores rojas", "exterior", "fácil cuidado", "atrae colibríes", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138423/plantas/lbe04l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LCH12L120', 'Lima Chichi', 'Citrus limetta', 'árbol', 'El Citrus limetta, conocido como Lima Chichi o lima dulce, es un árbol pequeño con ramas irregulares y espinas puntiagudas. Produce frutos verde-amarillentos con una pulpa dulce y abundante, y una cáscara delgada fácil de pelar. Es originario de Asia y se cultiva en climas cálidos a templados.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'LCH12L120', 0, '["cítrico", "frutal", "dulce", "exterior", "árbol", "comestible", "popular"]', '["bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138445/plantas/lch12l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LCO10L120', 'Limon Colimeño', 'Citrus x aurantifolia', 'árbol', 'Es un arbusto o árbol cítrico que puede alcanzar entre 4 y 5 metros de altura, conocido por sus frutos pequeños, muy jugosos y de acidez pronunciada. Es una variedad muy apreciada en la gastronomía mexicana y se cultiva ampliamente en el país.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'LCO10L120', 0, '["frutal", "cítrico", "limón", "mexicano", "exterior", "árbol", "popular"]', '["bolsa 10 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138465/plantas/lco10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LEU03L009', 'Leucophilum', 'Leucophyllum frutescens', 'exterior', 'El Leucophyllum frutescens, también conocido como cenizo o salvia de Texas, es un arbusto perenne originario del suroeste de Estados Unidos y México. Se caracteriza por su follaje plateado-grisáceo y sus flores tubulares de color púrpura, violeta o rosa que aparecen principalmente de verano a otoño, a menudo después de las lluvias. Es una planta muy apreciada en jardinería por su resistencia a la sequía y su bajo mantenimiento.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'LEU03L009', 0, '["arbusto", "cenizo", "salvia de Texas", "resistente a la sequía", "follaje plateado", "floración estival", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138485/plantas/leu03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LEU10L120', 'Limon Eureka', 'Citrus x limon ''Eureka''', 'árbol', 'El limón Eureka es una variedad de limonero ampliamente cultivada, conocida por su producción abundante de frutos jugosos y aromáticos. Produce limones de tamaño mediano, forma ovalada, piel gruesa y rugosa de color amarillo brillante, con pulpa ácida y pocas semillas. Es un árbol de crecimiento vigoroso con flores blancas, que fructifica casi todo el año en climas cálidos, siendo ideal para uso culinario y ornamental.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LEU10L120', 0, '["árbol frutal", "cítrico", "limón", "frutos jugosos", "uso culinario", "ornamental", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138503/plantas/leu10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LIC45L152', 'Lichi', 'Litchi chinensis', 'árbol', 'El lichi (Litchi chinensis) es un árbol frutal tropical de hoja perenne, originario del sur de China. Produce pequeños frutos carnosos de piel roja y áspera, con una pulpa blanca, dulce y aromática. Puede alcanzar alturas considerables, aunque en cultivo se mantiene más pequeño.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'LIC45L152', 0, '["árbol frutal", "tropical", "fruta exótica", "exterior", "China", "dulce"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138520/plantas/lic45l152.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LIM10L013', 'Lima', 'Citrus x aurantifolia', 'árbol', 'La lima es un árbol cítrico perenne que puede alcanzar entre 3 y 5 metros de altura. Produce frutos pequeños, redondos u ovalados, de color verde a amarillo, conocidos por su sabor ácido y aroma refrescante. Sus hojas son de color verde oscuro brillante y sus flores son blancas o blanco-amarillentas y fragantes.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'LIM10L013', 0, '["cítrico", "frutal", "perenne", "tropical", "aromática", "exterior"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138540/plantas/lim10l013.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LIQ03L006', 'Liquidambar', 'Liquidambar styraciflua', 'árbol', 'El Liquidambar (Liquidambar styraciflua) es un árbol caducifolio grande, conocido por sus hojas en forma de estrella que adquieren vibrantes tonalidades de rojo, naranja, amarillo y púrpura en otoño. Produce frutos esféricos y espinosos, y su tronco exuda una resina aromática. Es muy apreciado como árbol ornamental por su espectacular follaje otoñal.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'LIQ03L006', 0, '["árbol caducifolio", "follaje otoñal", "árbol ornamental", "resinoso", "hojas estrelladas", "frutos espinosos"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138558/plantas/liq03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LNI01L125', 'Lagrima De Niño', 'Plectranthus verticillatus', 'ornamental', 'La Lágrima de Niño, científicamente conocida como Plectranthus verticillatus, es una planta ornamental de porte rastrero o colgante. Se caracteriza por sus hojas redondas, brillantes y de color verde intenso, a menudo con tonos púrpuras en el envés. Produce pequeñas flores blancas o malvas, y es apreciada por su facilidad de cuidado y su follaje exuberante.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'LNI01L125', 0, '["rastrera", "colgante", "follaje verde", "fácil cuidado", "no tóxica", "interior", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138580/plantas/lni01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LOR08P006', 'Loropetalo', 'Loropetalum chinense', 'ornamental', 'El Loropetalum chinense, también conocido como flor de flecos china, es un arbusto o pequeño árbol de hoja perenne o semiperenne. Se caracteriza por sus vistosas flores en forma de flecos, que pueden ser blancas, rosas o rojas, y su follaje que varía entre verde, púrpura y burdeos. Es una planta versátil que añade interés durante todo el año al paisaje.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'LOR08P006', 0, '["arbusto", "floración vistosa", "follaje colorido", "setos", "macetas", "fácil cuidado", "popular"]', '["maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138600/plantas/lor08p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LOR15L116', 'Lluvia De Oro', 'Cassia fistula', 'árbol', 'La Lluvia de Oro, cuyo nombre científico es Cassia fistula, es un árbol de tamaño mediano que puede alcanzar entre 10 y 20 metros de altura. Es ampliamente valorado por sus espectaculares racimos colgantes de flores de color amarillo brillante, que cubren el árbol en primavera y verano. Originario del sur de Asia, se cultiva en regiones tropicales y subtropicales de todo el mundo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LOR15L116', 0, '["árbol ornamental", "flores amarillas", "árbol tropical", "medicinal", "caducifolio", "vaina"]', '["bolsa 15 litros", "bolsa 18 litros", "bolsa 40 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138622/plantas/lor15l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LOV03P126', 'Lovery Rose', '×Graptoveria ''Lovely Rose''', 'suculenta', 'Es una suculenta atractiva y popular, conocida por sus rosetas compactas y sus hojas carnosas que varían de rosa claro a violeta intenso en los márgenes y puntas. Su forma única se asemeja a un capullo de rosa.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'LOV03P126', 0, '["suculenta", "roseta", "fácil cuidado", "hojas carnosas", "ornamental", "exterior"]', '["maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138642/plantas/lov03p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LPE06L001', 'Limon Persa', 'Citrus x latifolia', 'árbol', 'El Limón Persa (Citrus x latifolia) es un árbol frutal vigoroso, conocido por sus frutos de alta calidad, piel fina y pulpa jugosa y aromática. Sus limones son típicamente sin semillas, de forma ovalada o de globo, y de color verde que se torna amarillo al madurar. Se cultiva principalmente en exteriores y puede alcanzar una altura de 6 a 7 metros.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'LPE06L001', 0, '["cítrico", "frutal", "sin semillas", "exterior", "árbol", "medicinal", "popular"]', '["bolsa 6 litros", "bolsa 3 litros", "bolsa 10 litros", "bolsa 8 litros", "bolsa 20 litros", "bolsa 30 litros", "bolsa 60 litros", "bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138663/plantas/lpe06l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LPE08L009', 'Lirio Persa Bco', 'Fritillaria persica', 'ornamental', 'Esta planta bulbosa perenne produce elegantes espigas de flores acampanadas de color blanco cremoso que maduran a marfil, complementadas por un follaje azul-verde ondulado. Alcanza una altura de 60 a 90 cm y es conocida por su resistencia a ciervos y roedores.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'LPE08L009', 0, '["ornamental", "bulbosa", "perenne", "exterior", "flores blancas", "resistente a ciervos", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138683/plantas/lpe08l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LRO10P134', 'Lirio Rojo', 'Lilium bulbiferum', 'ornamental', 'Es una planta herbácea perenne bulbosa con tallos erectos y hojas lanceoladas. Produce flores grandes, en forma de cuenco y mirando hacia arriba, de color naranja brillante a rojo anaranjado, a menudo con manchas rojizas-marrones. Florece en verano y es apreciada por su vibrante color.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LRO10P134', 0, '["Lirio", "Azucena", "Bulbosa", "Flores naranjas", "Exterior", "Perenne"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138715/plantas/lro10p134.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('LVE12L136', 'Laurel Verde', 'Laurus nobilis', 'árbol', 'El laurel (Laurus nobilis) es un árbol o arbusto perennifolio originario de la región mediterránea, conocido por sus hojas aromáticas de color verde oscuro y brillante. Puede alcanzar entre 2 y 10 metros de altura, con un tronco recto y una copa densa. Sus pequeñas flores amarillentas aparecen en primavera, seguidas de frutos negros similares a aceitunas en otoño.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'LVE12L136', 0, '["aromática", "culinaria", "árbol perenne", "exterior", "mediterránea", "fácil cuidado"]', '["bolsa 12 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138742/plantas/lve12l136.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MAG03L010', 'Magnolia', 'Magnolia grandiflora', 'árbol', 'La Magnolia es un género de árboles y arbustos, siendo la Magnolia grandiflora una especie arbórea perenne muy conocida. Se caracteriza por sus grandes y vistosas flores blancas, muy fragantes, y sus hojas coriáceas de color verde brillante. Puede alcanzar alturas considerables y es muy apreciada en jardinería.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'MAG03L010', 0, '["árbol ornamental", "flores grandes", "hoja perenne", "fragante", "jardín", "clima templado", "popular"]', '["bolsa 3 litros", "bolsa 20 litros", "bolsa 60 litros", "bolsa 80 litros", "bolsa 10 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138762/plantas/mag03l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MAJ06L153', 'Majagua', 'Hibiscus elatus Sw.', 'árbol', 'La Majagua (Hibiscus elatus) es un árbol tropical que puede alcanzar hasta 25 metros de altura, conocido por sus hojas anchas y sus grandes flores que cambian de color, de amarillo brillante a anaranjado y finalmente rojo carmesí al madurar. Es nativo de Cuba y Jamaica, valorado por su belleza ornamental, su madera resistente y sus propiedades medicinales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MAJ06L153', 0, '["árbol", "ornamental", "tropical", "flores cambiantes", "medicinal", "madera", "popular"]', '["bolsa 6 litros", "bolsa 45 litros", "bolsa 4 litros", "bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138784/plantas/maj06l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MAM08L115', 'Mamey', 'Pouteria sapota', 'árbol', 'El mamey, también conocido como zapote mamey o mamey colorado, es un árbol frutal perenne originario de Mesoamérica que puede alcanzar grandes alturas. Produce frutos ovalados o elípticos con una cáscara rugosa de color marrón y una pulpa dulce, cremosa y aromática de color naranja a rojizo intenso. Es apreciado por su delicioso sabor y sus propiedades nutricionales y medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'MAM08L115', 0, '["frutal", "tropical", "árbol grande", "dulce", "antioxidante", "medicinal"]', '["bolsa 8 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138804/plantas/mam08l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MAN04L001', 'Mandevilia Amarilla', 'Mandevilla sanderi', 'ornamental', 'La Mandevilla Amarilla, o Mandevilla sanderi, es una planta trepadora tropical conocida por sus vistosas flores amarillas en forma de trompeta. Sus hojas son de color verde oscuro brillante y de textura coriácea. Es una planta ornamental popular para jardines, patios y como planta de interior en climas fríos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'MAN04L001', 0, '["trepadora", "flor amarilla", "tropical", "exterior", "interior", "polinizadores", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138825/plantas/man04l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MAN10L120', 'Mango', 'Mangifera indica', 'árbol', 'El mango es una especie arbórea frutal de la familia Anacardiaceae, originaria del noroeste de la India y el norte de Birmania. Puede alcanzar hasta 30 metros de altura, con un tronco recto y corteza gris-café. Produce drupas carnosas de piel gruesa y pulpa jugosa, dulce y muy sabrosa.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'MAN10L120', 0, '["frutal", "tropical", "árbol grande", "clima cálido", "fruta dulce", "Mangifera indica", "popular"]', '["bolsa 10 litros", "bolsa 45 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138845/plantas/man10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MCA10L120', 'Mandarina Calamondi', 'Citrus × microcarpa', 'árbol', 'La Mandarina Calamondí es un híbrido cítrico, un arbusto o árbol pequeño perennifolio que produce flores blancas fragantes y frutos pequeños, redondos y de color naranja. Sus frutos son muy ácidos, similares al limón, y se utiliza tanto por su valor ornamental como culinario.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'MCA10L120', 0, '["cítrico", "frutal", "ornamental", "árbol pequeño", "frutos ácidos", "planta de interior", "planta de exterior", "popular"]', '["bolsa 10 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138870/plantas/mca10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MCJ03L077', 'Manzana California', 'Malus domestica', 'árbol', 'El manzano es un árbol caducifolio ampliamente cultivado por sus frutos comestibles, las manzanas. Produce flores blancas a rosadas en primavera, seguidas de frutos redondos que varían en color, tamaño y sabor.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MCJ03L077', 0, '["frutal", "árbol caducifolio", "huerto", "floración primaveral", "fruto comestible", "polinización cruzada", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777138890/plantas/mcj03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MEN04P009', 'Menta', 'Mentha x piperita', 'medicinal', 'La menta es una planta herbácea vivaz de tallos erectos y hojas opuestas, lanceoladas y aserradas, de color verde oscuro. Es conocida por su aroma fresco y penetrante, debido a la presencia de mentol, y sus pequeñas flores púrpuras o blancas que aparecen en verano. Se utiliza ampliamente en gastronomía, medicina tradicional y aromaterapia.', 'media sombra', 'alto', 'fácil', 'disponible', 'ambas', 'tóxica', 'MEN04P009', 0, '["aromática", "culinaria", "perenne", "fácil cuidado", "exterior", "híbrida", "popular"]', '["maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141691/plantas/men04p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MEZ10L006', 'Mezquite', 'Prosopis spp.', 'árbol', 'El mezquite es un árbol o arbusto caducifolio espinoso, que alcanza entre 4 y 12 metros de altura, con una copa extendida y ramas bajas. Posee hojas bipinnadas y produce flores amarillentas, seguidas de vainas dulces.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'MEZ10L006', 0, '["árbol del desierto", "resistente a la sequía", "ornamental", "medicinal", "fijador de nitrógeno", "sombra"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141733/plantas/mez10l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MGO04L077', 'Manzana Golden', 'Malus domestica ''Golden Delicious''', 'árbol', 'La Manzana Golden, o ''Golden Delicious'', es una variedad de manzano (Malus domestica) que produce frutos de tamaño mediano a grande, con piel fina de color amarillo dorado. Su pulpa es blanca, firme, crujiente, jugosa y de sabor dulce y ligeramente ácido. Es un árbol vigoroso y muy productivo, ideal para huertos familiares y comerciales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MGO04L077', 0, '["Manzano", "Frutal", "Manzana", "Cultivar", "Exterior", "Dulce", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141756/plantas/mgo04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MIR03L119', 'Mirto', 'Myrtus communis', 'ornamental', 'El mirto es un arbusto perenne de follaje compacto y muy aromático, con hojas ovaladas de color verde brillante. Produce flores blancas fragantes en primavera y verano, seguidas de bayas comestibles de color azul oscuro al madurar.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'MIR03L119', 0, '["arbusto", "perenne", "aromática", "flores blancas", "bayas comestibles", "mediterránea", "setos", "popular"]', '["bolsa 3 litros", "bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141776/plantas/mir03l119.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MJA60L170', 'Maple Japones', 'Acer palmatum', 'árbol', 'El Arce Japonés es un arbusto o árbol pequeño caducifolio, nativo de Asia, que alcanza alturas de 6 a 10 metros. Se distingue por sus hojas palmatilobadas que ofrecen una espectacular gama de colores en otoño, desde rojos intensos hasta naranjas y amarillos. Es muy apreciado por su forma elegante y su follaje vibrante, siendo una elección popular para jardines y como bonsái.', 'media sombra', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'MJA60L170', 0, '["árbol caducifolio", "ornamental", "jardín", "bonsái", "follaje colorido", "asiático"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141794/plantas/mja60l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MON01L006', 'Moneda', 'Plectranthus verticillatus', 'ornamental', 'La Plectranthus verticillatus, conocida como "Planta Moneda" o "Planta del Dinero", es una planta de interior popular por sus hojas redondas y verdes, y sus tallos colgantes. Es originaria del sur de África y se asocia comúnmente con la buena suerte y la prosperidad.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'MON01L006', 0, '["planta de interior", "fácil cuidado", "colgante", "hojas redondas", "buena suerte", "ornamental", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141814/plantas/mon01l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MPI10L120', 'Mandarina Piñatera', 'Citrus reticulata', 'árbol', 'Árbol frutal cítrico que produce mandarinas dulces, jugosas y de cáscara delgada de color naranja intenso. Puede alcanzar hasta 3-5 metros de altura, aunque existen variedades enanas aptas para macetas. Sus flores son blancas y muy aromáticas.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MPI10L120', 0, '["frutal", "cítrico", "exterior", "ornamental", "dulce", "perenne", "popular"]', '["bolsa 10 litros", "bolsa 45 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141842/plantas/mpi10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MRE10L120', 'Mandarina Reyna', 'Citrus reticulata', 'árbol', 'La Mandarina Reyna es un árbol pequeño de hoja perenne con follaje verde brillante y flores blancas fragantes. Produce frutos dulces, jugosos y fáciles de pelar, de color naranja a naranja rojizo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'MRE10L120', 0, '["frutal", "cítrico", "exterior", "dulce", "fácil de pelar", "árbol", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141859/plantas/mre10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MRO03L077', 'Manzana Red Delicius', 'Malus domestica ''Red Delicious''', 'árbol', 'El manzano ''Red Delicious'' es un árbol caducifolio de tamaño mediano a grande, conocido por sus frutos de piel roja brillante, pulpa firme, dulce y jugosa. Produce flores de color blanco-rosado a principios de la primavera.', 'sol directo', 'medio', 'difícil', 'disponible', 'ambas', 'tóxica', 'MRO03L077', 0, '["árbol frutal", "manzano", "fruto comestible", "exterior", "caducifolio", "requiere polinización", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141876/plantas/mro03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MST10L120', 'Mandarina Sangre De Toro', 'Citrus x sinensis', 'árbol', 'La Mandarina Sangre de Toro es una variedad de naranja sanguina (*Citrus x sinensis*) caracterizada por su pulpa de color rojo oscuro, similar al jugo de frambuesa, debido a la presencia de antocianinas. Posee un sabor equilibrado entre dulce y ácido, y es apreciada por sus propiedades antioxidantes y alto contenido de vitamina C. Es un árbol frutal de tamaño medio que requiere condiciones específicas de temperatura para desarrollar su coloración intensa.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MST10L120', 0, '["cítrico", "frutal", "antioxidante", "invierno", "naranja", "sanguina"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141894/plantas/mst10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MTA10L120', 'Mandarina Tangerina', 'Citrus reticulata', 'árbol', 'La mandarina tangerina es un árbol frutal cítrico, conocido por sus frutos redondos de color naranja rojizo, dulces y jugosos, con una cáscara fácil de pelar. Es rica en vitamina C, flavonoides y aceites esenciales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MTA10L120', 0, '["cítrico", "frutal", "árbol", "exterior", "vitamina C", "dulce", "popular"]', '["bolsa 10 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141913/plantas/mta10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MUI01L125', 'Muicle', 'Justicia spicigera Schltdl.', 'medicinal', 'El muicle es un arbusto perenne que alcanza de 1 a 2 metros de altura, caracterizado por sus tallos delgados y hojas lanceoladas de color verde oscuro. Produce flores tubulares de un intenso color naranja y sus hojas, al estrujarse, liberan un tinte púrpura. Es una especie nativa de México y Centroamérica.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'MUI01L125', 0, '["medicinal", "arbusto", "nativa de México", "flores naranjas", "tinte natural", "fácil cuidado", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141940/plantas/mui01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('MVE04L077', 'Manzana Verde', 'Malus domestica', 'árbol', 'El manzano (Malus domestica) es un árbol caducifolio de tamaño mediano, con una copa redondeada y hojas ovaladas. Produce flores blancas o rosadas en primavera y frutos conocidos como manzanas, que son pomos globosos. Las manzanas verdes, como la variedad Granny Smith, son crujientes, jugosas y de sabor ácido.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'MVE04L077', 0, '["árbol frutal", "manzano", "fruta", "exterior", "caducifolio", "Rosaceae"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141959/plantas/mve04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NAN03L116', 'Nanche', 'Byrsonima crassifolia', 'árbol', 'El Nanche es un arbusto grande o árbol de crecimiento lento, que puede alcanzar entre 5 y 20 metros de altura. Produce pequeños frutos redondos de color amarillo a rojizo, con un aroma fuerte y un sabor agridulce. Sus hojas son alargadas y rígidas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'NAN03L116', 0, '["frutal", "tropical", "ornamental", "medicinal", "resistente a sequía", "árbol"]', '["bolsa 3 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141975/plantas/nan03l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NAN15L006', 'Nandina', 'Nandina domestica', 'exterior', 'Es un arbusto perennifolio o semiperennifolio de hasta 3 metros de altura, con tallos erectos y hojas compuestas que cambian de verde a tonos rojizos y anaranjados en otoño e invierno. Produce pequeñas flores blancas en panículas y vistosas bayas rojas que persisten desde el otoño hasta la primavera.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'NAN15L006', 0, '["arbusto", "perennifolio", "follaje decorativo", "bayas rojas", "resistente al frío", "exterior", "popular"]', '["bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777141993/plantas/nan15l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NBR04P126', 'Neon Break', 'Echeveria ''Neon Breakers''', 'suculenta', 'Esta suculenta forma rosetas llamativas con hojas que exhiben tonos de rosa, morado y azul-verde. Sus bordes son distintivamente rizados y de un vibrante color rosa intenso. Puede crecer hasta 8 pulgadas de diámetro.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'NBR04P126', 0, '["suculenta", "echeveria", "ornamental", "exterior", "fácil cuidado", "hojas coloridas"]', '["maceta negra 4 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142020/plantas/nbr04p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NBU07P159', 'Noche Buena', 'Euphorbia pulcherrima', 'ornamental', 'La Nochebuena es un arbusto o pequeño árbol, que típicamente alcanza entre 0.6 y 4 metros de altura. Es conocida por sus vistosas brácteas de colores intensos, comúnmente rojas, que a menudo se confunden con flores, siendo estas últimas pequeñas y amarillas en el centro. Es una planta emblemática de la temporada navideña.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'NBU07P159', 0, '["Navidad", "arbusto", "brácteas de colores", "interior", "exterior", "México"]', '["maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142043/plantas/nbu07p159.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NCA20L013', 'Naranja Calamondi', 'Citrus × microcarpa', 'ornamental', 'La Naranja Calamondín es un pequeño árbol o arbusto perenne, híbrido de mandarina y kumquat, con hojas verdes brillantes y flores blancas fragantes. Produce pequeños frutos redondos de color naranja, muy ácidos pero comestibles, utilizados en la cocina. Es valorado tanto por su estética ornamental como por su producción de frutos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'NCA20L013', 0, '["árbol frutal", "cítrico", "interior", "exterior", "frutos comestibles", "aromática"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142062/plantas/nca20l013.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NCP08L077', 'Nogal Cascara De Papel', 'Carya illinoinensis', 'árbol', 'El nogal cáscara de papel, o pecán, es un árbol caducifolio grande nativo de América del Norte, conocido por sus nueces dulces y comestibles. Puede alcanzar alturas de 20 a 30 metros y desarrolla una copa amplia y extendida. Sus frutos tienen una cáscara delgada que se abre en cuatro secciones al madurar.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'NCP08L077', 0, '["árbol frutal", "nuez", "pecanero", "exterior", "madera", "caducifolio"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142084/plantas/ncp08l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NCP45L152', 'Nuez Cascara De Papel', 'Carya illinoinensis', 'árbol', 'El nogal pecanero es un árbol caducifolio y monoico que puede alcanzar más de 40 metros de altura. Su fruto, la nuez pecana o nuez cáscara de papel, es muy apreciado por su sabor y propiedades nutricionales, caracterizándose por una cáscara delgada y fácil de retirar. Es nativo del noreste de México y el sureste de Estados Unidos.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'NCP45L152', 0, '["frutal", "nuez", "pecana", "árbol grande", "cultivo", "saludable"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142104/plantas/ncp45l152.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NEE10L115', 'Neem', 'Azadirachta indica', 'medicinal', 'El Neem (Azadirachta indica) es un árbol de hoja perenne originario de la India y Birmania, que puede alcanzar entre 15 y 20 metros de altura. Es ampliamente reconocido por sus múltiples propiedades medicinales y su uso tradicional en la medicina ayurvédica. Además, se valora por sus compuestos naturales con efectos insecticidas y repelentes.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'NEE10L115', 0, '["árbol", "medicinal", "insecticida", "Ayurveda", "exterior", "resistente a la sequía"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142123/plantas/nee10l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NEN10P134', 'Nenunfares', 'Nymphaea spp.', 'ornamental', 'Los nenúfares (Nymphaea spp.) son plantas acuáticas con flores vistosas que flotan en la superficie del agua, junto con sus grandes hojas. Son originarios de Asia y África, y se cultivan en estanques y lagos por su belleza.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'tóxica', 'NEN10P134', 0, '["planta acuática", "flores", "estanque", "flotante", "ornamental", "Nymphaea"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142142/plantas/nen10p134.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NIS60L105', 'Nispero', 'Eriobotrya japonica', 'árbol', 'El níspero es un árbol o arbusto de hoja perenne, originario de Asia, que puede alcanzar entre 5 y 10 metros de altura. Posee un follaje denso con hojas grandes, coriáceas y de color verde oscuro brillante. Produce flores blancas fragantes en otoño-invierno y frutos comestibles de color amarillo a naranja, dulces y jugosos, con grandes semillas marrones en su interior.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'NIS60L105', 0, '["frutal", "ornamental", "perenne", "subtropical", "medicinal", "exterior"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142167/plantas/nis60l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NMI10L120', 'Naranja Miniola', 'Citrus × tangelo', 'árbol', 'La Naranja Miniola, también conocida como Minneola tangelo, es un híbrido cítrico resultante del cruce entre un pomelo Duncan y una mandarina Dancy. Se caracteriza por su forma de campana, piel rojiza-anaranjada fácil de pelar y pulpa jugosa con un sabor agridulce y aromático.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'NMI10L120', 0, '["cítrico", "frutal", "árbol", "exterior", "agridulce", "forma de campana"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142183/plantas/nmi10l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NMO01L125', 'No Me Olvides', 'Myosotis', 'ornamental', 'El Myosotis, conocido comúnmente como ''No Me Olvides'', es una planta herbácea que puede ser anual, bienal o perenne, caracterizada por sus pequeñas y delicadas flores, generalmente azules con un centro amarillo. Forma matas bajas de hasta 30-80 cm de altura con tallos vellosos y hojas estrechas. Es apreciada por su valor ornamental en jardines, rocallas y macetas, simbolizando el recuerdo fiel.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'NMO01L125', 0, '["flor azul", "jardín", "ornamental", "fácil cuidado", "perenne", "Boraginaceae", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142203/plantas/nmo01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NPA04L006', 'Nevando En Paris Bco', 'Breynia disticha', 'ornamental', 'Es un arbusto ornamental con hojas variegadas en tonos verdes, blancos y rosados cuando son jóvenes. Puede alcanzar entre 1 y 2 metros de altura, aportando un toque elegante y moderno.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'NPA04L006', 0, '["arbusto", "variegada", "follaje decorativo", "fácil cuidado", "interior", "exterior"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142233/plantas/npa04l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('NWA10L013', 'Naranja Washintonia Red', 'Citrus sinensis ''Washington Navel''', 'árbol', 'La Naranja Washington Navel Roja es una variedad de naranja dulce, conocida por su pulpa de color naranja intenso a rojizo, a menudo sin semillas y fácil de pelar. Produce frutos grandes y redondos con un sabor dulce, que maduran de finales de otoño a finales de invierno. Es un árbol de hoja perenne con follaje verde brillante y flores blancas fragantes en primavera.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'NWA10L013', 0, '["frutal", "cítrico", "árbol de hoja perenne", "naranja ombligo", "fruto comestible", "exterior"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142261/plantas/nwa10l013.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('OAR03L113', 'Orquidea De Arbol', 'Bauhinia variegata', 'árbol', 'Es un árbol o arbusto semicaducifolio de copa ancha, que puede alcanzar hasta 10 metros de altura. Sus hojas son redondeadas con una hendidura central, parecidas a una pezuña de vaca. Produce flores grandes y fragantes, similares a las orquídeas, en tonos de rosa, púrpura, blanco y amarillo.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'OAR03L113', 0, '["árbol", "flores vistosas", "ornamental", "pata de vaca", "tropical", "exterior"]', '["bolsa 3 litros", "bolsa 20 litros", "bolsa 65 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142285/plantas/oar03l113.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('OFR20L108', 'Olivo De Fruta', 'Olea europaea', 'árbol', 'El olivo (Olea europaea) es un árbol perennifolio de crecimiento lento y larga vida, nativo de la región mediterránea. Se caracteriza por su tronco grueso y retorcido, hojas lanceoladas de color verde plateado y produce frutos conocidos como aceitunas. Es valorado tanto por su fruto para aceite y consumo, como por su uso ornamental.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'OFR20L108', 0, '["mediterráneo", "frutal", "longevo", "ornamental", "resistente a la sequía", "aceitunas", "medicinal"]', '["bolsa 20 litros", "bolsa 4 litros", "bolsa 45 litros", "bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142304/plantas/ofr20l108.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ONE60L006', 'Olivo Negro', 'Bucida buceras', 'árbol', 'El Olivo Negro es un árbol ornamental conocido por sus hojas alargadas y de color verde oscuro, con un matiz casi negro. Posee un porte estilizado y una copa compacta e irregular, lo que lo hace ideal para decorar interiores y jardines. Es un árbol de hoja perenne en lugares húmedos y caducifolio en zonas más secas.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'ONE60L006', 0, '["árbol ornamental", "árbol de sombra", "follaje oscuro", "tropical", "exterior", "interior"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142323/plantas/one60l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('OPH06P003', 'Orquidea Phalenopsis', 'Phalaenopsis sp.', 'ornamental', 'La Orquídea Phalaenopsis, también conocida como orquídea mariposa, es un género de orquídeas monopodiales, mayormente epífitas, con hojas grandes y carnosas. Sus elegantes flores, que recuerdan a mariposas en vuelo, son muy apreciadas por su belleza y larga duración, convirtiéndolas en populares plantas ornamentales.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'OPH06P003', 0, '["orquídea", "flor", "epífita", "planta de interior", "fácil cuidado", "decorativa", "tropical", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142339/plantas/oph06p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('OPU06L124', 'Opuntia', 'Opuntia', 'suculenta', 'Opuntia es un género de plantas cactáceas originarias del continente americano, caracterizadas por sus segmentos planos y carnosos llamados cladodios. Estas plantas son muy rústicas y ramificadas, adaptándose a climas áridos y semiáridos, y muchas de sus especies producen flores vistosas y frutos comestibles.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'OPU06L124', 0, '["cactus", "nopal", "suculenta", "resistente", "frutal", "ornamental"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142356/plantas/opu06l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ORE01L125', 'Oregano', 'Origanum vulgare', 'exterior', 'El orégano (Origanum vulgare) es una hierba aromática perenne de la familia Lamiaceae, nativa de la región mediterránea. Se caracteriza por sus hojas ovaladas de color verde oscuro y pequeñas flores blancas, rosas o púrpuras. Es ampliamente valorada en la gastronomía como condimento y reconocida por sus propiedades medicinales.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'ORE01L125', 0, '["hierba aromática", "culinaria", "mediterránea", "perenne", "medicinal", "fácil cuidado", "popular"]', '["bolsa 1 litros", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142381/plantas/ore01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('OVI02L010', 'Oro Viejo', 'Juniperus ''Old Gold''', 'exterior', 'El ''Oro Viejo'' es un arbusto conífero compacto, a menudo utilizado en paisajismo y como bonsái. Su follaje, de un vibrante verde limón, adquiere un tono dorado cenizo durante el otoño e invierno, lo que le da su nombre característico.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'OVI02L010', 0, '["arbusto", "conífera", "follaje dorado", "paisajismo", "bonsái", "exterior", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142402/plantas/ovi02l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAB10L009', 'Palma Abanico', 'Washingtonia robusta', 'árbol', 'La Washingtonia robusta es una palmera de gran tamaño, con un tronco robusto y esbelto que puede alcanzar hasta 35 metros de altura. Sus hojas son grandes y distintivas, en forma de abanico, con segmentos divididos y largos pecíolos espinosos. Es una especie ornamental muy utilizada en exteriores, especialmente en climas cálidos y secos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PAB10L009', 0, '["palmera", "exterior", "ornamental", "resistente a la sequía", "gran tamaño"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142424/plantas/pab10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAC08P001', 'Pachypodium', 'Pachypodium', 'suculenta', 'Pachypodium es un género de árboles y arbustos suculentos, nativos de Madagascar y África, que se caracterizan por sus tallos engrosados (cáudex) que almacenan agua y a menudo están cubiertos de espinas. Sus hojas suelen agruparse en la parte superior de los tallos y muchas especies producen flores vistosas. Son plantas adaptadas a climas cálidos y secos.', 'sol directo', 'bajo', 'intermedio', 'disponible', 'ambas', 'tóxica', 'PAC08P001', 0, '["suculenta", "espinosa", "cáudex", "Madagascar", "África", "floración vistosa"]', '["maceta negra 8 pulgadas", "bolsa 30 litros", "maceta negra 14 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142446/plantas/pac08p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAC45L153', 'Pachyra', 'Pachira aquatica', 'ornamental', 'La Pachira aquatica, conocida popularmente como Árbol del Dinero, es un árbol tropical de humedales originario de América Central y del Sur. Se caracteriza por sus hojas palmadas de color verde brillante y un tronco que a menudo se trenza cuando se cultiva como planta de interior. Es apreciada por su valor ornamental y su asociación con la buena fortuna.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PAC45L153', 0, '["Árbol del dinero", "planta de interior", "tropical", "follaje", "fácil cuidado", "buena suerte"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142467/plantas/pac45l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAK06P010', 'Paquistaqui', 'Pachystachys lutea', 'ornamental', 'La Pachystachys lutea es un arbusto perennifolio tropical que puede alcanzar entre 0.5 y 2.5 metros de altura, nativo de América Central y del Sur. Se distingue por sus vistosas brácteas amarillas superpuestas que recuerdan a camarones o paletas, de las cuales emergen pequeñas flores blancas. Sus hojas son lanceoladas, de color verde oscuro y con nervios prominentes.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PAK06P010', 0, '["Planta camarón", "Choclo de oro", "Arbusto", "Tropical", "Flores blancas", "Brácteas amarillas", "Planta de interior", "popular"]', '["maceta negra 6 pulgadas", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142486/plantas/pak06p010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAM60L006', 'Pampagras', 'Cortaderia selloana', 'ornamental', 'La Cortaderia selloana, conocida como Hierba de la Pampa, es una gramínea perenne robusta originaria de Sudamérica. Forma densos macizos de hojas largas y estrechas con bordes afilados, y produce grandes penachos plumosos de color blanco plateado o rosa pálido que pueden alcanzar hasta 3 metros de altura. Es valorada por su atractivo ornamental, pero puede ser invasora en algunas regiones.', 'sol directo', 'bajo', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PAM60L006', 0, '["Hierba de la Pampa", "plumero", "exterior", "resistente", "invasora", "Sudamérica"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142501/plantas/pam60l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAN30L011', 'Pandanus', 'Pandanus', 'ornamental', 'El género Pandanus agrupa alrededor de 600 especies de árboles y arbustos tropicales, conocidos por sus tallos esbeltos y raíces aéreas de soporte. Sus hojas, largas y en forma de espada, se disponen en espiral, dándoles una apariencia distintiva. Varían en tamaño, desde pequeños arbustos hasta árboles que alcanzan los 20 metros de altura.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PAN30L011', 0, '["tropical", "palmera falsa", "hojas espinosas", "raíces aéreas", "árbol", "exterior"]', '["bolsa 30 litros", "maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142524/plantas/pan30l011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAP01L116', 'Papaya', 'Carica papaya', 'exterior', 'La papaya (Carica papaya) es una planta herbácea arborescente perennifolia de rápido crecimiento, que puede alcanzar entre 2 y 10 metros de altura. Se caracteriza por su tronco recto y sin ramificaciones, coronado por grandes hojas lobuladas. Produce frutos grandes, dulces y jugosos, ampliamente valorados por su consumo y propiedades.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'PAP01L116', 0, '["frutal", "tropical", "perenne", "rápido crecimiento", "papaína", "medicinal"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142544/plantas/pap01l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAP30L105', 'Papaya Maradol', 'Carica papaya L.', 'árbol', 'La Papaya Maradol es una variedad de papaya conocida por sus frutos grandes, ovalados a alargados, con piel gruesa que madura de verde a amarillo-anaranjado. Su pulpa es dulce, firme y jugosa, de color que va del dorado al rojo salmón, y contiene numerosas semillas negras comestibles. La planta es un árbol herbáceo de porte bajo, cultivado por su alta productividad.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'tóxica', 'PAP30L105', 0, '["fruta tropical", "árbol frutal", "dulce", "papaína", "vitamina C", "cultivo comercial"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142563/plantas/pap30l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAR06L200', 'Palma Areka', 'Dypsis lutescens', 'ornamental', 'La Palma Areka es una palmera tropical de hojas perennes, originaria de Madagascar, conocida por su follaje plumoso y arqueado de color verde brillante. Puede alcanzar varios metros de altura, con tallos delgados que le dan una apariencia similar al bambú. Es muy apreciada por su capacidad para purificar el aire y su elegancia.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PAR06L200', 0, '["tropical", "palmera", "interior", "purificadora de aire", "fácil cuidado", "follaje", "popular"]', '["bolsa 6 litros", "bolsa 10 litros", "bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142582/plantas/par06l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAR50L129', 'Parota', 'Enterolobium cyclocarpum', 'árbol', 'Árbol grande y caducifolio, nativo de las regiones tropicales de América, conocido por su amplia copa y sus distintivas vainas de semillas en forma de oreja. Puede alcanzar alturas de hasta 45 metros y es valorado por su madera y la sombra que proporciona.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PAR50L129', 0, '["árbol tropical", "madera", "sombra", "medicinal", "semillas comestibles", "fijador de nitrógeno"]', '["bolsa 50 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142602/plantas/par50l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAZ03L006', 'Plumbago Blanco', 'Plumbago auriculata ''Alba''', 'exterior', 'Es un arbusto perenne de crecimiento extendido y arqueado, que produce abundantes flores blancas en forma de trompeta con cinco pétalos. Florece desde primavera hasta otoño, o casi todo el año en climas cálidos. Sus hojas son de color verde claro y forma espatulada.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PAZ03L006', 0, '["arbusto", "ornamental", "flores blancas", "trepadora", "resistente sequía", "atrae mariposas", "popular"]', '["bolsa 3 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142625/plantas/paz03l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PAZ03L009', 'Plumbago Azul', 'Plumbago auriculata', 'ornamental', 'La Plumbago Azul es un arbusto perenne trepador originario de Sudáfrica, conocido por sus abundantes racimos de flores de color azul cielo. Florece durante gran parte del año en climas cálidos y puede cultivarse como arbusto, cubresuelos o planta trepadora. Es una planta ornamental popular por su belleza y facilidad de cuidado.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PAZ03L009', 0, '["arbusto", "trepadora", "flores azules", "exterior", "fácil cuidado", "atrae mariposas", "popular"]', '["bolsa 3 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142647/plantas/paz03l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PBA10L006', 'Palma Bambu', 'Chamaedorea seifrizii', 'ornamental', 'La Palma Bambú (Chamaedorea seifrizii) es una palmera de tamaño mediano que se asemeja al bambú, con tallos delgados y agrupados. Sus hojas pinnadas de color verde intenso aportan frescura y un aire natural, siendo muy apreciada como planta ornamental de interior. Es conocida por su resistencia y bajo mantenimiento, adaptándose bien a la luz indirecta.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PBA10L006', 0, '["palmera", "interior", "tropical", "bajo mantenimiento", "purificadora de aire", "elegante"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142668/plantas/pba10l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PBI30L077', 'Palma Bismarquia', 'Bismarckia nobilis', 'ornamental', 'Es una palmera majestuosa y robusta, endémica de Madagascar, con grandes hojas en forma de abanico de color azul plateado. Puede alcanzar alturas de hasta 25 metros en su hábitat natural y es muy valorada en paisajismo por su imponente porte.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PBI30L077', 0, '["palmera", "exterior", "hojas plateadas", "resistente sequía", "gran porte", "Madagascar"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142695/plantas/pbi30l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PBR07P077', 'Palo De Brasil', 'Dracaena fragrans', 'interior', 'El Palo de Brasil es una planta arbustiva ornamental muy popular, caracterizada por sus hojas largas y arqueadas de color verde brillante, a menudo con franjas amarillas, y un tronco leñoso. Es apreciada por su elegancia y su capacidad para purificar el aire en interiores. En su hábitat natural puede alcanzar varios metros de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PBR07P077', 0, '["planta de interior", "ornamental", "purificadora de aire", "Dracaena", "fácil cuidado", "tropical", "popular"]', '["maceta negra 7 pulgadas", "maceta negra 6 pulgadas", "maceta negra 5 pulgadas", "maceta negra 8 pulgadas", "bolsa 4 litros", "bolsa 20 litros", "bolsa 1 litros", "bolsa 6 litros", "bolsa 8 litros", "maceta negra 9 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142722/plantas/pbr07p077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCA06P001', 'Pasto Canguro', 'Themeda triandra', 'exterior', 'Es una gramínea perenne que forma matas densas, alcanzando hasta 1.5 metros de altura. Sus hojas son de color verde a grisáceo, tornándose marrón anaranjado en verano, y produce espiguillas distintivas de color marrón rojizo en tallos ramificados.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PCA06P001', 0, '["gramínea", "pasto nativo", "resistente a la sequía", "ornamental", "bajo mantenimiento", "control de erosión", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142783/plantas/pca06p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCA06P006', 'Palma Camedor', 'Chamaedorea elegans', 'interior', 'La Palma Camedor es una pequeña y elegante palmera originaria de las selvas tropicales de México y Guatemala. Se caracteriza por sus tallos delgados y hojas pinnadas de textura delicada, lo que la convierte en una planta de interior muy popular. Su crecimiento es lento y puede alcanzar entre 60 y 180 cm de altura en interiores.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PCA06P006', 0, '["Palma de interior", "Planta ornamental", "Fácil cuidado", "Purificadora de aire", "No tóxica para mascotas", "Tropical", "popular"]', '["maceta negra 6 pulgadas", "bolsa 6 litros", "bolsa 20 litros", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142759/plantas/pca06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCI20L006', 'Palma Cica Dion Spinolosum', 'Dioon spinulosum', 'ornamental', 'Dioon spinulosum, también conocida como Cica Gigante o Palma Cica, es una cícada perenne de aspecto similar a una palma, con una roseta abierta de frondas pinnadas de color verde azulado. Es una de las cícadas más altas del mundo, pudiendo alcanzar hasta 12 metros en su hábitat natural, y se caracteriza por su crecimiento lento a moderado. Es apreciada por su follaje exuberante que añade un toque tropical a jardines y paisajes.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PCI20L006', 0, '["cícada", "ornamental", "tropical", "bajo mantenimiento", "resistente a la sequía", "planta antigua"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142804/plantas/pci20l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCO01L125', 'Pasto Coreano', 'Zoysia tenuifolia', 'ornamental', 'El Pasto Coreano (Zoysia tenuifolia) es un césped de textura fina y crecimiento lento que forma densos montículos, ideal para cubrir suelos y áreas decorativas. Es conocido por su resistencia a la sequía y su bajo mantenimiento una vez establecido. Se utiliza comúnmente en jardines, entre adoquines y en zonas de bajo tránsito.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PCO01L125', 2, '["césped", "cubre suelo", "bajo mantenimiento", "resistente a la sequía", "ornamental", "crecimiento lento", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142825/plantas/pco01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCO08L011', 'Palma Coco Comun', 'Cocos nucifera', 'árbol', 'La Palma Coco Común, o Cocos nucifera, es una palmera grande que puede alcanzar hasta 30 metros de altura, caracterizada por su tronco esbelto y hojas pinnadas y arqueadas. Produce el conocido fruto del coco, ampliamente valorado por su pulpa y agua. Es una planta tropical emblemática de las costas.', 'sol directo', 'medio', 'difícil', 'disponible', 'ambas', 'no tóxica', 'PCO08L011', 0, '["tropical", "palmera", "fruto comestible", "ornamental", "costera", "exótica", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142861/plantas/pco08l011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCO11P001', 'Philodendro Congo', 'Philodendron tatei ''Congo''', 'interior', 'El Philodendron ''Congo'' es un cultivar de filodendro de crecimiento erguido y arbustivo, no trepador. Se caracteriza por sus hojas grandes y brillantes que emergen en tonos verdes o rojizos y maduran a un verde oscuro. Es una planta de bajo mantenimiento ideal para interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PCO11P001', 0, '["planta de interior", "follaje grande", "fácil cuidado", "tropical", "no trepadora", "tóxica para mascotas", "popular"]', '["maceta negra 11 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142842/plantas/pco11p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCP20L009', 'Palma Coco Plumoso', 'Syagrus romanzoffiana', 'árbol', 'La Palma Coco Plumoso es una palmera elegante y de rápido crecimiento, con un tronco liso y grisáceo que puede alcanzar hasta 25 metros de altura. Sus hojas pinnadas y finamente divididas le confieren un distintivo aspecto plumoso. Es muy utilizada en paisajismo por su porte esbelto y atractivo estético.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PCP20L009', 0, '["palmera", "ornamental", "exterior", "tropical", "rápido crecimiento", "bajo mantenimiento"]', '["bolsa 20 litros", "bolsa 60 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142876/plantas/pcp20l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCR04L116', 'Palma Crepe', 'Curculigo capitulata', 'ornamental', 'Es una planta herbácea perenne con hojas largas y plegadas de color verde brillante que forman una roseta basal. Es conocida por su aspecto tropical y puede alcanzar hasta un metro de altura.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PCR04L116', 0, '["herbácea", "tropical", "hojas decorativas", "planta de interior", "fácil cuidado", "falsa palma"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142901/plantas/pcr04l116.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PCZ18L010', 'Palma Cola De Zorro', 'Wodyetia bifurcata', 'árbol', 'La Palma Cola de Zorro es una elegante palmera ornamental originaria de Australia, conocida por su rápido crecimiento. Se caracteriza por sus hojas pinnadas, arqueadas y plumosas que se asemejan a la cola de un zorro. Puede alcanzar hasta 15 metros de altura y posee un tronco liso y esbelto de color grisáceo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PCZ18L010', 0, '["palmera", "tropical", "ornamental", "exterior", "crecimiento rápido", "bajo mantenimiento"]', '["bolsa 18 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142920/plantas/pcz18l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PDA04L151', 'Palma Datilera', 'Phoenix dactylifera', 'árbol', 'La palma datilera (Phoenix dactylifera) es una palmera perenne que puede alcanzar entre 15 y 30 metros de altura. Es conocida por sus largos frutos dulces comestibles, los dátiles, y es originaria del norte de África, Oriente Medio y el sur de Asia. Sus hojas son pinnadas y espinosas, lo que la convierte en una planta ornamental y frutal muy apreciada.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PDA04L151', 0, '["palmera", "frutal", "exterior", "árido", "dátil", "paisajismo"]', '["bolsa 4 litros", "bolsa 15 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142938/plantas/pda04l151.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PDO20L009', 'Platano Dominico', 'Musa sapientum', 'árbol', 'El plátano dominico es una variedad de plátano que mide entre 22 y 30 centímetros de largo y pesa de 150 a 200 gramos. Su color es verde y al madurar se torna amarillo con manchas marrones. Su sabor en crudo es amargo, por lo que requiere cocción para volverse suave y mantecoso.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PDO20L009', 0, '["frutal", "tropical", "cocina", "cultivo", "exterior", "herbácea gigante"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142962/plantas/pdo20l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PED04L011', 'Pedilantus', 'Euphorbia tithymaloides', 'suculenta', 'Es un arbusto suculento perenne conocido por sus tallos en zigzag y hojas ovadas de color verde, que pueden presentar variegación. Produce pequeñas flores insignificantes envueltas en vistosas brácteas rojas en forma de zapatilla. Es una planta de bajo mantenimiento, popular tanto en interiores como en exteriores en climas cálidos.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PED04L011', 0, '["ornamental", "tallo zigzag", "fácil cuidado", "brácteas rojas", "planta de interior", "planta de exterior", "popular"]', '["bolsa 4 litros", "bolsa 10 litros", "bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777142741/plantas/ped04l011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PEL10P109', 'Peluca', 'Callisia repens', 'ornamental', 'La Callisia repens, conocida como ''Peluca'', es una pequeña planta perenne de porte colgante o cubridor, apreciada por su rápido crecimiento y su denso follaje. Sus hojas carnosas, a menudo en forma de corazón, pueden ser verdes o con tonos violáceos, creando un efecto de "cabellera" verde. Es ideal para macetas colgantes y como cubresuelos en climas adecuados.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PEL10P109', 0, '["planta colgante", "cubresuelos", "follaje decorativo", "fácil cuidado", "interior", "tropical", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143001/plantas/pel10p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PEN01L125', 'Pensamiento', 'Viola x wittrockiana', 'ornamental', 'El Pensamiento es una planta de porte bajo, que alcanza hasta 30 cm de altura, conocida por sus grandes y vistosas flores aterciopeladas en una amplia gama de colores. Florece abundantemente desde el otoño hasta la primavera, siendo ideal para aportar color en épocas frías.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PEN01L125', 0, '["flor", "invierno", "exterior", "maceta", "jardín", "colorida", "resistente al frío", "comestible", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143021/plantas/pen01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PEP06P109', 'Peperonia', 'Peperomia', 'interior', 'Las Peperomias son un género diverso de plantas tropicales, apreciadas por su follaje ornamental que varía en formas, colores y texturas. Sus hojas carnosas les permiten almacenar agua, lo que las hace relativamente fáciles de cuidar. Son populares como plantas de interior debido a su tamaño compacto y adaptabilidad.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PEP06P109', 0, '["ornamental", "tropical", "fácil cuidado", "no tóxica", "follaje variado", "suculenta", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 5 pulgadas", "maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143038/plantas/pep06p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PER10L153', 'Peregrina', 'Jatropha integerrima', 'ornamental', 'La Peregrina (Jatropha integerrima) es un arbusto o pequeño árbol perenne, nativo de Cuba y La Española, conocido por sus llamativas flores rojas en forma de estrella que florecen durante gran parte del año. Puede crecer hasta 4.5 metros de altura y es popular como planta ornamental en jardines tropicales y subtropicales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'PER10L153', 0, '["arbusto", "flores rojas", "tropical", "perenne", "ornamental", "tóxica", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143058/plantas/per10l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PES08L077', 'Palma Estrella', 'Rhapis excelsa', 'interior', 'La Palma Estrella, cuyo nombre científico es Rhapis excelsa, es una planta ornamental conocida por sus hojas palmeadas de color verde intenso que terminan en picos, simulando una estrella. Es apreciada por su capacidad para purificar el aire y su fácil cultivo, lo que la hace ideal para principiantes. Puede crecer tanto en interiores como en exteriores en semisombra.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PES08L077', 0, '["palma", "ornamental", "purificadora de aire", "fácil cuidado", "hojas verdes", "tropical", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143076/plantas/pes08l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PFI01L125', 'Pasto Fistuca', 'Festuca arundinacea', 'exterior', 'La Festuca arundinacea, conocida como Pasto Festuca alta, es una gramínea perenne de crecimiento otoño-invierno-primavera, con hojas brillosas y angostas. Forma un césped tupido y uniforme, y sus raíces profundas le otorgan una notable resistencia a la sequía y al pisoteo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PFI01L125', 0, '["césped", "forraje", "resistente", "bajo mantenimiento", "gramínea", "sequía", "pastizal", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143099/plantas/pfi01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PFR10L077', 'Piñon De Fruta', 'Jatropha curcas', 'medicinal', 'Jatropha curcas es un arbusto o árbol pequeño, de 1 a 5 metros de altura, con hojas ovadas. Produce frutos ovoides ligeramente trilobulados, carnosos y dehiscentes, que contienen semillas. Es conocida por sus propiedades medicinales y su uso en la producción de biocombustible.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'PFR10L077', 0, '["arbusto", "tóxica", "biocombustible", "exterior", "sequía", "fácil cuidado"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143119/plantas/pfr10l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PGO80L129', 'Pimienta Gorda', 'Pimenta dioica', 'árbol', 'La Pimienta Gorda (*Pimenta dioica*) es un árbol perennifolio originario de México y Centroamérica, que puede alcanzar hasta 20 metros de altura. Sus frutos secos son una especia muy valorada, conocida por su aroma que evoca una mezcla de clavo, canela y nuez moscada. Además de su uso culinario, la planta tiene aplicaciones medicinales y se cultiva en exteriores.', 'sol directo', 'medio', 'difícil', 'disponible', 'ambas', 'tóxica', 'PGO80L129', 0, '["árbol", "especia", "tropical", "medicinal", "aromática", "condimento"]', '["bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143139/plantas/pgo80l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PHI05P011', 'Philodendro', 'Philodendron', 'interior', 'Philodendron es un género grande de plantas con flores de la familia Araceae, conocido por su follaje exuberante y diverso. Muchas de sus especies son populares como plantas ornamentales y de interior, adaptándose bien a diferentes condiciones de luz y agua. Pueden tener hábitos de crecimiento variados, incluyendo trepadoras y no trepadoras, con hojas que varían en forma, tamaño y color.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PHI05P011', 0, '["planta de interior", "tropical", "follaje decorativo", "trepadora", "purificadora de aire", "Araceae"]', '["maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143157/plantas/phi05p011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PHO10L006', 'Photinea', 'Photinia x fraseri', 'ornamental', 'La Photinia es un arbusto de hoja perenne conocido por sus llamativas hojas que cambian de color, desde un rojo brillante en los brotes nuevos hasta tonos verdes o púrpuras en su madurez. Produce pequeñas flores blancas en primavera y es muy utilizada para setos y pantallas vegetales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PHO10L006', 0, '["arbusto", "seto", "hoja perenne", "follaje rojo", "jardinería", "exterior", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143192/plantas/pho10l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PHO20L120', 'Philodendro Hope', 'Philodendron bipinnatifidum ''Hope''', 'ornamental', 'Es una planta de interior perenne y arbustiva, conocida por sus grandes hojas verdes brillantes, profundamente lobuladas y con bordes ondulados. Originaria de las regiones tropicales de Sudamérica, puede alcanzar hasta 1.5 metros de altura y anchura. Su follaje denso y exuberante le confiere un aspecto tropical distintivo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PHO20L120', 0, '["tropical", "planta de interior", "follaje exuberante", "fácil cuidado", "hojas lobuladas", "purificadora de aire", "popular"]', '["bolsa 20 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143177/plantas/pho20l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PIM06P106', 'Philodendro Imperial Rojo', 'Philodendron erubescens ''Imperial Red''', 'interior', 'El Philodendron ''Imperial Red'' es una planta de interior magnífica, apreciada por su impresionante follaje que transiciona de un borgoña profundo a un verde oscuro brillante. Presenta un hábito de crecimiento erguido y compacto, formando una forma densa y tupida.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PIM06P106', 0, '["planta de interior", "follaje colorido", "fácil cuidado", "tropical", "arbustiva", "purificadora de aire", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143211/plantas/pim06p106.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PIN10L009', 'Piña', 'Ananas comosus', 'exterior', 'La piña (Ananas comosus) es una fruta tropical de la familia de las bromeliáceas, originaria de las regiones de tierras bajas de América del Sur. Es una planta herbácea perenne de escaso porte, con hojas duras y lanceoladas. Fructifica una vez al año, produciendo un único fruto fragante y dulce, muy apreciado en gastronomía.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PIN10L009', 0, '["fruta tropical", "bromeliácea", "comestible", "perenne", "sudamérica", "fácil cuidado", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143256/plantas/pin10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PIN12L006', 'Piñanona', 'Monstera deliciosa', 'ornamental', 'La Monstera deliciosa, conocida como Piñanona o Costilla de Adán, es una planta trepadora perenne originaria de las selvas tropicales de México y Centroamérica. Se caracteriza por sus grandes hojas verdes brillantes que desarrollan cortes y perforaciones distintivas a medida que maduran. Es muy apreciada como planta ornamental de interior por su estética exótica y su facilidad de cuidado.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PIN12L006', 0, '["Costilla de Adán", "Planta de interior", "Tropical", "Hojas fenestradas", "Trepadora", "Follaje", "popular"]', '["bolsa 12 litros", "bolsa 15 litros", "bolsa 6 litros", "bolsa 2 litros", "bolsa 4 litros", "bolsa 30 litros", "bolsa 10 litros", "bolsa 20 litros", "maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143230/plantas/pin12l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PIN45L009', 'Piña Ornamental', 'Ananas comosus', 'ornamental', 'La piña ornamental es una planta herbácea perenne tropical, conocida por su roseta de hojas largas y estrechas, a menudo con bordes espinosos. Produce un fruto pequeño y no comestible en forma de piña, que le confiere su valor decorativo. Es originaria de América del Sur y pertenece a la familia de las Bromeliaceae.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PIN45L009', 0, '["tropical", "bromelia", "planta de interior", "planta de exterior", "fruto decorativo", "fácil cuidado"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143286/plantas/pin45l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PKE45L077', 'Palma Kerpiz', 'Adonidia merrillii', 'ornamental', 'La Palma Kerpiz, también conocida como Palma de Manila o Palma de Navidad, es una palmera solitaria que puede alcanzar entre 3.7 y 10 metros de altura. Posee un tronco delgado y anillado, con hojas pinnadas y arqueadas. Sus frutos, de forma ovalada, se tornan rojos al madurar, dándole su apodo navideño.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PKE45L077', 0, '["palma", "tropical", "exterior", "interior", "fácil cuidado", "palmera de navidad"]', '["bolsa 45 litros", "bolsa 20 litros", "bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143302/plantas/pke45l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLA03L151', 'Platanillo', 'Canna indica', 'ornamental', 'La Canna indica, conocida como Platanillo o Achira, es una planta herbácea robusta que puede alcanzar entre 0.5 y 3.5 metros de altura. Se caracteriza por sus grandes hojas ovadas, similares a las del plátano, y sus vistosas flores que presentan tonalidades desde el amarillo intenso hasta el anaranjado o rojizo, a menudo con manchas. Posee rizomas subterráneos gruesos.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PLA03L151', 0, '["tropical", "rizomatosa", "flores vistosas", "jardín", "medicinal", "exterior", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143337/plantas/pla03l151.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLI04L200', 'Palma Licuala', 'Licuala grandis', 'ornamental', 'La Palma Licuala, o Licuala grandis, es una palma de crecimiento lento originaria de las selvas tropicales de Vanuatu y las Islas Salomón. Se distingue por sus grandes hojas brillantes, plegadas y en forma de abanico, que le dan un aspecto exótico. Puede alcanzar hasta 3-4 metros de altura en su hábitat natural, pero suele ser más pequeña cuando se cultiva en interiores.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PLI04L200', 0, '["palma", "tropical", "hojas grandes", "interior", "exterior", "crecimiento lento"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143358/plantas/pli04l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLR02L105', 'Pasto Liriope Rayado', 'Liriope muscari', 'ornamental', 'El Liriope Rayado es una planta perenne de follaje perenne, similar a la hierba, con hojas arqueadas y estrechas, a menudo variegadas con rayas cremosas o doradas. Produce espigas de flores lavanda o púrpuras a finales del verano, seguidas de pequeñas bayas negras en invierno. Es una excelente opción como cobertura de suelo o para bordes.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PLR02L105', 0, '["cobertura de suelo", "planta perenne", "fácil cuidado", "tolerante a la sequía", "follaje variegado", "bordes", "popular"]', '["bolsa 2 litros", "bolsa 7 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143379/plantas/plr02l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLT15P009', 'Papiro Litlle Tut', 'Cyperus papyrus ''Little Tut''', 'ornamental', 'El Papiro Little Tut es una planta acuática compacta y de fácil cultivo, ideal para estanques y jardines de agua. Presenta tallos delgados y erguidos coronados por un follaje plumoso en forma de paraguas. Alcanza una altura madura de entre 45 y 60 centímetros, aportando un elemento arquitectónico distintivo.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PLT15P009', 0, '["papiro", "acuática", "exterior", "interior", "fácil cuidado", "mascotas seguras"]', '["maceta negra 15 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143397/plantas/plt15p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLU04L009', 'Plumifero', 'Celosia argentea var. plumosa', 'ornamental', 'Es una planta herbácea anual de origen tropical, conocida por sus llamativas flores en forma de pluma con colores brillantes como rojo, rosa, amarillo y naranja. Puede alcanzar entre 20 y 90 cm de altura, dependiendo de la variedad.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PLU04L009', 0, '["floración vibrante", "planta anual", "sol", "jardín", "flor de corte", "fácil cuidado"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143416/plantas/plu04l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLU08L009', 'Plumero', 'Cortaderia selloana', 'ornamental', 'La Cortaderia selloana, conocida como Plumero o Hierba de la Pampa, es una planta herbácea perenne de gran tamaño, que puede alcanzar hasta 4 metros de altura. Se caracteriza por sus largas hojas con bordes afilados y sus distintivas inflorescencias plumosas de color blanco plateado o rosado que emergen a finales del verano. Es una planta ornamental muy adaptable, pero también considerada una especie invasora en muchas regiones.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PLU08L009', 0, '["ornamental", "exterior", "resistente", "invasora", "plumas", "pasto", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143433/plantas/plu08l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLU10L006', 'Plumeria', 'Plumeria rubra', 'ornamental', 'La Plumeria, también conocida como frangipani, es un arbusto grande o arbolillo de hoja caduca originario de México y América Central. Se distingue por sus flores muy fragantes y coloridas, que varían en tonos de blanco, amarillo, rosa y rojo. Sus ramas contienen una savia lechosa que es venenosa.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PLU10L006', 0, '["frangipani", "árbol tropical", "flor fragante", "exterior", "fácil cuidado", "hoja caduca"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143455/plantas/plu10l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PLV02L105', 'Pasto Liriope Verde', 'Liriope muscari', 'exterior', 'El Pasto Liriope Verde es una planta perenne herbácea, conocida por su denso follaje verde oscuro y arqueado, similar al césped. Produce espigas de flores violetas o blancas en verano, seguidas de pequeñas bayas negras en otoño. Es una excelente opción como cubierta vegetal de bajo mantenimiento y muy resistente.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PLV02L105', 0, '["cubresuelos", "perenne", "follaje verde", "resistente", "bajo mantenimiento", "ornamental", "popular"]', '["bolsa 2 litros", "bolsa 8 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143478/plantas/plv02l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PMA03L077', 'Pera Mantequilla', 'Pyrus communis', 'árbol', 'La pera mantequilla es un fruto exquisito de piel amarillo verdosa, a veces con tonos rojizos, y forma redondeada. Su pulpa es muy suave, jugosa y dulce, lo que la hace ideal para consumir fresca o en postres. Es una fruta rica en fibra y vitaminas, que favorece la salud digestiva y la hidratación.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PMA03L077', 0, '["frutal", "árbol frutal", "dulce", "jugosa", "exterior", "clima templado", "popular"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143497/plantas/pma03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PMA06L009', 'Platano Macho', 'Musa x paradisiaca', 'árbol', 'El plátano macho es un fruto de mayor tamaño y forma más angulosa que el plátano común, con una piel gruesa de color verde intenso que se torna amarilla al madurar. Su pulpa es harinosa y menos dulce, lo que lo hace ideal para cocinar como una verdura.', 'sol directo', 'alto', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PMA06L009', 0, '["frutal", "tropical", "cocina", "almidón", "cultivo", "exterior"]', '["bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143517/plantas/pma06l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PMO01L105', 'Pasto Monki', 'Ophiopogon japonicus', 'ornamental', 'El pasto Monki es una planta perenne de follaje denso y verde oscuro, que alcanza hasta 10 cm de altura. Es resistente a sequías y bajas temperaturas, ideal para cubrir suelos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PMO01L105', 0, '["cubresuelos", "perenne", "jardín", "follaje", "resistente", "bajo mantenimiento", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143539/plantas/pmo01l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('POL06L115', 'Polyalthia', 'Polyalthia longifolia', 'ornamental', 'Polyalthia longifolia es un árbol perenne de la familia Annonaceae, conocido por su forma columnar y su altura que puede alcanzar hasta 30 metros. Sus hojas son largas, lanceoladas y con márgenes ondulados, de un vibrante color verde brillante. En primavera, produce flores discretas de color verde pálido en forma de estrella.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'POL06L115', 0, '["árbol", "perenne", "fácil cuidado", "tolerante sequía", "Pino hindú", "Falsa Ashoka"]', '["bolsa 6 litros", "bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143593/plantas/pol06l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PON05P134', 'Pontederia', 'Pontederia cordata', 'exterior', 'La Pontederia cordata es una planta acuática perenne nativa de América, conocida por sus hojas brillantes en forma de corazón y sus espigas de flores azules, moradas o blancas que emergen sobre la superficie del agua. Crece vigorosamente en aguas poco profundas o suelos húmedos, alcanzando alturas de 60 a 120 cm. Es una excelente opción para estanques y jardines acuáticos, atrayendo polinizadores.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PON05P134', 0, '["acuática", "perenne", "ornamental", "flor azul", "planta de estanque", "nativa de América", "medicinal"]', '["maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143614/plantas/pon05p134.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('POR03P126', 'Porpusurum', 'Echeveria purpusorum', 'suculenta', 'La Echeveria purpusorum es una suculenta compacta que forma rosetas rígidas de hojas casi triangulares de color verde oscuro con marcas rojizas y un matiz plateado. Sus hojas son gruesas y carnosas, y puede producir flores en tonos naranja y amarillo. Es una planta ornamental muy valorada por su aspecto elegante y su resistencia a condiciones secas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'POR03P126', 0, '["suculenta", "Echeveria", "México", "ornamental", "bajo mantenimiento", "roseta"]', '["maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143637/plantas/por03p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PPR02L200', 'Pasto Penicetum Rojo', 'Pennisetum setaceum ''Rubrum''', 'ornamental', 'Esta gramínea ornamental de gran impacto visual se caracteriza por su follaje morado intenso a rojizo y sus espigas plumosas. Forma matas densas y arqueadas que pueden alcanzar hasta 1.5 metros de altura. Sus vistosas inflorescencias de color rojizo o púrpura aparecen desde mediados de verano hasta las heladas, aportando movimiento y color al jardín.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PPR02L200', 0, '["gramínea ornamental", "follaje rojizo", "resistente sequía", "bajo mantenimiento", "sol pleno", "jardín", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143675/plantas/ppr02l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PPV02L200', 'Pasto Penicetum Verde', 'Pennisetum setaceum', 'ornamental', 'El Pennisetum setaceum, conocido como Pasto Penicetum Verde o Capim do Texas Verde, es una gramínea ornamental de origen africano y asiático. Se caracteriza por su follaje verde vibrante y sus inflorescencias plumosas que emergen en verano y otoño, aportando textura y movimiento al paisaje. Forma densas matas de hojas finas y alargadas, siendo una opción popular para jardines de bajo mantenimiento.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PPV02L200', 0, '["pasto ornamental", "gramínea", "jardín", "bajo mantenimiento", "sol pleno", "resistente a la sequía", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143707/plantas/ppv02l200.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PRA10L011', 'Palma Rafiz', 'Rhapis excelsa', 'interior', 'La Rhapis excelsa, conocida comúnmente como Palma Raphis o Palma de Salón, es una palma de abanico perenne que forma densos grupos de tallos delgados y erguidos, similares al bambú. Posee hojas palmeadas de color verde oscuro, divididas en segmentos anchos y nervados. Es una planta de interior popular, apreciada por su apariencia elegante y su resistencia, tolerando bien las condiciones de poca luz.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PRA10L011', 0, '["Palma de salón", "Palma bambú", "Planta de interior", "Follaje verde", "Bajo mantenimiento", "Purificadora de aire", "popular"]', '["bolsa 10 litros", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143727/plantas/pra10l011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PRE07P109', 'Philodendro Red', 'Philodendron erubescens', 'interior', 'El Philodendron ''Red'' es una planta tropical ornamental, apreciada por sus hojas grandes y brillantes que a menudo emergen en tonos rojizos o burdeos, madurando a un verde oscuro. Sus tallos suelen ser de color rojo, añadiendo un atractivo contraste. Es una planta de interior popular por su follaje exuberante y su capacidad para purificar el aire.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PRE07P109', 0, '["tropical", "ornamental", "follaje rojo", "planta de interior", "purificadora de aire", "fácil cuidado", "popular"]', '["maceta negra 7 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143745/plantas/pre07p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PRE20L117', 'Palma Real', 'Roystonea regia', 'árbol', 'La Palma Real (Roystonea regia) es una majestuosa palmera que puede alcanzar hasta 40 metros de altura, caracterizada por un tronco liso y columnar de color grisáceo, ligeramente engrosado en el medio. Posee una elegante corona de grandes hojas pinnadas y es ampliamente valorada como árbol ornamental en regiones tropicales. Es el árbol nacional de Cuba y se distingue por su fácil cultivo y rápido crecimiento.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PRE20L117', 0, '["palmera", "tropical", "exterior", "paisajismo", "árbol nacional de Cuba", "crecimiento rápido"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143765/plantas/pre20l117.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PRI80L140', 'Primavera Rosa', 'Bougainvillea glabra', 'exterior', 'La Bougainvillea glabra, comúnmente conocida como ''Primavera Rosa'', es una planta trepadora leñosa y espinosa, famosa por sus vistosas brácteas de colores intensos, como el rosa, que envuelven pequeñas flores blancas. Crece vigorosamente y es ideal para cubrir muros, pérgolas o cultivarse como arbusto en climas cálidos y soleados.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'PRI80L140', 0, '["trepadora", "arbusto", "floración vibrante", "espinosa", "resistente a sequía", "clima cálido"]', '["bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143788/plantas/pri80l140.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PRO30L105', 'Palma Robelina', 'Phoenix roebelenii', 'ornamental', 'La Palma Robelina es una palmera enana de crecimiento lento, originaria del sudeste asiático. Se caracteriza por sus elegantes hojas pinnadas de color verde intenso, que le otorgan un aspecto delicado y tropical. Puede alcanzar hasta 5 metros de altura, aunque en cultivo rara vez supera los 2 metros.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PRO30L105', 0, '["palmera enana", "palmera pigmea", "planta tropical", "planta de interior", "planta de exterior", "bajo mantenimiento", "popular"]', '["bolsa 30 litros", "bolsa 5 litros", "bolsa 3 litros", "bolsa 45 litros", "bolsa 10 litros", "bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143804/plantas/pro30l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PSE08L001', 'Philodendro Sellum', 'Philodendron selloum', 'ornamental', 'Esta planta tropical es apreciada por sus grandes hojas verdes brillantes y profundamente lobuladas que crean un ambiente selvático. Puede crecer a un tamaño considerable, tanto en interiores como en exteriores en climas adecuados.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PSE08L001', 0, '["tropical", "hojas grandes", "planta de interior", "planta de exterior", "fácil cuidado", "purificadora de aire", "popular"]', '["bolsa 8 litros", "bolsa 10 litros", "bolsa 15 litros", "bolsa 20 litros", "bolsa 6 litros", "maceta negra 6 pulgadas", "bolsa 12 litros", "maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143835/plantas/pse08l001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PTW02L009', 'Pasto Twister', 'Juncus effusus spiralis', 'ornamental', 'Planta ornamental con hojas verdes rizadas que crecen en forma de espiral, dándole una apariencia peculiar. Forma matas densas de aproximadamente 30-36 cm de altura y ancho. Es ideal para contenedores y zonas húmedas.', 'luz indirecta', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PTW02L009', 0, '["planta acuática", "junco", "hojas rizadas", "exterior", "interior", "fácil cuidado", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143871/plantas/ptw02l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PVE08P109', 'Philodendro Verde', 'Philodendron ''Paraiso Verde''', 'ornamental', 'El Philodendron ''Paraiso Verde'' es una planta tropical muy buscada, apreciada por sus hojas grandes y alargadas con una impresionante variegación en tonos verdes y cremosos. Su hábito trepador la hace ideal para postes de musgo o celosías, añadiendo un toque exótico a cualquier espacio interior.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PVE08P109', 0, '["tropical", "trepadora", "follaje", "interior", "variegada", "fácil cuidado", "popular"]', '["maceta negra 8 pulgadas", "maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143895/plantas/pve08p109.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PVE30L006', 'Podocarpus Verde', 'Podocarpus macrophyllus', 'ornamental', 'El Podocarpus macrophyllus, también conocido como pino budista, es una conífera perenne que puede crecer como árbol o arbusto. Presenta hojas densas, de color verde oscuro y con forma de aguja, y es valorado por su versatilidad en paisajismo. Puede alcanzar hasta 20 metros de altura en jardines, aunque en maceta suele ser más pequeño.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PVE30L006', 0, '["árbol", "arbusto", "perenne", "seto", "bonsái", "bajo mantenimiento"]', '["bolsa 30 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143573/plantas/pve30l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PVI06P001', 'Philodendro Virking', 'Philodendron ''Birkin''', 'ornamental', 'El Philodendron ''Birkin'' es un cultivar llamativo conocido por sus hojas de color verde oscuro con distintivas rayas blancas cremosas. Crece de forma compacta y erguida, lo que lo convierte en una planta de interior muy popular por su follaje único y decorativo.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PVI06P001', 0, '["planta de interior", "hojas variegadas", "fácil cuidado", "tropical", "ornamental", "Philodendron", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143911/plantas/pvi06p001.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PWA60L105', 'Palma Washingtonia', 'Washingtonia robusta', 'ornamental', 'Es una palmera de la familia Arecaceae, con un tronco robusto y esbelto que puede alcanzar hasta 35 metros de altura. Sus grandes hojas en forma de abanico tienen largos pecíolos con bordes espinosos y, en su juventud, presentan hilos blancos que desaparecen con la edad. Es una especie de rápido crecimiento, muy utilizada como ornamental en jardines y espacios públicos.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'PWA60L105', 0, '["palmera", "árbol", "exterior", "rústica", "crecimiento rápido", "hojas en abanico"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143957/plantas/pwa60l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PXA08L006', 'Philodendro Xanadu', 'Philodendron xanadu', 'ornamental', 'El Philodendron xanadu es una planta perenne tropical conocida por sus hojas grandes, brillantes y profundamente lobuladas, que le dan un aspecto exuberante. Crece en densos grupos, alcanzando hasta 1.5 metros de altura y ancho. Es nativa del sur de Brasil y Paraguay, y se cultiva ampliamente como planta ornamental.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PXA08L006', 0, '["tropical", "follaje", "hojas lobuladas", "planta de interior", "planta de exterior", "fácil cuidado", "popular"]', '["bolsa 8 litros", "bolsa 30 litros", "bolsa 15 litros", "maceta negra 10 pulgadas", "bolsa 20 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143975/plantas/pxa08l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PZA07P003', 'Palma Zamioculca', 'Zamioculcas zamiifolia', 'interior', 'La Zamioculcas zamiifolia, conocida comúnmente como planta ZZ o gema de Zanzíbar, es una planta perenne herbácea tropical originaria de África oriental. Se caracteriza por sus hojas pinnadas, gruesas, cerosas y de color verde oscuro brillante, que crecen desde rizomas subterráneos. Esta planta es muy apreciada por su resistencia y su capacidad para almacenar agua en sus tallos y rizomas, lo que la hace tolerante a la sequía y de fácil cuidado.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'PZA07P003', 0, '["planta ZZ", "gema de Zanzíbar", "planta de la eternidad", "resistente", "purificadora de aire", "suculenta", "ornamental"]', '["maceta negra 7 pulgadas", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777143995/plantas/pza07p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('PZA20L105', 'Palma Zamia', 'Zamia furfuracea', 'ornamental', 'La Zamia furfuracea, conocida comúnmente como Palma Zamia o Palma de Cartón, es una cícada de crecimiento lento originaria de México. Posee un tronco corto y hojas rígidas, coriáceas y de textura afelpada, que le dan una apariencia similar al cartón. Puede alcanzar hasta 1.3 metros de altura y 2 metros de ancho, siendo una planta muy decorativa.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'PZA20L105', 0, '["cícada", "bajo mantenimiento", "tolerante a la sequía", "planta de interior", "planta de exterior", "hojas texturizadas"]', '["bolsa 20 litros", "bolsa 60 litros", "maceta negra 8 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144014/plantas/pza20l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('QUI20L006', 'Quisqualis', 'Combretum indicum', 'ornamental', 'La Quisqualis, cuyo nombre científico es Combretum indicum, es una enredadera leñosa trepadora que puede alcanzar hasta 10 metros de altura. Sus flores fragantes cambian de color del blanco al rosa y finalmente al rojo a medida que maduran. Es una planta ornamental muy apreciada en jardines tropicales y subtropicales.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'QUI20L006', 0, '["trepadora", "flores fragantes", "exterior", "tropical", "fácil cuidado", "medicinal"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144038/plantas/qui20l006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RCO02L167', 'Rosa Coster', 'Rosa polyantha', 'ornamental', 'La Rosa Coster es un rosal enano que generalmente no supera los 50-60 cm de altura. Es conocida por su abundante floración durante todo el año, produciendo flores en forma de pompón. Pertenece a la familia de las rosáceas y es una planta ornamental muy apreciada.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'RCO02L167', 0, '["rosal enano", "floración continua", "exterior", "maceta", "jardín", "ornamental", "popular"]', '["bolsa 2 litros", "bolsa 6 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144058/plantas/rco02l167.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RCO05P003', 'Rosario Colgante', 'Curio rowleyanus', 'ornamental', 'La planta Rosario Colgante, o Curio rowleyanus, es una suculenta perenne con tallos rastreros y hojas esféricas que se asemejan a pequeñas perlas. Es muy popular como planta ornamental, especialmente en cestas colgantes, debido a su distintivo follaje que cae en cascada. Es originaria de las zonas secas de Sudáfrica.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'RCO05P003', 0, '["suculenta", "colgante", "interior", "fácil cuidado", "hojas esféricas", "Sudáfrica"]', '["maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144074/plantas/rco05p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RDO40L145', 'Rosa Dorada', 'Rosa sp.', 'ornamental', 'La ''Rosa Dorada'' es un nombre común que se refiere a diversas variedades de rosales que producen flores de color amarillo intenso o dorado. Estas rosas son arbustos o trepadoras, apreciadas por su belleza ornamental y, a menudo, por su fragancia. Florecen desde la primavera hasta el otoño.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'RDO40L145', 0, '["rosa", "arbusto", "flor", "jardín", "ornamental", "amarilla"]', '["bolsa 40 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144096/plantas/rdo40l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('REA01L149', 'Rea Tricolor', 'Tradescantia spathacea ''Tricolor''', 'ornamental', 'Es una planta perenne de follaje llamativo, con hojas en forma de espada dispuestas en roseta. Sus hojas son verdes y blancas o rosadas en la parte superior, y de un vibrante color púrpura en el envés. Produce pequeñas flores blancas que se encuentran dentro de brácteas púrpuras en forma de bote.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'REA01L149', 0, '["ornamental", "follaje colorido", "bajo mantenimiento", "interior", "exterior", "tropical", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144116/plantas/rea01l149.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RIN01L011', 'Rinonina', 'Ipomoea pes-caprae', 'medicinal', 'La Riñonina es una enredadera perenne que crece al ras de las arenas de las playas tropicales, formando un manto denso. Sus hojas tienen forma de pezuña de cabra y sus flores son acampanadas de un atractivo color rosa.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'RIN01L011', 0, '["enredadera", "playa", "dunas costeras", "medicinal renal", "flor rosa", "resistente a la sal", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144131/plantas/rin01l011.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RNU08L169', 'Romero De Nuez', 'Salvia rosmarinus', 'medicinal', 'Es una planta arbustiva perenne, muy aromática y resistente, originaria del Mediterráneo. Se caracteriza por sus hojas finas de color verde oscuro y flores violeta-azuladas, desprendiendo un distintivo aroma a nuez al ser tocada.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'RNU08L169', 0, '["aromática", "culinaria", "arbusto", "perenne", "jardín", "olor a nuez", "popular"]', '["bolsa 8 litros", "bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144154/plantas/rnu08l169.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ROM02L119', 'Romero', 'Salvia rosmarinus', 'medicinal', 'El romero es un arbusto aromático leñoso perenne, nativo de la región mediterránea, con hojas finas, similares a agujas, y flores pequeñas que pueden ser azuladas, blanquecinas o rosáceas. Alcanza una altura de 1 a 2 metros y es valorado por su fragancia y usos culinarios y medicinales.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ROM02L119', 0, '["aromática", "arbusto", "perenne", "mediterránea", "culinaria", "fácil cuidado", "popular"]', '["bolsa 2 litros", "bolsa 10 litros", "bolsa 8 litros", "bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144178/plantas/rom02l119.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ROS03L167', 'Rosal', 'Rosa spp.', 'ornamental', 'Los rosales son arbustos espinosos de la familia de las rosáceas, ampliamente valorados por sus hermosas y fragantes flores que presentan una gran diversidad de colores y formas. Se cultivan principalmente con fines ornamentales en jardines, aunque también se utilizan en la industria de la perfumería y con fines medicinales. Requieren sol directo y un riego regular para un desarrollo óptimo.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'ROS03L167', 0, '["arbusto", "flores", "jardín", "ornamental", "espinas", "fragante", "popular"]', '["bolsa 3 litros", "bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144196/plantas/ros03l167.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('RRA08L120', 'Romero Rastrero', 'Salvia rosmarinus ''Prostrata''', 'ornamental', 'El Romero Rastrero es una variedad de romero de porte bajo y crecimiento horizontal, que forma una alfombra verde y aromática. Sus hojas son pequeñas y puntiagudas, y produce flores de tonos azules, violetas o blancos a finales de primavera y principios de verano. Es ideal para cubrir suelos, rocallas y como planta colgante en jardines mediterráneos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'RRA08L120', 0, '["Cubresuelos", "Aromática", "Mediterránea", "Jardinería", "Medicinal", "Culinaria"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144221/plantas/rra08l120.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SAB11P170', 'Sabila Reyna', 'Aloe vera (L.) Burm.f.', 'medicinal', 'La sábila, también conocida como aloe vera, es una planta suculenta con hojas carnosas de color verde grisáceo y bordes dentados, que contienen un gel transparente y viscoso. Es ampliamente valorada por sus propiedades medicinales y cosméticas.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'SAB11P170', 0, '["suculenta", "medicinal", "ornamental", "fácil cuidado", "sol", "exterior", "popular"]', '["maceta negra 11 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144241/plantas/sab11p170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SAL02L119', 'Salvia Leucanta', 'Salvia leucantha', 'ornamental', 'La Salvia leucantha, también conocida como Salvia mexicana, es un arbusto perenne originario de México y Centroamérica. Se distingue por sus vistosas espigas de flores aterciopeladas, generalmente con cálices morados y corolas blancas, que florecen desde finales del verano hasta la primera helada. Sus hojas son de color verde grisáceo y textura suave, atrayendo a colibríes y mariposas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'SAL02L119', 0, '["arbusto", "perenne", "floración prolongada", "atrae polinizadores", "resistente sequía", "jardín mediterráneo", "popular"]', '["bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144263/plantas/sal02l119.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SAN03L105', 'Sanciviera', 'Sansevieria trifasciata', 'ornamental', 'La Sansevieria, también conocida como Lengua de Suegra o Planta Serpiente, es una planta perenne de interior muy resistente. Se caracteriza por sus hojas rígidas, erguidas y en forma de espada, con patrones variados en tonos verdes, amarillos y crema. Es apreciada por su belleza escultural y su fácil mantenimiento.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'SAN03L105', 0, '["interior", "resistente", "purificadora de aire", "suculenta", "poca luz", "decorativa", "popular"]', '["bolsa 3 litros", "bolsa 4 litros", "maceta negra 6 pulgadas", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144282/plantas/san03l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SAP06P009', 'Sapito', 'Maranta leuconeura', 'ornamental', 'La Maranta leuconeura, conocida como Planta Sapito, es una planta ornamental tropical originaria de Brasil. Se caracteriza por sus hojas ovaladas con patrones coloridos y su peculiar movimiento de plegarse por la noche.', 'luz indirecta', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SAP06P009', 0, '["planta de oración", "maranta", "hojas decorativas", "planta tropical", "interior", "fácil cuidado", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144299/plantas/sap06p009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SCO01L125', 'Salvia Comestible', 'Salvia officinalis', 'medicinal', 'La Salvia Comestible, o Salvia officinalis, es un subarbusto perenne aromático y comestible, con tallos leñosos y hojas de color verde grisáceo. Es originaria de la región mediterránea y produce flores de tonos azules a púrpuras. Se valora tanto por sus usos culinarios y medicinales como por su atractivo ornamental en jardines.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SCO01L125', 0, '["Hierba", "Aromática", "Culinaria", "Perenne", "Resistente a la sequía", "Exterior", "popular"]', '["bolsa 1 litros", "bolsa 2 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144319/plantas/sco01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SED06P003', 'Sedum  Reflexon', 'Sedum reflexum', 'suculenta', 'Es una suculenta perenne de bajo crecimiento y hábito rastrero, con hojas azul-verdosas en forma de aguja que se asemejan a las de un abeto. Produce flores amarillas brillantes en forma de estrella durante el verano. Es una planta resistente y de rápido crecimiento, ideal como cobertura del suelo.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SED06P003', 0, '["suculenta", "rastrera", "cobertura del suelo", "resistente a la sequía", "jardín de rocas", "fácil cuidado", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144336/plantas/sed06p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SEN10L009', 'Senna Alata', 'Senna alata', 'medicinal', 'Senna alata es un arbusto o pequeño árbol tropical de rápido crecimiento, que alcanza entre 1 y 4 metros de altura. Se distingue por sus llamativas espigas florales de color amarillo brillante, que se asemejan a velas, y sus grandes hojas pinnadas que se pliegan al anochecer. Es valorada tanto por su uso ornamental como por sus propiedades medicinales, especialmente antifúngicas y laxantes.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SEN10L009', 0, '["arbusto", "tropical", "flores amarillas", "medicinal", "ornamental", "antifúngico", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144358/plantas/sen10l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SLI45L105', 'Sangre Libaneza', 'Euphorbia cotinifolia', 'árbol', 'La Sangre Libanesa es un arbusto o árbol pequeño ornamental, conocido por sus llamativas hojas de color rojo cobrizo que permanecen así todo el año. Produce pequeñas flores de color amarillo crema. Su savia es tóxica y puede causar irritación al contacto.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'SLI45L105', 0, '["arbusto", "hojas rojas", "tropical", "ornamental", "fácil cuidado", "tóxica"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144404/plantas/sli45l105.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SLL15L077', 'Sauce Lloron', 'Salix babylonica L.', 'árbol', 'El Sauce Llorón es un árbol caducifolio originario de China, conocido por su elegante porte y sus largas ramas flexibles que cuelgan grácilmente hasta el suelo. Puede alcanzar hasta 20 metros de altura y sus hojas son lanceoladas, volviéndose amarillo dorado intenso en otoño.', 'sol directo', 'alto', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SLL15L077', 0, '["árbol", "caducifolio", "ornamental", "humedad", "riberas", "crecimiento rápido", "ramas colgantes", "exterior", "popular"]', '["bolsa 15 litros", "bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144424/plantas/sll15l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SNI45L009', 'Stirilitzia Nicolae', 'Strelitzia nicolai', 'ornamental', 'La Strelitzia nicolai es una planta grande y exuberante originaria de las regiones tropicales de Sudáfrica, que puede alcanzar hasta 10 metros de altura. Se caracteriza por sus grandes hojas de color gris verdoso, similares a las de un banano, dispuestas en forma de abanico, y sus distintivas flores de color azul intenso y blanco cremoso. Es apreciada por su aspecto tropical y su imponente tamaño.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'SNI45L009', 0, '["tropical", "hojas grandes", "ave del paraíso", "planta de interior", "planta de exterior", "árbol"]', '["bolsa 45 litros", "bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144443/plantas/sni45l009.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SOC04P126', 'Socialis', 'Ledebouria socialis', 'ornamental', 'La Ledebouria socialis es una pequeña planta bulbosa perenne, de 15 a 25 cm de altura, con bulbos en forma de lágrima que suelen crecer sobre el suelo. Sus hojas carnosas y lanceoladas son de color verde plateado con manchas verdes oscuras en el haz y púrpuras en el envés. Produce pequeñas flores verdosas o rosadas en espigas durante la primavera y el verano.', 'luz indirecta', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'SOC04P126', 0, '["bulbosa", "suculenta", "hojas variegadas", "fácil cuidado", "planta de interior"]', '["maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144462/plantas/soc04p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SPI03L153', 'Spirea Bca/Rosa', 'Spiraea japonica', 'ornamental', 'La Spiraea japonica es un arbusto caducifolio conocido por sus abundantes racimos de pequeñas flores que varían en tonos de blanco, rosa y rojo. Sus hojas ovaladas y dentadas proporcionan interés durante tres estaciones, a menudo con colores vibrantes en otoño. Es una planta ornamental popular por su fácil mantenimiento y su atractivo para los polinizadores.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SPI03L153', 0, '["arbusto", "flores rosas", "flores blancas", "caducifolio", "atractivo para mariposas", "fácil cuidado"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144481/plantas/spi03l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SPI06P006', 'Singonio', 'Syngonium podophyllum', 'ornamental', 'El Singonio (Syngonium podophyllum) es una planta trepadora de la familia Araceae, originaria de América Central y del Sur. Se caracteriza por sus hojas en forma de flecha, que pueden variar en color y patrón, a menudo con variegaciones en tonos verdes, blancos o rosados. Es una planta de interior popular por su belleza ornamental y su fácil mantenimiento.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'SPI06P006', 0, '["planta punta de flecha", "trepadora", "purificadora del aire", "hojas variegadas", "tropical", "fácil cuidado", "popular"]', '["maceta negra 6 pulgadas", "maceta negra 8 pulgadas", "bolsa 2 litros", "maceta negra 11 pulgadas", "maceta negra 5 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144386/plantas/spi06p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SPI10L153', 'Spirea Bca', 'Spiraea', 'ornamental', 'Las Spiraea son arbustos caducifolios muy populares, conocidos por sus abundantes racimos de pequeñas flores, a menudo blancas. Son plantas de bajo mantenimiento que ofrecen interés estacional con su follaje y floración. Se utilizan comúnmente en jardines ornamentales y paisajismo.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SPI10L153', 0, '["Arbusto", "Flores blancas", "Fácil cuidado", "Exterior", "Caducifolio", "Atrae polinizadores", "popular"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144512/plantas/spi10l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('SVI01L125', 'Siempre Viva', 'Sempervivum tectorum', 'suculenta', 'La Siempre Viva es una planta suculenta perenne que forma rosetas compactas de hojas carnosas, a menudo con puntas rojizas. Es muy resistente y produce hijuelos que forman densos grupos. Florece en verano con pequeñas flores de colores variados.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'SVI01L125', 0, '["roseta", "perenne", "resistente", "bajo mantenimiento", "exterior", "ornamental", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144545/plantas/svi01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAB04L129', 'Tabachin Silvestre', 'Caesalpinia pulcherrima', 'ornamental', 'El Tabachín Silvestre es un arbusto tropical que crece de forma espontánea, alcanzando hasta cinco metros de altura. Presenta un follaje verde ramificado con hojas pequeñas y ovaladas. Su floración es extraordinaria, con grandes espigas de flores rojas y amarillas muy vistosas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TAB04L129', 0, '["arbusto", "flores vistosas", "tropical", "exterior", "rápido crecimiento", "leguminosa", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144563/plantas/tab04l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAB60L003', 'Tabachin', 'Delonix regia', 'árbol', 'El Tabachín, o Flamboyán (Delonix regia), es un árbol caducifolio de 8 a 12 metros de altura, conocido por su copa ancha y aparasolada. Sus hojas son bipinnadas y produce espectaculares flores grandes de color rojo o naranja-rojizo, que a menudo aparecen cuando el árbol está sin follaje. Tras la floración, desarrolla largas vainas leñosas de color marrón oscuro.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TAB60L003', 0, '["árbol", "ornamental", "flamboyán", "árbol de fuego", "caducifolio", "flores rojas", "tropical", "sombra"]', '["bolsa 60 litros", "bolsa 7 litros", "bolsa 20 litros", "bolsa 30 litros", "bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144581/plantas/tab60l003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAF03L077', 'Tulipan Africano', 'Spathodea campanulata', 'árbol', 'El Tulipán Africano es un árbol de porte elegante, nativo de las zonas tropicales de África, que puede alcanzar hasta 25 metros de altura. Se distingue por sus grandes y abundantes flores de color anaranjado rojizo, en forma de campana, que se presentan en racimos terminales. Es una especie de crecimiento rápido, ampliamente utilizada como ornamental en regiones cálidas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TAF03L077', 0, '["árbol ornamental", "flores naranjas", "clima tropical", "crecimiento rápido", "árbol de sombra", "especie invasora"]', '["bolsa 3 litros", "bolsa 12 litros", "bolsa 40 litros", "bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144602/plantas/taf03l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAM04L010', 'Tamarindo', 'Tamarindus indica', 'árbol', 'El tamarindo es un árbol tropical de hoja perenne que puede alcanzar hasta 30 metros de altura, conocido por su crecimiento lento y longevidad. Produce vainas comestibles que contienen una pulpa agridulce de color marrón oscuro. Sus hojas son alternas y pinnadas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TAM04L010', 0, '["frutal", "tropical", "comestible", "árbol de sombra", "usos culinarios", "medicinal"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144618/plantas/tam04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAM30L125', 'Tamarix', 'Tamarix spp.', 'árbol', 'El género Tamarix, conocido como taray o tamarisco, agrupa arbustos y pequeños árboles nativos de Eurasia y África, que pueden alcanzar entre 1 y 15 metros de altura. Se caracterizan por sus ramas finas, follaje gris verdoso con hojas escamosas y pequeñas flores rosadas o blancas que aparecen en densas espigas. Son plantas extremadamente resistentes, adaptadas a suelos salinos y ambientes áridos, gracias a sus profundas raíces y su capacidad para excretar el exceso de sal.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TAM30L125', 0, '["arbusto", "ornamental", "resistente a la sequía", "tolerante a la salinidad", "cortavientos", "floración rosa"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144640/plantas/tam30l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TAR08L077', 'Trueno De Arbol', 'Ligustrum lucidum', 'árbol', 'El Trueno de Árbol es un árbol perenne que puede alcanzar hasta 15 metros de altura, caracterizado por sus hojas ovaladas, brillantes y de un verde intenso. Produce pequeñas flores blancas y aromáticas en racimos cónicos, seguidas de bayas oscuras que maduran en otoño.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TAR08L077', 0, '["ornamental", "perenne", "exterior", "flores blancas", "frutos", "resistente"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144658/plantas/tar08l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TEC20L129', 'Tecoma', 'Tecoma stans', 'ornamental', 'Es un arbusto o árbol pequeño, perenne, nativo de América, conocido por sus vistosas flores amarillas en forma de trompeta que florecen en racimos. Sus hojas son compuestas y produce frutos en forma de vainas alargadas.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TEC20L129', 0, '["árbol", "arbusto", "flores amarillas", "resistente a la sequía", "medicinal", "exterior", "popular"]', '["bolsa 20 litros", "bolsa 60 litros", "bolsa 12 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144706/plantas/tec20l129.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TEJ04L077', 'Tejocote', 'Crataegus mexicana', 'árbol', 'El tejocote (Crataegus mexicana) es un árbol o arbusto caducifolio nativo de México y Centroamérica, que puede alcanzar de 4 a 10 metros de altura y a menudo presenta espinas. Sus hojas son romboides y sus flores blancas. Produce frutos pequeños, redondos u ovalados, de color amarillo-anaranjado a rojo, con un sabor agridulce, que maduran a finales del invierno.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TEJ04L077', 0, '["frutal", "medicinal", "ornamental", "nativo de México", "resistente", "exterior"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144727/plantas/tej04l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TEL10P006', 'Telefono', 'Epipremnum aureum', 'interior', 'El ''Teléfono'' es una planta trepadora de hoja perenne, conocida por sus atractivas hojas en forma de corazón, que a menudo presentan variegaciones en tonos amarillos, blancos o verdes claros. En su hábitat natural, puede alcanzar grandes alturas trepando por los troncos de los árboles, mientras que en interiores se cultiva como planta colgante o trepadora con soporte. Es muy apreciada por su resistencia y facilidad de cuidado, lo que la convierte en una opción popular para principiantes.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TEL10P006', 0, '["planta de interior", "trepadora", "follaje variegado", "purificadora de aire", "fácil cuidado", "potos", "popular"]', '["maceta negra 10 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144745/plantas/tel10p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('THE80L145', 'Thevetia', 'Thevetia peruviana', 'árbol', 'La Thevetia peruviana es un arbusto o árbol pequeño de hoja perenne, originario de las regiones tropicales de América. Se caracteriza por sus hojas verdes brillantes y sus vistosas flores en forma de trompeta, generalmente de color amarillo o naranja claro, que florecen durante gran parte del año. Produce frutos carnosos que cambian de verde a negro al madurar.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'THE80L145', 0, '["ornamental", "tropical", "perenne", "tóxica", "arbusto", "flor amarilla"]', '["bolsa 80 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144767/plantas/the80l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('THI60L145', 'Tabebuia Hippie-1650 (Guayacan', 'Tabebuia guayacan', 'árbol', 'El Tabebuia guayacan es un árbol grande, nativo de América Central y del Sur, que puede alcanzar hasta 50 metros de altura. Es conocido por sus espectaculares flores amarillas en forma de trompeta que brotan en una corona completa antes de que aparezcan las hojas durante la estación seca. Su madera es muy dura y valorada, utilizada en construcción y carpintería, y también posee propiedades medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'THI60L145', 0, '["árbol tropical", "flores amarillas", "madera dura", "ornamental", "caducifolio", "medicinal"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144789/plantas/thi60l145.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TLI07L128', 'Te Limon', 'Cymbopogon citratus', 'medicinal', 'Es una hierba perenne tropical que crece en densos grupos, con hojas largas, delgadas y arqueadas de color verde claro que desprenden un fuerte aroma a limón al estrujarse. Se utiliza ampliamente en la cocina, la medicina tradicional y como planta ornamental.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TLI07L128', 0, '["hierba aromática", "culinaria", "medicinal", "tropical", "perenne", "repelente de insectos"]', '["bolsa 7 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144814/plantas/tli07l128.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TOR01L125', 'Toronjil', 'Melissa officinalis', 'medicinal', 'El toronjil, o Melissa officinalis, es una hierba perenne de la familia de la menta, conocida por sus hojas con un distintivo aroma a limón. Produce pequeñas flores blancas o rosadas y puede crecer hasta un metro de altura. Es ampliamente valorada por sus propiedades medicinales, especialmente como tranquilizante natural y para aliviar problemas digestivos.', 'media sombra', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TOR01L125', 0, '["medicinal", "aromática", "relajante", "digestiva", "ornamental", "atrae abejas", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144835/plantas/tor01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TOR10L013', 'Toronja Sangria', 'Citrus paradisi', 'árbol', 'La toronja Sangría es una variedad de pomelo (Citrus paradisi) caracterizada por su pulpa roja o rojo intenso, muy jugosa y aromática. Posee un sabor dulce-ácido con un ligero amargor típico de los cítricos y su cáscara suele ser rosada o rojiza.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'TOR10L013', 0, '["frutal", "cítrico", "árbol", "pulpa roja", "jugoso", "exterior"]', '["bolsa 10 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144851/plantas/tor10l013.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TPA10P006', 'Telefono Panda', 'Scindapsus pictus ''Argyraeus''', 'interior', 'El Teléfono Panda es una planta colgante y trepadora, apreciada por su elegante follaje decorativo. Sus hojas en forma de corazón combinan tonos verdes con vetas plateadas, creando un contraste natural. Es una planta resistente y de fácil cuidado, ideal para interiores.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TPA10P006', 0, '["planta colgante", "planta trepadora", "follaje decorativo", "interior", "fácil cuidado", "variegada", "popular"]', '["maceta negra 10 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144867/plantas/tpa10p006.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TRA10P003', 'Tradescantia', 'Tradescantia spp.', 'ornamental', 'Tradescantia es un género de plantas herbáceas perennes originarias del Nuevo Mundo, apreciadas por su atractivo follaje de colores variados y vibrantes. Son de crecimiento rápido y pueden presentar un hábito rastrero, colgante o erguido. Muchas de sus especies son populares como plantas ornamentales, tanto de interior como de exterior.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TRA10P003', 0, '["ornamental", "planta colgante", "fácil cuidado", "hojas coloridas", "interior", "exterior", "popular"]', '["maceta negra 10 pulgadas", "maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144681/plantas/tra10p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TTE03L112', 'Trueno Texano', 'Leucophyllum frutescens', 'exterior', 'El Trueno Texano es un arbusto de hoja perenne originario de Texas y el norte de México, conocido por su follaje gris plateado y sus vibrantes flores en forma de campana de color púrpura, lavanda o magenta. Florece de forma intermitente, a menudo después de las lluvias, y tiene un hábito de crecimiento compacto y redondeado.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'TTE03L112', 0, '["arbusto", "resistente a la sequía", "floración púrpura", "follaje plateado", "planta desértica", "bajo mantenimiento"]', '["bolsa 3 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144883/plantas/tte03l112.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TUL04L010', 'Tulipan Arcoiris', 'Tulipa spp.', 'ornamental', 'Los tulipanes ''Arcoíris'' son variedades cultivadas o arreglos florales que exhiben una deslumbrante gama de colores en sus pétalos, a menudo combinando tonos de rojo, amarillo, verde y morado. Su forma y colores vibrantes los hacen muy apreciados como flores ornamentales. Florecen en primavera, añadiendo un toque espectacular a jardines y arreglos.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TUL04L010', 0, '["flor", "bulbosa", "primavera", "colores vibrantes", "jardín", "ornamental", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144903/plantas/tul04l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TUL04L164', 'Tulipan', 'Tulipa spp.', 'ornamental', 'El tulipán (Tulipa spp.) es una planta bulbosa perenne de la familia Liliaceae, originaria de Asia Central. Es ampliamente valorada por sus espectaculares y vistosas flores, que presentan una gran diversidad de formas y colores vibrantes. Se cultiva comúnmente tanto en jardines como en interiores para fines ornamentales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TUL04L164', 0, '["flor", "bulbosa", "primavera", "jardín", "decoración", "colores vibrantes", "popular"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144923/plantas/tul04l164.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TUL20L132', 'Tulia', 'Platycladus orientalis', 'ornamental', 'La Tulia, también conocida como Tuya asiática, es un arbusto o árbol conífero perenne de hasta 12 metros de altura, con una copa piramidal y ramas aplanadas. Sus hojas escamiformes son de un vistoso color verde claro, que pueden adquirir tonos marrones en invierno. Produce flores masculinas y femeninas en el mismo ejemplar.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TUL20L132', 0, '["conífera", "seto", "árbol ornamental", "perenne", "árbol de la vida", "tuya"]', '["bolsa 20 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144954/plantas/tul20l132.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TUL30L013', 'Tulia Dorada', 'Platycladus orientalis', 'árbol', 'La Tulia Dorada, también conocida como Tuya Oriental, es una conífera perenne de crecimiento lento que puede alcanzar hasta 12 metros de altura. Se caracteriza por su follaje escamoso de color verde amarillento o dorado, especialmente en los bordes de las hojas, y su forma cónica. Es muy apreciada en jardinería por su valor ornamental y su capacidad para formar setos.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'TUL30L013', 0, '["conífera", "exterior", "follaje dorado", "seto", "crecimiento lento", "ornamental"]', '["bolsa 30 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144978/plantas/tul30l013.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('TUL60L170', 'Tulipan De La India Ama', 'Spathodea campanulata', 'árbol', 'El Tulipán de la India, cuyo nombre científico es Spathodea campanulata, es un árbol grande y de rápido crecimiento originario de los bosques tropicales de África. Se caracteriza por sus vistosas flores campanuladas de color naranja rojizo, que emergen en densos racimos. Es ampliamente cultivado como ornamental, aunque es considerado una especie invasora en muchas regiones tropicales.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'TUL60L170', 0, '["árbol", "ornamental", "flores naranjas", "tropical", "invasora", "floración abundante"]', '["bolsa 60 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777144999/plantas/tul60l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('USE06P127', 'Uña De Señorita', 'Sempervivum calcareum', 'suculenta', 'La Uña de Señorita es una suculenta perenne que forma rosetas compactas con hojas gruesas de color verde grisáceo y puntas rojizas. Cada roseta alcanza entre 5 y 10 cm de diámetro y florece una vez en su vida, tras lo cual la roseta madre muere.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'USE06P127', 0, '["suculenta", "roseta", "exterior", "resistente", "bajo mantenimiento", "planta de roca", "popular"]', '["maceta negra 6 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145024/plantas/use06p127.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('UVA08L077', 'Uva De Mar', 'Coccoloba uvifera', 'árbol', 'La Uva de Mar (Coccoloba uvifera) es un árbol o arbusto perennifolio nativo de las playas costeras de América tropical y el Caribe. Se caracteriza por sus grandes hojas redondeadas y coriáceas, a menudo con nervaduras rojizas, y produce racimos de pequeños frutos comestibles de color púrpura que se asemejan a las uvas. Esta especie es valorada por su uso ornamental, su capacidad para estabilizar dunas y sus propiedades medicinales.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'UVA08L077', 0, '["comestible", "costera", "rompevientos", "tropical", "medicinal", "ornamental", "popular"]', '["bolsa 8 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145049/plantas/uva08l077.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VAF04P003', 'Violeta Africana', 'Saintpaulia ionantha', 'interior', 'La violeta africana es una planta herbácea perenne de pequeño tamaño, con hojas carnosas, vellosas y de color verde oscuro que forman una roseta. Produce pequeñas flores aterciopeladas en una amplia gama de colores como violeta, azul, blanco y rosa, floreciendo varias veces al año.', 'luz indirecta', 'medio', 'intermedio', 'disponible', 'ambas', 'no tóxica', 'VAF04P003', 0, '["planta de interior", "floración anual", "hojas vellosas", "flores coloridas", "fácil de cuidar", "no tóxica para mascotas", "popular"]', '["maceta negra 4 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145095/plantas/vaf04p003.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VAL10L153', 'Valeriana', 'Valeriana officinalis L.', 'medicinal', 'La valeriana es una planta herbácea perenne, nativa de Europa y Asia, que puede alcanzar hasta 1.5-2 metros de altura. Se caracteriza por su tallo erecto, hojas pinnadas y pequeñas flores de color rosa pálido o blanco agrupadas en corimbos terminales. Es ampliamente reconocida por las propiedades medicinales de sus raíces.', 'luz indirecta', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'VAL10L153', 0, '["medicinal", "relajante", "ansiolítica", "insomnio", "hierba", "perenne"]', '["bolsa 10 litros", "bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145115/plantas/val10l153.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VER01L124', 'Veronica Morada', 'Veronica spp.', 'ornamental', 'Las verónicas moradas son plantas herbáceas perennes conocidas por sus atractivas espigas de flores de color violeta a púrpura. Florecen desde finales de primavera hasta bien entrado el verano, aportando un vibrante color al jardín. Suelen crecer en forma de matas o con un porte erguido.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'VER01L124', 0, '["perenne", "flores moradas", "jardín", "ornamental", "atrae polinizadores", "fácil cuidado", "popular"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145134/plantas/ver01l124.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VER01L125', 'Verbena', 'Verbena', 'ornamental', 'La verbena es un género de plantas herbáceas o semileñosas, anuales o perennes, que incluye alrededor de 250 especies. Se caracteriza por sus tallos cuadrangulares y sus pequeñas flores agrupadas en espigas, que pueden ser de diversos colores como azul, púrpura, lila, rosa, rojo o blanco. Es apreciada tanto por su valor ornamental en jardines y macetas como por sus reconocidas propiedades medicinales.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'VER01L125', 0, '["flores", "jardín", "medicinal", "resistente", "atrae polinizadores", "perenne"]', '["bolsa 1 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145161/plantas/ver01l125.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VIT10L010', 'Vitex', 'Vitex agnus-castus', 'medicinal', 'El Vitex agnus-castus, también conocido como sauzgatillo o árbol casto, es un arbusto o pequeño árbol aromático de hoja caduca, originario del Mediterráneo y Asia. Produce vistosas espigas de flores de color lavanda, azul o blanco que atraen a los polinizadores. Sus frutos y hojas se han utilizado tradicionalmente en la medicina herbal para tratar desequilibrios hormonales femeninos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'VIT10L010', 0, '["Sauzgatillo", "Árbol casto", "Arbusto", "Mediterráneo", "Hormonal", "Ornamental", "popular"]', '["bolsa 10 litros", "bolsa 2 litros", "bolsa 20 litros", "bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145076/plantas/vit10l010.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('VRE03P126', 'Vampire Red', 'Echeveria ''Vampire Red Ball''', 'suculenta', 'Esta Echeveria presenta impresionantes gradientes de rosa, oliva y amarillo, formando una roseta multicolor. Sus hojas anchas y puntiagudas, dispuestas en una roseta aplanada, le dan una forma inusual para una Echeveria. Es una planta suculenta muy atractiva.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'no tóxica', 'VRE03P126', 0, '["suculenta", "roseta", "colores vibrantes", "fácil cuidado", "exterior", "interior"]', '["maceta negra 3 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145198/plantas/vre03p126.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('WIS12P130', 'Wisteria', 'Wisteria spp.', 'exterior', 'Wisteria es un género de plantas trepadoras leñosas, conocidas popularmente como glicina o glicinia, que produce vistosos racimos colgantes de flores perfumadas en primavera. Es una planta robusta y de crecimiento vigoroso, ideal para cubrir pérgolas, muros y arcos en jardines. Sus flores pueden ser violetas, azules o blancas, y es apreciada por su valor ornamental.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'WIS12P130', 0, '["trepadora", "ornamental", "floración primaveral", "caducifolia", "vigorosa", "tóxica"]', '["maceta negra 12 pulgadas"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145216/plantas/wis12p130.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('YUC15L170', 'Yuca', 'Yucca spp.', 'ornamental', 'La Yuca es un género de plantas suculentas perennes, caracterizadas por sus rosetas de hojas rígidas en forma de espada que crecen sobre tallos leñosos. Originarias de Norte y Centroamérica, son apreciadas por su aspecto exótico y su resistencia, pudiendo producir racimos de flores blancas o crema.', 'sol directo', 'bajo', 'fácil', 'disponible', 'ambas', 'tóxica', 'YUC15L170', 0, '["ornamental", "resistente", "bajo mantenimiento", "hojas perennes", "exterior", "interior"]', '["bolsa 15 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145238/plantas/yuc15l170.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ZAM45L152', 'Zapote Amarillo', 'Pouteria campechiana', 'árbol', 'El Zapote Amarillo es un árbol perennifolio originario de Mesoamérica, conocido por sus frutos de pulpa dulce y cremosa de color amarillo anaranjado. Su textura se compara a menudo con la de una yema de huevo cocida. Puede alcanzar hasta 15 metros de altura.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'tóxica', 'ZAM45L152', 0, '["frutal", "tropical", "árbol perenne", "Pouteria", "canistel", "fruta de huevo"]', '["bolsa 45 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145256/plantas/zam45l152.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ZAP04L115', 'Zapote Negro', 'Diospyros nigra', 'árbol', 'El Zapote Negro es un árbol frutal tropical de hoja perenne, nativo de México y Centroamérica, que puede alcanzar hasta 25 metros de altura. Sus frutos, de piel verde, desarrollan una pulpa casi negra con una textura y sabor similar al pudín de chocolate cuando están maduros. Es apreciado por su fruta exótica y su valor ornamental.', 'sol directo', 'medio', 'intermedio', 'disponible', 'ambas', 'tóxica', 'ZAP04L115', 0, '["árbol frutal", "tropical", "fruta exótica", "Diospyros", "Ebenaceae", "pudín de chocolate"]', '["bolsa 4 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145274/plantas/zap04l115.png"]');
INSERT INTO plantas (id, nombre, nombre_cientifico, categoria, descripcion, luz, riego, cuidado, disponibilidad, sucursal, mascotas, sku, vistas, etiquetas, variaciones, imagenes) VALUES ('ZAR05L130', 'Zarzamora', 'Rubus fruticosus', 'exterior', 'La zarzamora es un arbusto perenne y espinoso, conocido por sus tallos largos y flexibles que pueden crecer vigorosamente. Produce flores blancas o rosadas que dan lugar a frutos comestibles llamados moras, que son bayas negras, dulces y aromáticas. Es una planta adaptable que se encuentra tanto de forma silvestre como cultivada en jardines y huertos.', 'sol directo', 'medio', 'fácil', 'disponible', 'ambas', 'no tóxica', 'ZAR05L130', 0, '["arbusto", "frutal", "silvestre", "espinosa", "moras", "medicinal", "popular"]', '["bolsa 5 litros"]', '["https://res.cloudinary.com/dfigwymjb/image/upload/v1777145298/plantas/zar05l130.png"]');
